INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('k-1-world-gp---zettai-ouja-ikusei-keikaku-japan', 'NDS', 'K-1 World GP - Zettai Ouja Ikusei Keikaku (Japan)', '2007', 'Sports', 'Spike', '1', 'CombatSports', 'Sports and Simulation.', 'Train your fighter to become the K-1 World Grand Prix champion.', 'A deep kickboxing management and fighting sim.', 'K-1 World GP on NDS focuses on the "Zettai Ouja" training system. Manage your athlete''s diet, training, and strategy to win the toughest combat sports tournament in the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('k11---kommissare-im-einsatz-germany', 'NDS', 'K11 - Kommissare im Einsatz (Germany)', '2008', 'Adventure', 'DTF Games', '1', 'DetectiveAdventure', 'Mystery adventure.', 'Solve criminal cases alongside the famous German TV detectives.', 'A crime-solving adventure based on the K11 series.', 'K11 - Kommissare im Einsatz tasks you with investigating crime scenes. Collect evidence, interview witnesses, and help the detectives close the case in this interactive thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('k3-en-het-ijsprinsesje-netherlands', 'NDS', 'K3 en het IJsprinsesje (Netherlands)', '2009', 'Adventure', 'Unknown', '1', 'KidsAdventure', 'Adventure and Social.', 'Help the K3 girls on their journey to save the Ice Princess.', 'A charming adventure based on the popular Belgian pop group.', 'K3 en het IJsprinsesje on NDS features mini-games, puzzles, and a magical story. Help Karen, Kristel, and Josje through various challenges in this fun game for younger fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kabu-trader-shun-japan', 'NDS', 'Kabu Trader Shun (Japan)', '2007', 'Simulation', 'Artdink', '1', 'StockTradingSimulation', 'Adventure and Simulation.', 'Navigate the stock market and solve business mysteries.', 'A unique "Stock Trading" adventure game from Capcom.', 'Kabu Trader Shun combines financial simulation with a dramatic story. Use your trading skills to manipulate stocks and outsmart rivals in a high-stakes corporate world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kabushiki-baibai-trainer---kabutore!-japan', 'NDS', 'Kabushiki Baibai Trainer - Kabutore! (Japan)', '2007', 'Simulation', 'Artdink', '1', 'StockTradingSimulation', 'Educational and Simulation.', 'Learn the basics of stock market trading in Japan.', 'A realistic financial trainer and trading simulator.', 'Kabutore! on NDS uses real historical stock data. Practice buying and selling stocks in a safe digital environment to learn the mechanics of the Tokyo Stock Exchange.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kabushiki-baibai-trainer---kabutore!-next-japan', 'NDS', 'Kabushiki Baibai Trainer - Kabutore! Next (Japan)', '2009', 'Simulation', 'Artdink', '1', 'StockTradingSimulation', 'Educational and Simulation.', 'Master advanced stock trading techniques and strategies.', 'The sequel to the popular financial trading trainer.', 'Kabutore! Next offers updated market tools and more complex scenarios. It’s an essential tool for anyone wanting to learn about Japanese investment through interactive simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kachou-shima-kosaku-ds---dekiru-otoko-no-love-&-success-japan', 'NDS', 'Kachou Shima Kosaku DS - Dekiru Otoko no Love & Success (Japan)', '2008', 'Simulation', 'Bandai Namco', '1', 'LifeSimulation', 'Social Sim / Adventure.', 'Manage Shima Kosaku''s career and romantic life.', 'A professional and romantic simulation based on the famous manga.', 'Kachou Shima Kosaku DS follows the life of a Japanese salaryman. Make critical business decisions and navigate social relationships to climb the corporate ladder.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kage-no-densetsu---the-legend-of-kage-2-japan', 'NDS', 'Kage no Densetsu - The Legend of Kage 2 (Japan)', '2008', 'Action', 'Natsume', '1', 'ActionPlatformer', 'Action-platformer.', 'Defeat the ninja clan and rescue Princess Yuki.', 'A modern sequel to the legendary Taito arcade classic.', 'The Legend of Kage 2 on NDS features fast-paced ninja action. Play as Kage or Chihiro, using vertical movement and elemental magic to slash through hordes of enemies in beautiful 2D.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kageyama-hideo-no-hanpuku-ondoku---ds-eigo---shougaku-eigo-hisshuu-drill-japan', 'NDS', 'Kageyama Hideo no Hanpuku Ondoku - DS Eigo - Shougaku Eigo Hisshuu Drill (Japan)', '2008', 'Education', 'Bandai Namco', '1', 'EnglishLearning', 'Educational and Language.', 'Practice English reading and pronunciation for elementary school.', 'A structured English trainer based on the Kageyama method.', 'DS Eigo focuses on repetitive oral reading to build fluency. Using the NDS microphone, students can practice essential English vocabulary and sentences in a fun, effective way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kageyama-hideo-no-iq-teacher-ds---kangaeru-chikara-to-oboeru-chikara-japan', 'NDS', 'Kageyama Hideo no IQ Teacher DS - Kangaeru Chikara to Oboeru Chikara (Japan)', '2009', 'Education', 'Bandai Namco', '1', 'BrainTraining', 'Educational / Brain Training.', 'Improve your IQ through logic and memory exercises.', 'A mental training program focused on "Thinking Power."', 'IQ Teacher DS offers a series of challenges designed to expand your cognitive limits. Track your daily progress and unlock new levels as your mental agility improves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaidan-restaurant---ura-menu-100-sen-japan', 'NDS', 'Kaidan Restaurant - Ura Menu 100-sen (Japan)', '2009', 'Adventure', 'Bandai Namco', '1', 'HorrorAdventure', 'Visual Novel / Horror.', 'Read 100 scary stories from the "Spooky Restaurant."', 'An interactive anthology of Japanese ghost stories.', 'Kaidan Restaurant on NDS features a massive collection of urban legends. Choose your "menu" of horror stories and experience them with atmospheric sound and art on the dual screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaijuu-busters-japan', 'NDS', 'Kaijuu Busters (Japan)', '2009', 'Action', 'Bandai Namco', '4', 'ActionHunting', 'Action / Hunting.', 'Hunt down massive space monsters to protect the galaxy.', 'A sci-fi monster-hunting game similar to Monster Hunter.', 'Kaijuu Busters on NDS puts you in the shoes of a cosmic hunter. Craft gear from fallen foes, team up with friends, and take down giant Kaiju across various alien planets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaijuu-busters-powered-japan', 'NDS', 'Kaijuu Busters Powered (Japan)', '2010', 'Action', 'Bandai Namco', '4', 'ActionHunting', 'Action / Hunting.', 'Battle even stronger monsters with new weapons and missions.', 'The "Powered" and expanded version of the Kaijuu Busters.', 'Kaijuu Busters Powered features more monsters, improved graphics, and expanded multiplayer. It''s the definitive experience for space-monster hunters on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaite-oboeru---doragana-japan', 'NDS', 'Kaite Oboeru - Doragana (Japan)', '2008', 'Education', 'Success', '1', 'WritingTraining', 'Educational and Language.', 'Learn to write Hiragana and Katakana through tracing.', 'A simple and effective writing trainer for young children.', 'Kaite Oboeru: Doragana makes learning Japanese characters easy. Use the stylus to follow guides, play letter-based mini-games, and build a strong foundation for reading and writing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaite-shabette-hajimeyou!---monster-farm-ds-japan', 'NDS', 'Kaite, Shabette, Hajimeyou! - Monster Farm DS (Japan)', '2008', 'Simulation', 'Tecmo', '1', 'MonsterRaising', 'Simulation / RPG.', 'Draw and talk to create and train your own monsters.', 'A creative spin-off of the Monster Farm (Monster Rancher) series.', 'Kaite, Shabette, Hajimeyou! lets you generate monsters by drawing on the screen or using the microphone. Train your unique creations and battle them against others in this fun RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaitou-rousseau-japan', 'NDS', 'Kaitou Rousseau (Japan)', '2009', 'Adventure', 'Unknown', '1', 'PhantomThiefAdventure', 'Adventure / Puzzle.', 'Use the power of drawing to solve mysteries and "morph."', 'A unique and artistic adventure game from Konami.', 'Kaitou Rousseau features a hero who can transform into anything he draws. Use the stylus to solve environmental puzzles and outmaneuver the police in this stylish and clever title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaitou-wario-the-seven-japan', 'NDS', 'Kaitou Wario the Seven (Japan)', '2006', 'Action', 'Intelligent Systems', '1', 'PuzzlePlatformer', 'Action-platformer.', 'Swap between seven different disguises to solve puzzles.', 'A creative platforming quest starring the greedy Wario.', 'Wario: Master of Disguise on NDS lets you use the stylus to draw costumes. Turn into a thief, a scientist, or a spark to gain new powers and steal treasures across the globe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakikomi-shiki---hannya-shingyou-renshuuchou-ds-japan', 'NDS', 'Kakikomi Shiki - ''Hannya Shingyou'' Renshuuchou DS (Japan)', '2008', 'Education', 'Success', '1', 'WritingPractice', 'Calligraphy.', 'Practice and copy the Heart Sutra with the stylus.', 'A digital Zen calligraphy workbook for the NDS.', 'Hannya Shingyou Renshuuchou DS lets you practice traditional sutra copying. Improve your handwriting and focus while learning the sacred Buddhist text in a meditative digital environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakko-yoku-narou---kaku-chan-shiki---kintore-navi-japan', 'NDS', 'Kakko Yoku Narou - Kaku-chan Shiki - Kintore Navi (Japan)', '2009', 'Education', 'Success', '1', 'FitnessTraining', 'Fitness.', 'Follow Kaku-chan''s routines to build muscle and fitness.', 'A personal training and muscle-building guide.', 'Kintore Navi on NDS provides structured workout plans. Follow animated guides for strength training and track your physical progress with advice from fitness expert Kaku-chan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakuromaniacs-europe-enfrdeesit', 'NDS', 'Kakuromaniacs (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Codemasters', '1', 'LogicPuzzle', 'Logic puzzle.', 'Fill the grids with numbers based on Kakuro rules.', 'A massive collection of addictive Kakuro puzzles.', 'Kakuromaniacs on NDS offers hundreds of cross-sum puzzles. Perfect for Sudoku fans, this game tests your math and logic across various difficulty levels and grid sizes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakushi-e-mystery---riku-to-yohan---kieta-2-mai-no-e-japan', 'NDS', 'Kakushi E Mystery - Riku to Yohan - Kieta 2-mai no E (Japan)', '2008', 'Adventure', 'Success', '1', 'MysteryAdventure', 'Hidden object.', 'Find hidden pictures and solve the art mystery.', 'A charming illustrated hidden-picture adventure.', 'Kakushi E Mystery: Riku to Yohan follows the story of two children searching for lost paintings. Use the stylus to find cleverly hidden objects within beautiful hand-drawn scenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kalle-kunskap---4-7-aar-europe-svnodafi', 'NDS', 'Kalle Kunskap - 4-7 Aar (Europe) (Sv,No,Da,Fi)', '2007', 'Education', 'Krea Medie', '1', 'EarlyLearning', 'Educational.', 'Complete fun activities to develop preschool skills.', 'A Nordic educational game for children aged 4-7.', 'Kalle Kunskap on NDS features a variety of mini-games focused on early learning. Help kids develop logic, vocabulary, and basic math skills through interactive storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kameleon-europe', 'NDS', 'Kameleon (Europe)', '2006', 'Puzzle', '9Lives', '1', 'ActionPuzzle', 'Puzzle.', 'Match colored stones to clear the board.', 'A simple and addictive tile-matching puzzle game.', 'Kameleon on NDS tasks you with matching colors to advance through levels. It''s a perfect casual title for quick gaming sessions, featuring bright graphics and intuitive touch controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider---dragon-knight-usa-enfres', 'NDS', 'Kamen Rider - Dragon Knight (USA) (En,Fr,Es)', '2009', 'Action', 'Eighting', '2', 'HeroAction', 'Fighting.', 'Defeat the forces of Xaviax using Rider powers.', 'A high-action fighter based on the American Kamen Rider show.', 'Kamen Rider: Dragon Knight on NDS lets you play as multiple riders. Use the "Advent Card" system to summon weapons and perform powerful finishers in intense 2D battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider-battle---ganbaride---card-battle-taisen-japan', 'NDS', 'Kamen Rider Battle - GanbaRide - Card Battle Taisen (Japan)', '2009', 'Action', 'Bandai Namco', '2', 'CardBattle', 'Card Battle.', 'Build a deck and win the Ganbaride tournament.', 'A strategic card-battle game based on the Kamen Rider series.', 'Kamen Rider Battle: GanbaRide features over 700 cards. Build your ultimate team of heroes and use the touch screen to execute tactical moves and cinematic attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamonohashikamo---aimai-seikatsu-no-susume-japan', 'NDS', 'Kamonohashikamo. - Aimai Seikatsu no Susume (Japan)', '2007', 'Simulation', 'Success', '1', 'LifeSimulation', 'Virtual Pet.', 'Live a relaxed daily life with the platypus Kamonohashikamo.', 'A cute and quirky life simulation with a unique pet.', 'Kamonohashikamo on NDS focuses on "ambiguous living." Interact with your platypus friend, play mini-games, and enjoy a slow-paced, humorous lifestyle simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kanbayashi-shiki-nouryoku-kaihatsu-hou---unou-kids-ds-japan', 'NDS', 'Kanbayashi Shiki Nouryoku Kaihatsu Hou - Unou Kids DS (Japan)', '2008', 'Education', 'Benesse', '1', 'BrainTraining', 'Educational.', 'Develop right-brain skills in children through fun games.', 'A specialized right-brain training program for kids.', 'Unou Kids DS features visual and spatial exercises designed to boost creativity and intuition. It''s a fun way for children to sharpen their mental faculties on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kangaeru-chikara-o-gun-gun-nobasu!---ds-youji-no-noutore-japan', 'NDS', 'Kangaeru Chikara o Gun Gun Nobasu! - DS Youji no Noutore (Japan)', '2009', 'Education', 'Benesse', '1', 'BrainTraining', 'Educational.', 'Improve cognitive abilities through daily brain training.', 'A brain-boosting game designed for young children.', 'DS Youji no Noutore offers age-appropriate puzzles to help toddlers develop memory and concentration skills through simple touch-screen interactions and bright visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kanji-no-wataridori-japan', 'NDS', 'Kanji no Wataridori (Japan)', '2007', 'Education', 'Nintendo', '1', 'KanjiLearning', 'Puzzle/Educational.', 'Solve Kanji puzzles to advance through the story.', 'A unique adventure game themed around Kanji characters.', 'Kanji no Wataridori turns learning into an adventure. Solve writing puzzles and word challenges to help the protagonist navigate a world built out of Japanese characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kanji-no-wataridori-japan-rev-1', 'NDS', 'Kanji no Wataridori (Japan) (Rev 1)', '2007', 'Education', 'Nintendo', '1', 'KanjiLearning', 'Puzzle/Educational.', 'Solve Kanji puzzles to advance through the story.', 'A unique adventure game themed around Kanji characters.', 'Kanji no Wataridori turns learning into an adventure. Solve writing puzzles and word challenges to help the protagonist navigate a world built out of Japanese characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kanji-sonomama---ds-rakubiki-jiten-japan', 'NDS', 'Kanji Sonomama - DS Rakubiki Jiten (Japan)', '2006', 'Education', 'Nintendo', '1', 'DictionaryReference', 'Dictionary/Utility.', 'Look up kanji and words using handwriting recognition.', 'A powerful Japanese-to-Japanese and English dictionary.', 'DS Rakubiki Jiten on NDS is a professional-grade reference tool. Use the stylus to write kanji you don''t know and get instant definitions, making it essential for students.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kankyou-jidai-no-koushiki-kentei---eco-kentei-ds---tokyo-shoukou-kaigisho-kanshuu-japan', 'NDS', 'Kankyou Jidai no Koushiki Kentei - Eco Kentei DS - Tokyo Shoukou Kaigisho Kanshuu (Japan)', '2008', 'Education', 'Success', '1', 'EcoEducation', 'Educational.', 'Pass the Eco Test by learning about the environment.', 'A comprehensive guide to environmental knowledge and certification.', 'Eco Kentei DS prepares you for the official ecology exam. Learn about climate change, recycling, and sustainability through quizzes and interactive lessons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kanshuu---shuukan-pro-wrestling---pro-wrestling-kentei-ds-japan', 'NDS', 'Kanshuu - Shuukan Pro Wrestling - Pro Wrestling Kentei DS (Japan)', '2009', 'Sports', 'Yuke''s', '1', 'WrestlingQuiz', 'Trivia/Quiz.', 'Test your knowledge of Japanese professional wrestling history.', 'A deep trivia game for hardcore wrestling fans.', 'Pro Wrestling Kentei DS features thousands of questions about the legends, moves, and history of Japanese wrestling. Prove you''re the ultimate fan by passing the exam!');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kanshuu-nihon-joushiki-ryoku-kentei-kyoukai---imasara-hito-ni-wa-kikenai---otona-no-joushiki-ryoku-training-ds-japan', 'NDS', 'Kanshuu Nihon Joushiki Ryoku Kentei Kyoukai - Imasara Hito ni wa Kikenai - Otona no Joushiki Ryoku Training DS (Japan)', '2008', 'Education', 'Success', '1', 'CommonSenseTraining', 'Educational.', 'Train in adult etiquette and common knowledge.', 'A popular "Common Sense" trainer for the modern adult.', 'Otona no Joushiki Ryoku Training helps you master social manners, history, and culture. Use daily tests to ensure you''re up to date on the general knowledge expected in society.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kanshuu-nihon-joushiki-ryoku-kentei-kyoukai---imasara-hito-ni-wa-kikenai---otona-no-joushiki-ryoku-training-ds-japan-rev-1', 'NDS', 'Kanshuu Nihon Joushiki Ryoku Kentei Kyoukai - Imasara Hito ni wa Kikenai - Otona no Joushiki Ryoku Training DS (Japan) (Rev 1)', '2008', 'Education', 'Success', '1', 'CommonSenseTraining', 'Educational.', 'Train in adult etiquette and common knowledge.', 'A popular "Common Sense" trainer for the modern adult.', 'Otona no Joushiki Ryoku Training helps you master social manners, history, and culture. Use daily tests to ensure you''re up to date on the general knowledge expected in society.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kantan!-tanoshii!---okashi-navi-ds-japan', 'NDS', 'Kantan! Tanoshii! - Okashi Navi DS (Japan)', '2009', 'Education', 'Success', '1', 'CookingGuide', 'Cooking/Utility.', 'Learn to make delicious Japanese sweets and snacks.', 'A step-by-step interactive guide to making pastries.', 'Okashi Navi DS offers dozens of dessert recipes. Follow voice-guided instructions and visual aids to bake perfect cakes and cookies in your own kitchen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karada-yorokobu-shokuji-&-exercise---kenkou-kentei-japan', 'NDS', 'Karada, Yorokobu Shokuji & Exercise - Kenkou Kentei (Japan)', '2009', 'Education', 'Success', '1', 'HealthTraining', 'Health/Fitness.', 'Improve your health through diet and exercise plans.', 'A wellness simulator focused on a healthy lifestyle.', 'Karada Yorokobu provides health quizzes and activity logs. Learn about nutrition and follow simple exercise routines to improve your daily well-being and fitness levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karasawa-shunichi-no-zettai-ni-ukeru!!---zatsugakuen-ds-japan', 'NDS', 'Karasawa Shunichi no Zettai ni Ukeru!! - Zatsugakuen DS (Japan)', '2008', 'Education', 'Success', '1', 'TriviaQuiz', 'Trivia/Quiz.', 'Learn fascinating facts and "useless" knowledge.', 'A trivia collection based on Shunichi Karasawa''s work.', 'Zatsugakuen DS features a massive library of interesting tidbits. From history to science, impress your friends with weird and wonderful facts learned through fun quizzes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaseki-chou-shinka---spectrobes-japan', 'NDS', 'Kaseki Chou Shinka - Spectrobes (Japan)', '2007', 'Action', 'Jupiter', '1', 'ActionRPG', 'Monster RPG.', 'Excavate, awaken, and battle mysterious fossil creatures.', 'A deep monster-collection RPG with fossil digging.', 'Spectrobes on NDS lets you play as Rallen. Use the touch screen to carefully excavate fossils, awaken them with your voice, and battle the evil Krawl in real-time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katei-de-dekiru!-chomeijin-yuumei-ryourinin-no-original-recipe---shokusai-roman-japan', 'NDS', 'Katei de Dekiru! Chomeijin Yuumei Ryourinin no Original Recipe - Shokusai Roman (Japan)', '2008', 'Simulation', 'Success', '1', 'CookingSimulation', 'Cooking/Utility.', 'Master original recipes from world-famous celebrity chefs.', 'A high-end digital cookbook for gourmet cooking.', 'Shokusai Roman features recipes from renowned culinary experts. Follow detailed guides and learn professional techniques to create restaurant-quality meals at home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---fate-of-heat---honoo-no-sadame-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Fate of Heat - Honoo no Sadame (Japan)', '2007', 'Action', 'Marvelous', '2', 'AnimeAction', 'RPG.', 'Lead Tsuna and the Vongola family in an epic adventure.', 'A story-driven RPG based on the Hitman Reborn anime.', 'Fate of Heat on NDS features turn-based combat and a branching narrative. Train your guardians and protect the Vongola legacy in this faithful anime adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---fate-of-heat-ii---unmei-no-futari-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Fate of Heat II - Unmei no Futari (Japan)', '2008', 'Action', 'Marvelous', '2', 'AnimeAction', 'RPG.', 'Continue the Vongola legacy with even more guardians.', 'The expanded sequel to the Hitman Reborn RPG series.', 'Fate of Heat II introduces more characters and refined combat mechanics. Follow the Vongola family''s journey and master powerful flame-based attacks to defeat rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---fate-of-heat-iii---yuki-no-shugosha-raishuu!-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Fate of Heat III - Yuki no Shugosha Raishuu! (Japan)', '2009', 'Action', 'Marvelous', '2', 'AnimeAction', 'RPG.', 'Face the Snow Guardians in the final chapter of the trilogy.', 'The dramatic conclusion to the Fate of Heat RPG saga.', 'Fate of Heat III features the most characters in the series. Engage in intense tactical battles and experience the climax of the story on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---flame-rumble---kaien-ring-soudatsusen!-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Flame Rumble - Kaien Ring Soudatsusen! (Japan)', '2007', 'Fighting', 'Marvelous', '2', 'AnimeFighting', 'Fighting.', 'Battle rivals to win the Vongola Ring tournament.', 'A fast-paced 2D fighter with anime-style combat.', 'Flame Rumble: Kaien Ring on NDS features intense one-on-one battles. Use special flame moves and assist characters to dominate the arena and claim the rings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---flame-rumble---mukuro-kyoushuu!-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Flame Rumble - Mukuro Kyoushuu! (Japan)', '2007', 'Fighting', 'Marvelous', '2', 'AnimeFighting', 'Fighting.', 'Stop Mukuro''s attack and protect the Mafia world.', 'A high-energy fighting game based on the early anime arcs.', 'Flame Rumble: Mukuro Kyoushuu features a variety of playable characters. Master the Dying Will flame and unleash powerful combos in this action-packed fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---flame-rumble-hyper---moeyo-mirai-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Flame Rumble Hyper - Moeyo Mirai (Japan)', '2008', 'Fighting', 'Marvelous', '2', 'AnimeFighting', 'Fighting.', 'Battle through the Future Arc with upgraded flame powers.', 'An evolved fighting game with new characters and moves.', 'Flame Rumble Hyper focuses on the Future saga. Experience high-speed battles with enhanced graphics and a deep move set for all your favorite guardians.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---flame-rumble-x---mirai-chou-bakuhatsu!!-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Flame Rumble X - Mirai Chou Bakuhatsu!! (Japan)', '2009', 'Fighting', 'Marvelous', '2', 'AnimeFighting', 'Fighting.', 'Face the ultimate challenge in the expanded Future world.', 'The "X" version of the Flame Rumble fighting series.', 'Flame Rumble X features even more characters and refined gameplay. Engage in massive battles and use strategic support to win the toughest mafia skirmishes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---flame-rumble-xx---chou-kessen!-real-6-chouka-japan-ndsi-enhanced', 'NDS', 'Katekyoo Hitman Reborn! DS - Flame Rumble XX - Chou Kessen! Real 6 Chouka (Japan) (NDSi Enhanced)', '2010', 'Fighting', 'Marvelous', '2', 'AnimeFighting', 'Fighting.', 'Compete in the Real 6 Funeral Wreaths battle.', 'A DSi-enhanced fighter with the series'' largest roster.', 'Flame Rumble XX is the definitive fighter for Reborn fans. Use the DSi camera for special unlocks and battle across dozens of stages with polished combat mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---mafia-daishuugou!---vongola-festival!!-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Mafia Daishuugou! - Vongola Festival!! (Japan)', '2009', 'Party', 'Marvelous', '4', 'PartyMiniGames', 'Mini-game/Social.', 'Join the Vongola family for a festive celebration.', 'A collection of fun mini-games starring the Reborn cast.', 'Mafia Daishuugou features dozens of touch-screen challenges. Earn points to unlock collectibles and enjoy the lighter side of the Vongola world with friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---ore-ga-boss!---saikyou-family-taisen-japan-ndsi-enhanced', 'NDS', 'Katekyoo Hitman Reborn! DS - Ore ga Boss! - Saikyou Family Taisen (Japan) (NDSi Enhanced)', '2010', 'Action', 'Marvelous', '2', 'AnimeAction', 'Strategy/Battle.', 'Become the boss and lead your family to victory.', 'A strategic DSi-enhanced mafia management battle game.', 'Ore ga Boss! on NDS lets you build your own mafia squad. Use tactical positioning and special abilities to defeat rival families in this unique hybrid title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---shinuki-max!-vongola-carnival!!-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Shinuki Max! Vongola Carnival!! (Japan)', '2009', 'Party', 'Marvelous', '4', 'PartyMiniGames', 'Mini-game/Social.', 'Party with the Reborn cast in this carnival-themed game.', 'A second collection of fun and frantic anime mini-games.', 'Vongola Carnival offers even more variety for fans. Play through hilarious scenarios and interact with the entire cast in this vibrant social game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katekyoo-hitman-reborn!-ds---vongola-shiki---taisen-battle-sugoroku-japan', 'NDS', 'Katekyoo Hitman Reborn! DS - Vongola Shiki - Taisen Battle Sugoroku (Japan)', '2007', 'BoardGame', 'Marvelous', '4', 'BoardGameBattle', 'Board Game.', 'Compete in a mafia-themed board game with your rivals.', 'A strategic board game based on the Reborn universe.', 'Vongola Shiki combines classic board game movement with tactical card battles. Outmaneuver your opponents to become the top mafia family in the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawa-no-nushi-tsuri---komorebi-no-tani-seseragi-no-uta-japan', 'NDS', 'Kawa no Nushi Tsuri - Komorebi no Tani, Seseragi no Uta (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'FishingSimulation', 'Fishing RPG.', 'Catch legendary fish and help the valley spirits.', 'A peaceful and scenic fishing adventure RPG.', 'Kawa no Nushi Tsuri (River King) on NDS blends fishing mechanics with a charming story. Explore beautiful nature, manage your equipment, and master various fishing spots in this relaxing Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawaii-koinu-ds-japan', 'NDS', 'Kawaii Koinu DS (Japan)', '2006', 'Simulation', 'MTO', '1', 'PetCare', 'Virtual Pet.', 'Raise and train adorable puppies to be your best friends.', 'A cute and detailed puppy simulation for dog lovers.', 'Kawaii Koinu DS lets you choose from multiple breeds. Feed, groom, and play with your puppy using the touch screen, and enter competitions to show off your pet''s skills in this heartwarming sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawaii-koinu-ds-japan-rev-2', 'NDS', 'Kawaii Koinu DS (Japan) (Rev 2)', '2006', 'Simulation', 'MTO', '1', 'PetCare', 'Virtual Pet.', 'Raise and train adorable puppies to be your best friends.', 'A cute and detailed puppy simulation for dog lovers.', 'Kawaii Koinu DS lets you choose from multiple breeds. Feed, groom, and play with your puppy using the touch screen, and enter competitions to show off your pet''s skills in this heartwarming sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawaii-koinu-ds-2-japan', 'NDS', 'Kawaii Koinu DS 2 (Japan)', '2007', 'Simulation', 'MTO', '1', 'PetCare', 'Virtual Pet.', 'Expand your family of pets with even more puppy breeds.', 'The improved sequel to the popular puppy simulation.', 'Kawaii Koinu DS 2 features updated graphics and more interactions. Build a deeper bond with your virtual dogs through new mini-games and customization options for their home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawaii-koinu-ds-3-japan', 'NDS', 'Kawaii Koinu DS 3 (Japan)', '2008', 'Simulation', 'MTO', '1', 'PetCare', 'Virtual Pet.', 'Master puppy training and explore new outdoor activities.', 'The definitive entry in the Kawaii Koinu puppy series.', 'Kawaii Koinu DS 3 offers the most breeds and items yet. Take your puppies on walks, participate in complex trials, and enjoy the most refined pet care experience on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawaii-koneko-ds-japan', 'NDS', 'Kawaii Koneko DS (Japan)', '2006', 'Simulation', 'MTO', '1', 'PetCare', 'Virtual Pet.', 'Care for cute kittens and manage a happy cat home.', 'A sweet and realistic kitten care simulation.', 'Kawaii Koneko DS focuses on the charm of feline friends. Use the stylus to pet and play with various breeds of kittens, ensuring they are well-fed and happy in this cozy digital environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawaii-koneko-ds-2-japan', 'NDS', 'Kawaii Koneko DS 2 (Japan)', '2007', 'Simulation', 'MTO', '1', 'PetCare', 'Virtual Pet.', 'Grow your cat family and discover new feline behaviors.', 'An expanded sequel for fans of kitten simulations.', 'Kawaii Koneko DS 2 introduces more breeds and toys. Customize your home to create the perfect sanctuary for your kittens and enjoy new touch-screen interactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawaii-koneko-ds-3-japan', 'NDS', 'Kawaii Koneko DS 3 (Japan)', '2008', 'Simulation', 'MTO', '1', 'PetCare', 'Virtual Pet.', 'Become the ultimate kitten caretaker with new challenges.', 'The third installment of the beloved kitten sim series.', 'Kawaii Koneko DS 3 features more realistic cat movements and a wide array of accessories. It''s the perfect NDS title for cat enthusiasts who want a portable feline companion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kayou-generation-the-japan', 'NDS', 'Kayou Generation, The (Japan)', '2009', 'Music', 'Bandai Namco', '1', 'MusicCompilation', 'Music / Trivia.', 'Guess the classic Japanese pop hits from different eras.', 'A nostalgic musical quiz game about Showa-era pop.', 'The Kayou Generation tests your knowledge of Japanese music history. Listen to clips and identify artists and songs in this fun, rhythm-integrated trivia challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kazoku-minna-de---nihon-shiatsu-shikai-kanshuu---raku-raku-shiatsu-navi-japan', 'NDS', 'Kazoku Minna de - Nihon Shiatsu Shikai Kanshuu - Raku Raku Shiatsu Navi (Japan)', '2008', 'Health', 'Success', '1', 'MassageGuide', 'Health / Utility.', 'Learn and practice professional Shiatsu massage techniques.', 'A digital guide to Japanese Shiatsu and relaxation.', 'Raku Raku Shiatsu Navi provides step-by-step instructions for pressure-point massage. Approved by the Japan Shiatsu Association, it''s a wellness tool for the whole family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keiba-navi---umanosuke-japan', 'NDS', 'Keiba Navi - Umanosuke (Japan)', '2006', 'Sports', 'Starfish', '1', 'HorseRacing', 'Sports / Betting.', 'Analyze horse racing data to make winning bets.', 'A deep and strategic horse racing data manager.', 'Keiba Navi: Umanosuke lets you track real racing stats and simulate outcomes. Essential for Keiba fans, it provides a comprehensive database of horses and tracks in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keiba-techou---umanosuke-2-japan', 'NDS', 'Keiba Techou - Umanosuke 2 (Japan)', '2007', 'Sports', 'Starfish', '1', 'HorseRacing', 'Sports / Betting.', 'Master the track with updated horse racing stats.', 'The professional sequel to the Keiba data manager.', 'Keiba Techou: Umanosuke 2 offers even more detailed analysis tools and updated rosters. Use the NDS to manage your bets and research pedigree and performance like a pro.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keiji-jb-harold-no-jikenbo---manhattan-requiem-&-kiss-of-murder-japan', 'NDS', 'Keiji J.B. Harold no Jikenbo - Manhattan Requiem & Kiss of Murder (Japan)', '2008', 'Adventure', 'Alfa System', '1', 'DetectiveAdventure', 'Mystery / Adventure.', 'Solve gritty murder cases as detective J.B. Harold.', 'A noir-style detective anthology for the NDS.', 'Manhattan Requiem & Kiss of Murder brings classic PC adventures to the dual screen. Interview suspects and piece together clues to solve dark crimes in this atmospheric detective sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keiji-jb-harold-no-jikenbo---murder-club-japan', 'NDS', 'Keiji J.B. Harold no Jikenbo - Murder Club (Japan)', '2008', 'Adventure', 'Alfa System', '1', 'DetectiveAdventure', 'Mystery / Adventure.', 'Solve the mystery of the Murder Club through investigation.', 'A classic point-and-click crime investigation game.', 'J.B. Harold: Murder Club tasks you with solving a high-profile case. Navigate a web of lies and evidence in this detailed and challenging detective title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keitai-sousakan-7-ds---buddy-sequence-japan', 'NDS', 'Keitai Sousakan 7 DS - Buddy Sequence (Japan)', '2010', 'Adventure', 'SEGA', '1', 'CrimeInvestigation', 'Adventure / Strategy.', 'Partner with a living cell phone to stop digital crimes.', 'A unique adventure based on the cult Japanese TV show.', 'Keitai Sousakan 7 lets you control the Phone Braver robots. Solve puzzles and engage in tactical battles to protect the network from hackers and cyber-terrorists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kekkaishi---karasumori-ayakashi-kidan-japan', 'NDS', 'Kekkaishi - Karasumori Ayakashi Kidan (Japan)', '2007', 'Action', 'Bandai Namco', '2', 'AnimeAction', 'Action-adventure.', 'Use barrier magic to destroy demons in the night.', 'A stylish action game based on the Kekkaishi anime.', 'Karasumori Ayakashi Kidan features touch-screen combat. Draw boxes to trap spirits and unleash powerful "Ketsu" attacks to protect the sacred school grounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kekkaishi---kokubourou-shuurai-japan', 'NDS', 'Kekkaishi - Kokubourou Shuurai (Japan)', '2007', 'Action', 'Bandai Namco', '2', 'AnimeAction', 'Action-adventure.', 'Defend the Kekkaishi territory from a massive demon invasion.', 'A high-stakes action sequel based on the hit anime.', 'Kokubourou Shuurai expands the combat system with new special moves and larger-than-life bosses. Master the art of Kekkaishi to save the world from the Kokubourou.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keltis---das-spiel-von-reiner-knizia-germany', 'NDS', 'Keltis - Das Spiel von Reiner Knizia (Germany)', '2008', 'BoardGame', 'Kosmos', '4', 'StrategyBoardGame', 'Board Game.', 'Navigate the stone path and reach the top of the mountain.', 'A digital version of Reiner Knizia''s award-winning board game.', 'Keltis on NDS brings the strategic card-and-board game to life. Use logic and risk management to place your tiles and score points in this elegant German game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kemeko-deluxe!-ds---yome-to-meka-to-otoko-to-onna-japan', 'NDS', 'Kemeko Deluxe! DS - Yome to Meka to Otoko to Onna (Japan)', '2008', 'VisualNovel', '5pb', '1', 'ComedyVisualNovel', 'Visual Novel / Mini-games.', 'Navigate a chaotic harem life with a robotic girl.', 'A wacky and humorous game based on the Kemeko Deluxe anime.', 'Kemeko Deluxe! DS features hilarious dialogue and touch-screen challenges. Follow Mmsand and his strange robotic "wife" in this over-the-top sci-fi comedy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kenkou-ouen-recipe-1000---ds-kondate-zenshuu-japan', 'NDS', 'Kenkou Ouen Recipe 1000 - DS Kondate Zenshuu (Japan)', '2009', 'Simulation', 'Nintendo', '1', 'CookingReference', 'Cooking / Utility.', 'Access 1,000 healthy recipes for a balanced lifestyle.', 'A massive digital cookbook and nutrition planner.', 'Kenkou Ouen Recipe 1,000 provides step-by-step guides for healthy meals. Search by calories or ingredients to plan the perfect diet on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kenshuui-tendo-dokuta-japan', 'NDS', 'Kenshuui Tendo Dokuta (Japan)', '2006', 'Adventure', 'Spike', '1', 'MedicalDrama', 'Medical Simulation.', 'Perform surgeries and save lives as an intern doctor.', 'A dramatic medical RPG in the style of Trauma Center.', 'Kenshuui Tendo Dokuta tasks you with using the stylus as a scalpel. Diagnose patients and perform high-pressure operations in this intense hospital drama.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kenshuui-tendo-dokuta-2---inochi-no-tenbin-japan', 'NDS', 'Kenshuui Tendo Dokuta 2 - Inochi no Tenbin (Japan)', '2008', 'Adventure', 'Spike', '1', 'MedicalDrama', 'Medical Simulation.', 'Make difficult life-and-death choices in the ER.', 'The emotional and challenging medical simulation sequel.', 'Kenshuui Tendo Dokuta 2 features more complex surgeries and a deep story about the ethics of medicine. Use your skills to balance the "scales of life" and save your patients.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kero-kero-7-japan', 'NDS', 'Kero Kero 7 (Japan)', '2007', 'Action', 'Jaleco', '2', 'ActionShooter', 'Action / Platformer.', 'Use ninja skills to defeat enemies and clear levels.', 'A fast-paced 2D action game based on the Kero Kero 7 manga.', 'Kero Kero 7 features vibrant graphics and tight platforming. Control the ninja team and use their unique abilities to overcome obstacles and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keroro-gunsou---enshuu-da-yo!---zenin-shuugou-part-2-japan', 'NDS', 'Keroro Gunsou - Enshuu Da yo! - Zenin Shuugou Part 2 (Japan)', '2007', 'Action', 'Bandai Namco', '2', 'AnimeAction', 'Mini-game collection.', 'Join the Keroro Platoon in a series of wacky drills.', 'A hilarious collection of mini-games for Sergeant Keroro fans.', 'Keroro Gunsou Part 2 features even more frantic touch-screen challenges. Help the frogs conquer Pekopon (Earth) through bizarre and fun experiments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keroro-rpg---kishi-to-musha-to-densetsu-no-kaizoku-japan', 'NDS', 'Keroro RPG - Kishi to Musha to Densetsu no Kaizoku (Japan)', '2008', 'RolePlaying', 'Bandai Namco', '1', 'AnimeRPG', 'RPG.', 'Explore a fantasy world with Sergeant Keroro and his friends.', 'A deep "Tales of" style RPG featuring the Keroro cast.', 'Keroro RPG blends the humor of the anime with traditional RPG exploration and real-time combat. Customize your party and save a magical world in this epic quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keshikasu-kun---battle-kasu-tival-japan', 'NDS', 'Keshikasu-kun - Battle Kasu-tival (Japan)', '2009', 'Action', 'Konami', '2', 'ComedyAction', 'Mini-game / Battle.', 'Fight with eraser-themed characters in schoolyard battles.', 'A quirky and fun action game based on the Keshikasu-kun manga.', 'Keshikasu-kun features creative mini-games where you use erasers to "rub out" the competition. It''s a humorous and energetic title perfect for short play sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ketsui-death-label---kizuna-jigoku-tachi-japan', 'NDS', 'Ketsui Death Label - Kizuna Jigoku-tachi (Japan)', '2007', 'Shooter', 'CAVE', '1', 'ArcadeShooter', 'Shoot ''em up.', 'Survive an intense curtain of bullets in this hardcore SHMUP.', 'A legendary and challenging "bullet hell" for NDS.', 'Ketsui Death Label is a masterpiece of the SHMUP genre. Face massive bosses and navigate complex bullet patterns in this intense arcade port designed for the hardcore fan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-paddle---blorks-invasion-europe-frnl', 'NDS', 'Kid Paddle - Blorks Invasion (Europe) (Fr,Nl)', '2008', 'Platformer', 'Mindscape', '1', 'ComicPlatformer', 'Action / Mini-games.', 'Save the arcade world from a virus invasion.', 'A fun action game based on the French comic series.', 'Kid Paddle: Blorks Invasion tasks you with playing various arcade-style mini-games. Use Kid Paddle''s imagination to defeat the Blorks and save the game universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-paddle---lost-in-the-game-france', 'NDS', 'Kid Paddle - Lost in the Game (France)', '2009', 'Platformer', 'Mindscape', '1', 'ComicPlatformer', 'Action-adventure.', 'Escape from a digital world and find your way home.', 'A colorful platforming adventure for Kid Paddle fans.', 'Kid Paddle: Lost in the Game features levels inspired by the comic''s signature art style. Solve puzzles and beat mini-games to help Kid Paddle escape his favorite video game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-gekidan-haro-ichiza---gundam-mahjong-+z---sarani-dekiru-you-ni-natta-na!-japan', 'NDS', 'Kidou Gekidan Haro Ichiza - Gundam Mahjong +Z - Sarani Dekiru You ni Natta Na! (Japan)', '2008', 'BoardGame', 'Bandai Namco', '4', 'Mahjong', 'Board Game / Mahjong.', 'Win the Gundam-themed Mahjong tournament.', 'A strategic Mahjong game with a comedic Gundam twist.', 'Gundam Mahjong +Z features characters from across the franchise. Compete in high-stakes matches and enjoy humorous dialogue in this unique crossover title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-gekidan-haro-ichiza---gundam-mahjong-ds---oyaji-ni-mo-agarareta-koto-nai-no-ni!-japan', 'NDS', 'Kidou Gekidan Haro Ichiza - Gundam Mahjong DS - Oyaji ni mo Agarareta Koto nai no ni! (Japan)', '2006', 'BoardGame', 'Bandai Namco', '4', 'Mahjong', 'Board Game / Mahjong.', 'Win the Gundam-themed Mahjong tournament.', 'A strategic Mahjong game with a comedic Gundam twist.', 'Gundam Mahjong DS combines classic tiles with the world of Mobile Suit Gundam. Use special character powers to turn the tide of the match and claim victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-senshi-gundam-00-japan', 'NDS', 'Kidou Senshi Gundam 00 (Japan)', '2008', 'Action', 'Bandai Namco', '2', 'AnimeAction', 'Action / Strategy.', 'Pilot the Gundam Exia and defeat the world''s conflicts.', 'A cinematic action-strategy game based on Gundam 00.', 'Kidou Senshi Gundam 00 on NDS features intense mecha battles. Follow the story of the Celestial Being pilots and use the touch screen to execute tactical maneuvers and powerful attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kids-ds---dekita-yo!-mama---onnanoko-japan', 'NDS', 'Kids DS - Dekita yo! Mama. - Onnanoko (Japan)', '2007', 'Education', 'Nintendo', '1', 'KidsLearning', 'Educational.', 'Learn daily chores and manners through fun mini-games.', 'A lifestyle educational game for young girls.', 'Dekita yo! Mama - Onnanoko helps young children learn about tidying up, helping at home, and social manners. With friendly guidance and simple touch-screen tasks, it''s a great early learning tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kids-ds---dekita-yo!-mama---otokonoko-japan', 'NDS', 'Kids DS - Dekita yo! Mama. - Otokonoko (Japan)', '2007', 'Education', 'Nintendo', '1', 'KidsLearning', 'Educational.', 'Learn daily chores and manners through fun mini-games.', 'A lifestyle educational game for young boys.', 'Dekita yo! Mama - Otokonoko features interactive lessons on daily routines and responsibility. Kids can practice "grown-up" tasks in a safe, fun digital environment designed for preschool learners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiite-hajimeru---eigo-kaiwa-training---kikitore-japan', 'NDS', 'Kiite Hajimeru - Eigo Kaiwa Training - Kikitore (Japan)', '2006', 'Education', 'Nintendo', '1', 'LanguageTraining', 'Educational / English.', 'Improve English listening and speaking skills.', 'A practical English conversation trainer for Japanese speakers.', 'Kikitore on NDS focuses on auditory learning. Listen to real-world English dialogues and use the microphone to practice pronunciation, making it a perfect tool for beginners and travelers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kikansha-thomas---ds-de-hajimeru-chiiku-gakushuu-japan', 'NDS', 'Kikansha Thomas - DS de Hajimeru Chiiku Gakushuu (Japan)', '2009', 'Education', 'Bandai Namco', '1', 'EarlyLearning', 'Educational.', 'Complete puzzles and activities with Thomas & Friends.', 'An early childhood learning game featuring Thomas the Tank Engine.', 'Kikansha Thomas: Chiiku Gakushuu uses the beloved train characters to teach shapes, colors, and logic. Simple touch controls make it ideal for young fans of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kikansha-thomas---ds-de-hajimeru-kokugo-sansuu-eigo-japan', 'NDS', 'Kikansha Thomas - DS de Hajimeru Kokugo Sansuu Eigo (Japan)', '2009', 'Education', 'Bandai Namco', '1', 'EarlyLearning', 'Educational.', 'Master basic Japanese, Math, and English with Thomas.', 'A comprehensive school-readiness trainer for NDS.', 'Thomas the Tank Engine leads the way in this educational title covering core subjects. Engaging mini-games help children build a strong foundation in language and arithmetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiku!-kaku!-kotoba-o-fuyasu!---hajimete-no-eigo-training---eitore-japan', 'NDS', 'Kiku! Kaku! Kotoba o Fuyasu! - Hajimete no Eigo Training - Eitore (Japan)', '2007', 'Education', 'Nintendo', '1', 'LanguageTraining', 'Educational / English.', 'Build a basic English vocabulary through writing and listening.', 'An introductory English trainer for young students.', 'Eitore on NDS focuses on the fundamentals of the English language. Use the stylus to write words and the speakers to hear correct pronunciations in a structured, fun learning path.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kilari---deviens-une-star-europe-enfresit', 'NDS', 'Kilari - Deviens une Star (Europe) (En,Fr,Es,It)', '2008', 'Simulation', 'Konami', '1', 'IdolSimulation', 'Social / Rhythm.', 'Train your idol skills and become a world-famous star.', 'A glamorous idol career simulation based on the anime.', 'Kilari: Deviens une Star lets you experience the life of an idol. Manage your schedule, choose stunning outfits, and perform in rhythm-based concerts to win the hearts of your fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kilari---na-san-mon-meilleur-ami-europe-fresit', 'NDS', 'Kilari - Na-san, Mon Meilleur Ami (Europe) (Fr,Es,It)', '2009', 'Simulation', 'Konami', '1', 'IdolSimulation', 'Virtual Pet / Adventure.', 'Take care of Na-san and complete fun missions together.', 'A charming adventure starring Kilari’s pet cat.', 'Na-san, Mon Meilleur Ami focuses on the bond between Kilari and her cat. Play mini-games, dress up Na-san, and help the duo navigate their busy celebrity lives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kim-possible---global-gemini-europe-enfrdeesit', 'NDS', 'Kim Possible - Global Gemini (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Tarantula Studios', '1', 'ActionAdventure', 'Action-platformer.', 'Stop Global Gemini and save the world from total domination.', 'A high-tech spy adventure featuring Disney''s Kim Possible.', 'Kim Possible: Global Gemini on NDS features gadgets, stealth, and martial arts. Use the touch screen to hack systems and control Kim as she travels the world to stop evil villains.');
