INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kimi-ni-todoke---sodateru-omoi-japan', 'NDS', 'Kimi ni Todoke - Sodateru Omoi (Japan)', '2009', 'VisualNovel', 'Bandai Namco', '1', 'RomanceStory', 'Social / Romance.', 'Build relationships and navigate high school life.', 'A heartwarming romance sim based on the hit anime.', 'Kimi ni Todoke on NDS lets you play as Sawako. Improve your social skills, make friends, and experience a touching story of growth and first love through interactive dialogues.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kimi-no-tame-nara-shineru-japan-enja', 'NDS', 'Kimi no Tame Nara Shineru (Japan) (En,Ja)', '2004', 'Action', 'Sonic Team', '1', 'ExperimentalAction', 'Mini-game / Romance.', 'Complete bizarre challenges to impress the girl of your dreams.', 'A quirky and creative cult classic for the NDS.', 'Kimi no Tame Nara Shineru (Feel the Magic) uses every NDS feature—touching, blowing, and shouting—to complete hilarious and stylish mini-games in the name of love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kimi-no-yuusha-japan', 'NDS', 'Kimi no Yuusha (Japan)', '2009', 'RolePlaying', 'Nintendo', '1', 'FantasyRPG', 'Turn-based RPG.', 'Embark on an epic quest to save a world of floating islands.', 'A classic and polished fantasy RPG for the NDS.', 'Kimi no Yuusha features a beautiful story and tactical combat. Lead a band of young heroes through a vibrant world, mastering unique abilities to defeat a looming darkness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kimochi-yosa-rensa-puzzle---trion-cube-japan', 'NDS', 'Kimochi yosa Rensa Puzzle - Trion Cube (Japan)', '2009', 'Puzzle', 'Jupiter', '1', 'LogicPuzzle', 'Puzzle.', 'Create 3x3 cubes to clear the screen and score big.', 'A fast-paced and addictive chain-reaction puzzle game.', 'Trion Cube on NDS puts a twist on the falling-block genre. Strategically place pieces to create large cubes and trigger massive combos in this colorful and energetic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kimokawa-e!-japan', 'NDS', 'Kimokawa-E! (Japan)', '2008', 'VisualNovel', 'D3 Publisher', '1', 'ComedyVisualNovel', 'Mystery / Horror.', 'Solve the mystery of a strange, creepy-cute curse.', 'A unique and atmospheric Japanese horror-adventure.', 'Kimokawa-E! blends high school drama with supernatural mystery. Use your investigative skills to uncover the truth behind strange occurrences in this stylish and eerie game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kindaichi-shounen-no-jikenbo---akuma-no-satsujin-koukai-japan', 'NDS', 'Kindaichi Shounen no Jikenbo - Akuma no Satsujin Koukai (Japan)', '2007', 'Adventure', 'Konami', '1', 'DetectiveMystery', 'Visual Novel / Mystery.', 'Solve a gruesome murder at sea with the famous boy detective.', 'A high-stakes detective adventure starring Kindaichi.', 'Akuma no Satsujin Koukai tasks you with finding clues and interviewing suspects on a luxury cruise. Use logic to unmask the killer in this classic Japanese mystery.');
