INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirarin-revolution---minna-de-odorou-furi-furi-debut!-japan', 'NDS', 'Kirarin Revolution - Minna de Odorou Furi Furi Debut! (Japan)', '2007', 'Music', 'Konami', '1', 'DanceRhythm', 'Rhythm / Dance.', 'Perform perfect dance routines and debut your idol group.', 'A high-energy rhythm and performance game.', 'Minna de Odorou features touch-screen dance gameplay. Follow the beat, unlock new songs, and watch Kirarin and her friends perform on the big stage.');
