INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirarin-revolution---tsukutte-misechao!---kime-kira-stage-japan', 'NDS', 'Kirarin Revolution - Tsukutte Misechao! - Kime Kira Stage (Japan)', '2009', 'Simulation', 'Konami', '1', 'IdolManagement', 'Fashion / Creative.', 'Design your own stage outfits and perform in style.', 'A creative fashion design and idol performance sim.', 'Kime Kira Stage focuses on customization. Create your own clothes, design the stage layout, and lead Kirarin to a stunning performance in this artistic NDS game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby---canvas-curse-usa', 'NDS', 'Kirby - Canvas Curse (USA)', '2005', 'Platformer', 'HAL Laboratory', '1', 'TouchPlatformer', 'Action-puzzle.', 'Draw rainbow paths to guide Kirby through a painted world.', 'A creative touch-screen adventure where Kirby is a ball.', 'Kirby: Canvas Curse on NDS reinvents platforming. Use the stylus to draw paths, stun enemies, and guide a ball-shaped Kirby through vibrant levels to defeat the witch Drawcia.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby---mass-attack-europe-enfrdeesit', 'NDS', 'Kirby - Mass Attack (Europe) (En,Fr,De,Es,It)', '2011', 'Platformer', 'HAL Laboratory', '1', 'ActionPlatformer', 'Strategy-action.', 'Control an army of up to 10 Kirbys to swashbuckle foes.', 'A unique mass-action adventure using only the stylus.', 'Kirby: Mass Attack on NDS tasks you with managing a crowd of Kirbys. Tap the screen to command your pink army to bash enemies, solve puzzles, and carry large objects in this innovative quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby---mass-attack-usa-enfres', 'NDS', 'Kirby - Mass Attack (USA) (En,Fr,Es)', '2011', 'Platformer', 'HAL Laboratory', '1', 'ActionPlatformer', 'Strategy-action.', 'Control an army of up to 10 Kirbys to swashbuckle foes.', 'A unique mass-action adventure using only the stylus.', 'Kirby: Mass Attack on NDS tasks you with managing a crowd of Kirbys. Tap the screen to command your pink army to bash enemies, solve puzzles, and carry large objects in this innovative quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby---mouse-attack-europe-enfrdeesit', 'NDS', 'Kirby - Mouse Attack (Europe) (En,Fr,De,Es,It)', '2007', 'Platformer', 'HAL Laboratory', '1', 'ActionPlatformer', 'Action-platformer.', 'Recover Kirby''s stolen strawberry shortcake from the Squeaks.', 'A classic Kirby adventure with a touch-screen stomach.', 'Kirby: Mouse Attack (Squeak Squad) features the iconic copy abilities. Store items and abilities in Kirby''s stomach on the bottom screen and combine them to create powerful new attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby---power-paintbrush-europe-enfrdeesit', 'NDS', 'Kirby - Power Paintbrush (Europe) (En,Fr,De,Es,It)', '2007', 'Platformer', 'HAL Laboratory', '1', 'TouchPlatformer', 'Action-puzzle.', 'Draw rainbow paths to guide Kirby through a painted world.', 'A creative touch-screen adventure where Kirby is a ball.', 'Kirby: Power Paintbrush (Canvas Curse) brings a unique art style to NDS. Control Kirby by drawing lines and tapping him to dash, offering a completely fresh way to play a platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby---squeak-squad-usa', 'NDS', 'Kirby - Squeak Squad (USA)', '2006', 'Platformer', 'HAL Laboratory', '1', 'ActionPlatformer', 'Action-platformer.', 'Recover Kirby''s stolen strawberry shortcake from the Squeaks.', 'A classic Kirby adventure with a touch-screen stomach.', 'Kirby: Squeak Squad on NDS pits you against a gang of treasure-hunting mice. Explore varied worlds, collect secret maps, and master classic abilities like Fire, Ice, and Sword.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-super-star-allies', 'NDS', 'Kirby Super Star Allies', '2018', 'Platformer', 'HAL Laboratory', '1', 'ModernPlatformer', 'Action-platformer.', 'Complete multiple adventures and mini-games in Dream Land.', 'A massive, enhanced remake of the SNES classic.', 'Kirby Super Star Ultra on NDS features over 15 game modes. Enjoy updated 3D cinematics, new sub-games, and cooperative play in what many consider the ultimate Kirby experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-super-star-ultra-europe-enfrdeesit', 'NDS', 'Kirby Super Star Ultra (Europe) (En,Fr,De,Es,It)', '2008', 'Platformer', 'HAL Laboratory', '1', 'ClassicPlatformer', 'Action-platformer.', 'Complete multiple adventures and mini-games in Dream Land.', 'A massive, enhanced remake of the SNES classic.', 'Kirby Super Star Ultra on NDS features over 15 game modes. Enjoy updated 3D cinematics, new sub-games, and cooperative play in what many consider the ultimate Kirby experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-super-star-ultra-usa', 'NDS', 'Kirby Super Star Ultra (USA)', '2008', 'Platformer', 'HAL Laboratory', '1', 'ClassicPlatformer', 'Action-platformer.', 'Complete multiple adventures and mini-games in Dream Land.', 'A massive, enhanced remake of the SNES classic.', 'Kirby Ultra Super Deluxe is the Korean version of the hit remake. Experience the legendary "Great Cave Offensive" and "Revenge of Meta Knight" with beautifully polished handheld graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-ultra-super-deluxe-korea', 'NDS', 'Kirby Ultra Super Deluxe (Korea)', '2008', 'Platformer', 'HAL Laboratory', '1', 'ClassicPlatformer', 'Social simulation.', 'Live a clean and happy life with the raccoon Kirei Zukin.', 'A cute lifestyle game based on the San-X character.', 'Kirei Zukin Seikatsu focuses on the joy of cleaning and daily chores. Play mini-games to tidy up your home and interact with adorable friends in this relaxing Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirei-zukin-seikatsu-japan', 'NDS', 'Kirei Zukin Seikatsu (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Lifestyle', 'Educational / English.', 'Master English vocabulary and grammar for students.', 'A structured English language trainer for the NDS.', 'Eigo@DS by Kirihara Shoten provides comprehensive lessons for Japanese learners. Improve your reading and listening skills through interactive exercises and progress tracking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirihara-shoten-forest---eigo@ds-japan', 'NDS', 'Kirihara Shoten Forest - Eigo@DS (Japan)', '2006', 'Education', 'Kirihara Shoten', '1', 'LanguageLearning', 'Educational / Trivia.', 'Test your general knowledge at a university level.', 'A challenging academic proficiency exam for adults.', 'Daigakusei Ryoku Kentei DS measures your "University Power." Answer questions on history, science, and literature to see how your knowledge compares to college graduates.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirihara-shoten-kanshuu---daigakusei-ryoku-kentei-ds-japan', 'NDS', 'Kirihara Shoten Kanshuu - Daigakusei Ryoku Kentei DS (Japan)', '2007', 'Education', 'Kirihara Shoten', '1', 'ExamTraining', 'Action-adventure.', 'Help Kirikou navigate the village and outsmart the sorceress.', 'A vibrant adventure based on the French animated film.', 'Kirikou and the Wild Beasts features puzzles and platforming inspired by West African folklore. Help the brave little hero protect his village in this beautiful and culturally rich game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirikou-and-the-wild-beasts-europe-enfrdeesit', 'NDS', 'Kirikou and the Wild Beasts (Europe) (En,Fr,De,Es,It)', '2007', 'Adventure', 'Etranges Libellules', '1', 'StoryAdventure', 'Lifestyle / Nature.', 'Relax while watching high-definition aquarium life.', 'A stunning virtual aquarium and marine guide.', 'Kiwami Birei Aquarium turns your NDS into a window to the sea. Watch whales, dolphins, and exotic fish with realistic animations and educational facts about marine biology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiwami-birei-aquarium---sekai-no-sakana-to-iruka-kujira-tachi-japan', 'NDS', 'Kiwami Birei Aquarium - Sekai no Sakana to Iruka Kujira-tachi (Japan)', '2008', 'Simulation', 'Nintendo', '1', 'NatureExperience', 'Educational / Social.', 'Learn proper manners and etiquette through play.', 'A German guide to good behavior and social rules.', 'Knigge on NDS teaches you the "dos and don''ts" of social situations. From dining etiquette to formal greetings, master the art of good manners through fun scenarios and quizzes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knigge---spielend-zum-guten-benehmen-germany', 'NDS', 'Knigge - Spielend zum Guten Benehmen (Germany)', '2008', 'Education', 'DTF Games', '1', 'SocialTraining', 'Strategy RPG.', 'Command souls to defeat monsters in a bullet-hell RPG.', 'A unique blend of real-time strategy and bullet hell.', 'Knights in the Nightmare features a complex combat system where you control a "Wisp" with the stylus. Manage your army''s souls and dodge projectiles in this atmospheric masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knights-in-the-nightmare-japan', 'NDS', 'Knights in the Nightmare (Japan)', '2008', 'RolePlaying', 'Sting', '1', 'TacticalRPG', 'Strategy RPG.', 'Command souls to defeat monsters in a bullet-hell RPG.', 'A unique blend of real-time strategy and bullet hell.', 'Knights in the Nightmare features a complex combat system where you control a "Wisp" with the stylus. Manage your army''s souls and dodge projectiles in this atmospheric masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knights-in-the-nightmare-usa', 'NDS', 'Knights in the Nightmare (USA)', '2009', 'RolePlaying', 'Sting', '1', 'TacticalRPG', 'Puzzle.', 'Solve logic puzzles by thinking "outside the box."', 'A creative and challenging brain-teaser collection.', 'Know How on NDS features over 100 puzzles that test your lateral thinking. Use the stylus to manipulate objects and find unconventional solutions to increasingly difficult riddles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('know-how---think-and-play-outside-the-box-europe-enfrdeesit', 'NDS', 'Know How - Think and Play outside the Box (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', '7th Sense', '1', 'LogicPuzzle', 'Educational / Language.', 'Learn to read and understand classic Japanese literature.', 'A specialized trainer for Old Japanese and Chinese classics.', 'Kobun Kanbun DS helps students master the difficult kanji and grammar of ancient texts. It’s an essential study tool for passing entrance exams in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kobun-kanbun-ds-japan', 'NDS', 'Kobun Kanbun DS (Japan)', '2006', 'Education', 'Nintendo', '1', 'ClassicalStudies', 'Party / Mini-games.', 'Help Ryoutsu win big through crazy schemes and games.', 'A hilarious mini-game collection based on the long-running manga.', 'Kochikame on NDS features the eccentric policeman Ryoutsu in a variety of "get-rich-quick" scenarios. Play wacky touch-screen games and experience the humor of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kochira-katsushika-ku-kameari-kouen-mae-hashutsujo---kateba-tengoku!-makereba-jigoku!---ryoutsu-ryuu-ikkakusenkin-daisakusen!-japan', 'NDS', 'Kochira Katsushika Ku Kameari Kouen Mae Hashutsujo - Kateba Tengoku! Makereba Jigoku! - Ryoutsu-ryuu Ikkakusenkin Daisakusen! (Japan)', '2007', 'Adventure', 'Bandai Namco', '1', 'ComedyAdventure', 'Cooking simulation.', 'Learn to cook hundreds of real recipes step-by-step.', 'An interactive digital cookbook and kitchen assistant.', 'Kochkurs (Cooking Guide) on NDS features voice-controlled navigation. Follow easy instructions, watch technique videos, and find the perfect meal to cook today.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kochkurs---was-wollen-wir-heute-kochen-germany', 'NDS', 'Kochkurs - Was Wollen Wir Heute Kochen (Germany)', '2008', 'Simulation', 'Tivola', '1', 'CookingSimulation', 'RPG / Battle.', 'Collect dinosaur fossils and battle for the title of King.', 'A strategic dinosaur-battling game with RPG elements.', 'Dinosaur King (7-tsu no Kakera) lets you excavate fossils and customize your dinosaurs. Use a rock-paper-scissors battle system to defeat rivals and save the world from the Alpha Gang.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kodai-ouja-kyouryuu-king---7-tsu-no-kakera-japan', 'NDS', 'Kodai Ouja Kyouryuu King - 7-tsu no Kakera (Japan)', '2007', 'Action', 'Sega', '1', 'ActionAdventure', 'Sports / Strategy.', 'Lead your professional baseball team to the championship.', 'A deep baseball management and simulation game.', 'Ochanoma Pro Yakyuu 2010 focuses on the strategy of the game. As the manager, make critical calls from the dugout to lead your team to victory using real player data.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kodawari-saihai-simulation---ochanoma-pro-yakyuu-ds---2010-nendo-ban-japan', 'NDS', 'Kodawari Saihai Simulation - Ochanoma Pro Yakyuu DS - 2010 Nendo Ban (Japan)', '2010', 'Sports', 'Namco Bandai', '1', 'BaseballSimulation', 'Sports / Strategy.', 'Lead your professional baseball team to the championship.', 'A deep baseball management and simulation game.', 'Ochanoma Pro Yakyuu DS lets you experience the thrill of the NPB. Manage your roster, call the plays, and watch your tactical decisions play out on the field in this detailed sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kodawari-saihai-simulation---ochanoma-pro-yakyuu-ds-japan', 'NDS', 'Kodawari Saihai Simulation - Ochanoma Pro Yakyuu DS (Japan)', '2008', 'Sports', 'Namco Bandai', '1', 'BaseballSimulation', 'Educational / Reading.', 'Enjoy interactive storybooks with professional narration.', 'A digital collection of classic children''s picture books.', 'Ehon de Asobou Vol. 1 brings stories to life for young children. Features beautiful illustrations and interactive touch points to encourage early literacy and a love for reading.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kodomo-no-tame-no-yomi-kikase---ehon-de-asobou-1-kan-japan', 'NDS', 'Kodomo no Tame no Yomi Kikase - Ehon de Asobou 1-kan (Japan)', '2007', 'Education', 'Nintendo', '1', 'Storybook', 'Educational / Reading.', 'Enjoy interactive storybooks with professional narration.', 'A digital collection of classic children''s picture books.', 'Ehon de Asobou Vol. 2 continues the series with new tales. Perfect for bedtime or travel, it offers a fun and educational way for kids to engage with timeless Japanese stories.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kodomo-no-tame-no-yomi-kikase---ehon-de-asobou-2-kan-japan', 'NDS', 'Kodomo no Tame no Yomi Kikase - Ehon de Asobou 2-kan (Japan)', '2007', 'Education', 'Nintendo', '1', 'Storybook', 'Educational / Reading.', 'Enjoy interactive storybooks with professional narration.', 'A digital collection of classic children''s picture books.', 'Ehon de Asobou Vol. 3 features even more narrated adventures. The high-quality voice acting and charming art make it a favorite for parents and children alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kodomo-no-tame-no-yomi-kikase---ehon-de-asobou-3-kan-japan', 'NDS', 'Kodomo no Tame no Yomi Kikase - Ehon de Asobou 3-kan (Japan)', '2007', 'Education', 'Nintendo', '1', 'Storybook', 'Educational / Reading.', 'Enjoy interactive storybooks with professional narration.', 'A digital collection of classic children''s picture books.', 'Ehon de Asobou Vol. 4 offers a new set of interactive fables. Kids can "play" with the pictures while listening to the story, building comprehension skills through interaction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kodomo-no-tame-no-yomi-kikase---ehon-de-asobou-4-kan-japan', 'NDS', 'Kodomo no Tame no Yomi Kikase - Ehon de Asobou 4-kan (Japan)', '2007', 'Education', 'Nintendo', '1', 'Storybook', 'Educational / Reading.', 'Enjoy interactive storybooks with professional narration.', 'A digital collection of classic children''s picture books.', 'Ehon de Asobou Vol. 5 provides another library of illustrated stories. Engaging mini-games between chapters help keep young minds focused and entertained.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kodomo-no-tame-no-yomi-kikase---ehon-de-asobou-5-kan-japan', 'NDS', 'Kodomo no Tame no Yomi Kikase - Ehon de Asobou 5-kan (Japan)', '2007', 'Education', 'Nintendo', '1', 'Storybook', 'Educational / Reading.', 'Enjoy interactive storybooks with professional narration.', 'A digital collection of classic children''s picture books.', 'Ehon de Asobou Vol. 6 completes this delightful series. With a vast array of stories, it’s a complete digital bookshelf for early learners on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kodomo-no-tame-no-yomi-kikase---ehon-de-asobou-6-kan-japan', 'NDS', 'Kodomo no Tame no Yomi Kikase - Ehon de Asobou 6-kan (Japan)', '2007', 'Education', 'Nintendo', '1', 'Storybook', 'Educational / Reading.', 'Enjoy interactive storybooks with professional narration.', 'A digital collection of classic children''s picture books.', 'Ehon de Asobou Vol. 6 completes this delightful series. With a vast array of stories, it’s a complete digital bookshelf for early learners on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koe-de-asobou---heartcatch-precure!-japan', 'NDS', 'Koe de Asobou - HeartCatch PreCure! (Japan)', '2010', 'Education', 'Toei Animation', '1', 'VoiceInteraction', 'Educational / Voice.', 'Practice speaking and acting with the PreCure characters.', 'A fun voice-interaction game based on the hit anime.', 'Koe de Asobou: HeartCatch PreCure! lets fans use the microphone to interact with Tsubomi and Erika. Record your voice, play mini-games, and experience scenes from the show on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koh-lanta---survie-dans-la-jungle!-france', 'NDS', 'Koh-Lanta - Survie dans la Jungle! (France)', '2009', 'Adventure', 'Mindscape', '1', 'SurvivalAdventure', 'Adventure / Survival.', 'Survive the jungle and win the reality show challenges.', 'A survival adventure based on the French "Survivor" show.', 'Koh-Lanta: Survie dans la Jungle! tasks you with managing resources, winning immunity idols, and outlasting rivals in a series of touch-screen physical and logic trials.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koh-lanta-france', 'NDS', 'Koh-Lanta (France)', '2001', 'Adventure', 'Mindscape', '1', 'RealityShow', 'Adventure / Survival.', 'Outlast your tribe members on a deserted island.', 'The digital adaptation of the popular French survival TV series.', 'Koh-Lanta on NDS features tribal councils, resource gathering, and iconic challenges. Use the stylus to master fishing, fire-making, and balance trials to become the ultimate survivor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koinu-de-kururin-japan', 'NDS', 'Koinu de Kururin (Japan)', '2006', 'Puzzle', 'Taito', '1', 'CasualPuzzle', 'Virtual Pet.', 'Spin and play with cute puppies in this puzzle-sim hybrid.', 'A charming and unique puppy interaction game.', 'Koinu de Kururin features adorable puppies in a "rolling" puzzle format. Use the touch screen to care for your pets and solve challenges in this cute Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koisuru-purin!---koi-wa-daibouken!-dr-kanmi-no-yabou!-japan', 'NDS', 'Koisuru Purin! - Koi wa Daibouken! Dr. Kanmi no Yabou! (Japan)', '2007', 'Adventure', 'Konami', '1', 'RomanticAdventure', 'Action-adventure.', 'Save the sweet kingdom from Dr. Kanmi''s sour plans.', 'A sugary-sweet platformer based on the Koisuru Purin manga.', 'Koisuru Purin! features a pudding-themed hero. Explore vibrant levels, collect treats, and use special abilities to defeat bosses in this colorful and humorous NDS quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kokoro-ga-mezameru---otoko-tachi-no-nurie-ds---tamiya-box-art-japan', 'NDS', 'Kokoro ga Mezameru - Otoko-tachi no Nurie DS - Tamiya Box Art (Japan)', '2008', 'Art', 'Tamiya', '1', 'ColoringExperience', 'Art / Hobby.', 'Color classic Tamiya model box art illustrations.', 'A digital coloring book for fans of Tamiya model kits.', 'Otoko-tachi no Nurie DS features iconic box art from tanks and ships. Use the stylus to meticulously paint these detailed illustrations and relax with a masculine artistic hobby.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kokoro-ga-uruou---birei-aquarium-ds---kujira-iruka-penguin-japan', 'NDS', 'Kokoro ga Uruou - Birei Aquarium DS - Kujira, Iruka, Penguin (Japan)', '2008', 'Simulation', 'Nintendo', '1', 'AquariumRelaxation', 'Lifestyle / Nature.', 'Relax with high-definition marine life and ocean sounds.', 'A stunning virtual aquarium featuring large sea mammals.', 'Birei Aquarium DS: Kujira, Iruka, Penguin brings whales and dolphins to your screen. Enjoy peaceful underwater views and learn fascinating facts about marine biology in high detail.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kokoro-ga-uruou---birei-aquarium-ds---tetra-guppy-angelfish-japan', 'NDS', 'Kokoro ga Uruou - Birei Aquarium DS - Tetra, Guppy, Angelfish (Japan)', '2008', 'Simulation', 'Nintendo', '1', 'AquariumRelaxation', 'Lifestyle / Nature.', 'Manage a tropical aquarium with colorful exotic fish.', 'A relaxing virtual fish tank for your NDS.', 'Birei Aquarium DS: Tetra, Guppy, Angelfish focuses on tropical species. Customize your tank, feed your fish, and enjoy the tranquil atmosphere of a professional aquarium on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kokoro-ni-shimiru---mouhitsu-de-kaku---aida-mitsuo-ds-japan', 'NDS', 'Kokoro ni Shimiru - Mouhitsu de Kaku - Aida Mitsuo DS (Japan)', '2007', 'Art', 'Ask', '1', 'CalligraphyArt', 'Art / Calligraphy.', 'Master brush calligraphy and the philosophy of Mitsuo Aida.', 'A spiritual and artistic calligraphy trainer.', 'Mouhitsu de Kaku: Aida Mitsuo DS lets you practice traditional Japanese brushwork. Trace the famous poet''s words and find inner peace through the art of digital calligraphy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kokoro-o-yasumeru---otona-no-nurie-ds-japan', 'NDS', 'Kokoro o Yasumeru - Otona no Nurie DS (Japan)', '2006', 'Art', 'Success', '1', 'ColoringRelaxation', 'Art / Hobby.', 'Relax by coloring intricate and beautiful illustrations.', 'A therapeutic digital coloring book for adults.', 'Otona no Nurie DS features various themes from nature to architecture. Choose your palette and use the stylus to create beautiful artwork in this stress-relieving NDS experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kokoro-o-yasumeru---otona-no-nurie-ds-2-japan', 'NDS', 'Kokoro o Yasumeru - Otona no Nurie DS 2 (Japan)', '2007', 'Art', 'Success', '1', 'ColoringRelaxation', 'Art / Hobby.', 'Color even more detailed and challenging illustrations.', 'The expanded sequel to the popular adult coloring series.', 'Otona no Nurie DS 2 offers new categories and improved painting tools. Perfect for unwinding, it provides a portable canvas for adult creativity and relaxation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kolonisten-van-catan-de-netherlands', 'NDS', 'Kolonisten van Catan, De (Netherlands)', '2008', 'Boardgame', 'Exozet Games', '4', 'StrategyBoardgame', 'Board Game.', 'Settle the island of Catan by trading and building.', 'A faithful digital version of the world-famous board game.', 'De Kolonisten van Catan on NDS features the classic resource-management gameplay. Compete against AI or friends to build roads, settlements, and cities in this strategic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koma-neko-ds-japan', 'NDS', 'Koma Neko DS (Japan)', '2008', 'Adventure', 'Dwarf Works', '1', 'AnimatedStory', 'Mini-game / Social.', 'Join Koma Neko the kitten for creative stop-motion fun.', 'A charming game based on the famous Japanese mascot.', 'Koma Neko DS features adorable mini-games and a creative studio. Use the touch screen to interact with Koma-chan and explore her cozy, hand-crafted world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konami-arcade-classics-europe-enjafrdeesit', 'NDS', 'Konami Arcade Classics (Europe) (En,Ja,Fr,De,Es,It)', '2007', 'Arcade', 'Konami', '2', 'RetroCollection', 'Arcade Collection.', 'Play 15 legendary arcade classics from the 80s.', 'A massive compilation of Konami''s golden age hits.', 'Konami Arcade Classics features icons like Gradius, Contra, and Frogger. Experience pixel-perfect ports with added features and history in this must-have retro collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konami-arcade-collection-japan-enja', 'NDS', 'Konami Arcade Collection (Japan) (En,Ja)', '2007', 'Arcade', 'Konami', '2', 'RetroCollection', 'Arcade Collection.', 'Play 15 legendary arcade classics from the 80s.', 'A massive compilation of Konami''s golden age hits.', 'Konami Arcade Collection (Japan) includes classic titles like Yie Ar Kung-Fu and Scramble. Perfect for retro fans, it offers original arcade controls adapted for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konami-classics-series---arcade-hits-usa-enja', 'NDS', 'Konami Classics Series - Arcade Hits (USA) (En,Ja)', '2007', 'Arcade', 'Konami', '2', 'RetroCollection', 'Arcade Collection.', 'Play 15 legendary arcade classics from the 80s.', 'A massive compilation of Konami''s golden age hits.', 'Arcade Hits on NDS brings the arcade experience home. Features wireless multiplayer, adjustable screen orientations, and a gallery of original promotional art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konchuu-wars-japan', 'NDS', 'Konchuu Wars (Japan)', '2008', 'Strategy', 'Nintendo', '2', 'InsectStrategy', 'Tactical RPG.', 'Lead an army of insects in a battle for garden supremacy.', 'A unique strategy game where bugs wage war.', 'Konchuu Wars features grid-based tactical combat. Customize your insect units with mechanical upgrades and outsmart rival swarms in this surprisingly deep strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konductra-usa', 'NDS', 'Konductra (USA)', '2008', 'Action', 'Engient', '1', 'SciFiAction', 'Puzzle.', 'Connect colored lines and clear the board at high speed.', 'A frantic and stylish action-puzzle game.', 'Konductra on NDS challenges your reflexes. Use the stylus to draw paths between blocks, triggering massive chain reactions in this rhythmic and colorful experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konnichiwa-akachan-japan', 'NDS', 'Konnichiwa Akachan (Japan)', '2007', 'Education', 'Benesse', '1', 'ParentingSimulation', 'Simulation / Educational.', 'Learn how to care for a newborn and track development.', 'A helpful guide and simulation for new parents.', 'Konnichiwa Akachan provides practical advice on baby care. From feeding schedules to bathing tips, it’s a supportive tool for those expecting or with a new arrival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kono-quiz-yarou!!-japan', 'NDS', 'Kono Quiz Yarou!! (Japan)', '2006', 'Quiz', 'Nintendo', '1', 'HumorQuiz', 'Trivia / Quiz.', 'Compete in a fast-paced quiz show against quirky rivals.', 'A fun and energetic Japanese trivia challenge.', 'Kono Quiz Yarou!! features thousands of questions across multiple categories. Use the touch screen to buzz in and prove you are the smartest in the room!');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konzentration-und-aufmerksamkeit-1-4-klasse-germany', 'NDS', 'Konzentration und Aufmerksamkeit 1.-4. Klasse (Germany)', '2009', 'Education', 'DTF Games', '1', 'CognitiveTraining', 'Educational.', 'Improve concentration and focus for primary school kids.', 'A German educational trainer for elementary students.', 'Konzentration und Aufmerksamkeit 1.-4. Klasse uses fun puzzles to build mental discipline. These scientifically-backed exercises help children improve their focus in and out of school.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kore-de-haji-o-kakanai---ashita-tsukaeru-ds-business-manner-japan', 'NDS', 'Kore de Haji o Kakanai - Ashita Tsukaeru DS Business Manner (Japan)', '2006', 'Education', 'Nintendo', '1', 'BusinessTraining', 'Educational / Utility.', 'Master professional etiquette and Japanese business manners.', 'A comprehensive guide to success in the corporate world.', 'Ashita Tsukaeru DS Business Manner teaches everything from formal greetings to proper business card exchange. An essential trainer for job hunters and young professionals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('korg-ds-10-synthesizer-europe-enfrdeesit', 'NDS', 'Korg DS-10 Synthesizer (Europe) (En,Fr,De,Es,It)', '2008', 'Music', 'Korg', '1', 'Synthesizer', 'Music / Synth.', 'Create professional electronic music with a legendary synth.', 'A powerful music creation tool based on the Korg MS-10.', 'Korg DS-10 Synthesizer turns your NDS into a production studio. With dual oscillators and a 16-step sequencer, it''s a legitimate tool for musicians and synth enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('korg-ds-10-synthesizer-japan-en', 'NDS', 'Korg DS-10 Synthesizer (Japan) (En)', '2008', 'Music', 'Korg', '1', 'Synthesizer', 'Music / Synth.', 'Create professional electronic music with a legendary synth.', 'A powerful music creation tool based on the Korg MS-10.', 'Korg DS-10 Synthesizer (Japan) provides the same deep synthesis features. Create, save, and share your tracks with a community of portable music makers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('korg-ds-10-synthesizer-usa', 'NDS', 'Korg DS-10 Synthesizer (USA)', '2008', 'Music', 'Korg', '1', 'Synthesizer', 'Music / Synth.', 'Create professional electronic music with a legendary synth.', 'A powerful music creation tool based on the Korg MS-10.', 'Korg DS-10 Synthesizer (USA) allows for complex sound design using the touch screen. It''s an iconic piece of software that pushed the NDS audio hardware to its limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('korg-ds-10+-synthesizer-usa-ndsi-enhanced', 'NDS', 'Korg DS-10+ Synthesizer (USA) (NDSi Enhanced)', '2009', 'Music', 'Korg', '1', 'Synthesizer', 'Music / Synth.', 'Create even more complex tracks with expanded features.', 'A DSi-enhanced version of the legendary synthesizer.', 'Korg DS-10+ takes advantage of the DSi hardware for double the synth power. Features 4 tracks and improved effects, making it the ultimate mobile synth for the DS family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('korg-m01-music-workstation-japan-en', 'NDS', 'Korg M01 Music Workstation (Japan) (En)', '2010', 'Music', 'Korg', '1', 'MusicWorkstation', 'Music / Synth.', 'Compose full songs using 8-part multi-timbral sounds.', 'A high-end music workstation based on the Korg M1.', 'Korg M01 features over 300 sounds and a detailed sequencer. Perfect for composing entire tracks on the go, it captures the essence of the classic 80s workstation for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kotoba-no-puzzle---mojipittan-ds-japan', 'NDS', 'Kotoba no Puzzle - Mojipittan DS (Japan)', '2003', 'Puzzle', 'Namco', '1', 'WordPuzzle', 'Puzzle.', 'Arrange "moji" (letters) to form words and clear the board.', 'A legendary and addictive Japanese word-puzzle game.', 'Kotoba no Puzzle: Mojipittan DS challenges your vocabulary. Connect letters in all directions to create words and fill the stage in this charming and brain-teasing classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kou-rate-ura-mahjong-retsuden---mukoubuchi---goburei-last-desu-ne-japan', 'NDS', 'Kou Rate Ura Mahjong Retsuden - Mukoubuchi - Goburei, Last Desu ne (Japan)', '2009', 'Mahjong', 'Enterbrain', '1', 'TraditionalMahjong', 'Board Game / Mahjong.', 'Win high-stakes Mahjong matches in the underworld.', 'A gritty Mahjong adventure based on the Mukoubuchi manga.', 'Kou Rate Ura Mahjong Retsuden features intense matches and a dramatic story. Face off against skilled gamblers and master the art of the tile to clear your debts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kou-chan-no-shiawase!-kantan!-oryouri-recipe-japan', 'NDS', 'Kou-chan no Shiawase! Kantan! Oryouri Recipe (Japan)', '2008', 'Simulation', 'Success', '1', 'CookingGuide', 'Cooking / Utility.', 'Learn simple and happy recipes from chef Kou-chan.', 'A practical and friendly digital cookbook for beginners.', 'Kou-chan no Shiawase! Oryouri Recipe features easy-to-follow guides for everyday meals. With voice instructions and shopping lists, it makes cooking fun and accessible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouchuu-kakutou---mushi-1-grand-prix-japan', 'NDS', 'Kouchuu Kakutou - Mushi-1 Grand-Prix (Japan)', '2006', 'Action', 'Nintendo', '1', 'InsectCombat', 'Action / Battle.', 'Battle giant beetles in a high-energy wrestling arena.', 'A bug-fighting action game based on the Mushi-1 GP.', 'Kouchuu Kakutou lets you choose your favorite beetle and fight for the championship. Use the touch screen to execute powerful moves and knock out your insect rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouchuu-ouja-mushi-king---greatest-champion-e-no-michi-2-japan', 'NDS', 'Kouchuu Ouja Mushi King - Greatest Champion e no Michi 2 (Japan)', '2008', 'Card Battle / Arcade', 'Sega', '2', 'Strategy', 'Rock-paper-scissors based beetle combat with RPG exploration elements.', 'Become the greatest beetle champion by winning tournaments and collecting cards.', 'Competitive beetle battling RPG sequel for NDS.', 'Experience the thrill of beetle combat in Mushiking: Greatest Champion e no Michi 2. Collect rare beetles, customize their skills with cards, and master the rock-paper-scissors battle system to dominate the championship circuit in this classic Japanese NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouchuu-ouja-mushi-king---greatest-champion-e-no-michi-ds-japan', 'NDS', 'Kouchuu Ouja Mushi King - Greatest Champion e no Michi DS (Japan)', '2009', 'Card Battle / Arcade', 'Sega', '2', 'Strategy', 'Card-based beetle battling with RPG adventure mechanics.', 'Travel across Japan to collect beetle cards and defeat rival trainers.', 'The definitive beetle battling adventure for Nintendo DS.', 'Kouchuu Ouja Mushi King brings the hit arcade beetle-fighting game to the DS. Build a powerful deck of beetles and skill cards, explore diverse environments, and engage in strategic turn-based combat to prove you are the ultimate Mushi King champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouchuu-ouja-mushi-king-super-collection-japan', 'NDS', 'Kouchuu Ouja Mushi King Super Collection (Japan)', '2008', 'Card Battle / Arcade', 'Sega', '2', 'Compilation', 'Collection-focused beetle battling with enhanced arcade-style graphics.', 'Collect the ultimate beetle library and win high-stakes battles.', 'A comprehensive collection of Mushiking beetle battles and cards.', 'Mushiking Super Collection offers fans the most complete beetle battling experience on the NDS. Featuring an extensive roster of insects and powerful skill cards, this title focuses on strategic deck-building and high-energy combat for fans of the arcade original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kouenji-joshi-soccer-2---koi-wa-nebagiba-kouenji-japan', 'NDS', 'Kouenji Joshi Soccer 2 - Koi wa Nebagiba Kouenji (Japan)', '2011', 'Sports', 'Spike', '4', 'Soccer', 'Visual novel with soccer management and dating simulation elements.', 'Lead the girls'' soccer team to victory while managing relationships.', 'High school girls'' soccer management and romance simulation.', 'Kouenji Joshi Soccer 2 combines sports management with a deep visual novel story. Navigate the complexities of high school life, train your female soccer team for the championship, and experience a unique blend of "Never Give Up" spirit and romantic subplots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koukou-juken-eitango-get-through-1900---eitan-zamurai-ds-japan', 'NDS', 'Koukou Juken Eitango Get Through 1900 - Eitan Zamurai DS (Japan)', '2007', 'Educational', 'IE Institute', '1', 'Education', 'Educational mini-games and flashcard-style English vocabulary quizzes.', 'Master 1,900 essential English words for high school entrance exams.', 'Samurai-themed English vocabulary training for students.', 'Koukou Juken Eitango Get Through 1900 turns English study into an adventure. Use the "Eitan Zamurai" system to learn 1,900 critical vocabulary words through interactive DS exercises designed to help Japanese students pass high school entrance exams with ease.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koukou-yakyuu-dou-ds-japan', 'NDS', 'Koukou Yakyuu-dou DS (Japan)', '2008', 'Sports', 'Spike', '4', 'Baseball', 'Baseball management simulation with strategic team building.', 'Guide a high school baseball team to win the Koshien tournament.', 'Realistic high school baseball management sim for NDS.', 'Koukou Yakyuu-dou DS puts you in the dugout as a high school baseball coach. Manage practice schedules, recruit talented players, and make critical tactical decisions during matches to lead your team to victory in the prestigious national tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koushounin-ds-japan', 'NDS', 'Koushounin DS (Japan)', '2009', 'Simulation', 'Idea Factory', '1', 'Business', 'Choice-based visual novel focusing on negotiation and psychological tactics.', 'Resolve high-stakes hostage situations through successful dialogue.', 'Intense police negotiation thriller and visual novel.', 'Step into the shoes of a professional negotiator in Koushounin DS. Use the Nintendo DS touch screen to select the right dialogue choices, analyze criminal psychology, and resolve dangerous standoffs in this gripping, text-heavy detective adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kousoku-card-battle---card-hero-japan', 'NDS', 'Kousoku Card Battle - Card Hero (Japan)', '2007', 'Card Battle', 'Nintendo', '2', 'Strategy', 'Fast-paced strategic card battling with touch-screen controls.', 'Build a deck of "Maru" monsters and win the Card Hero tournament.', 'Nintendo''s cult-classic strategic card battle game.', 'Kousoku Card Battle: Card Hero is the high-speed evolution of the beloved franchise. Featuring deep tactical gameplay, players must manage resources and position monsters strategically to defeat opponents in a quest to become the top-ranked card hero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kreuzwortraetsel-ds---welt-edition-germany', 'NDS', 'Kreuzwortraetsel DS - Welt Edition (Germany)', '2008', 'Puzzle', 'United Soft Media', '1', 'Word Puzzle', 'Touch-screen crossword puzzles with a global theme.', 'Solve hundreds of crossword puzzles across various difficulty levels.', 'German-language crossword puzzle collection for DS.', 'Kreuzwortraetsel DS - Welt Edition offers a portable library of brain-teasing crosswords. Specifically designed for German speakers, this "World Edition" features diverse topics and an intuitive interface that makes solving puzzles on the go easy and fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kumatanchi-japan', 'NDS', 'Kumatanchi (Japan)', '2009', 'Simulation', 'Bandai Namco', '1', 'Virtual Pet', 'Virtual pet simulation and room customization with cute characters.', 'Care for the "Kuma" bears and create a comfortable living space.', 'Adorable bear-themed life simulation from the makers of Doki Doki Majo Shinpan.', 'Kumatanchi is a charming life sim where you look after a group of cute bears. Interact with the characters in real-time, provide for their needs, and watch their stories unfold in this visually stunning and relaxing Japanese cult favorite for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-panda---legendary-warriors-europe-enfrdeesitnl', 'NDS', 'Kung Fu Panda - Legendary Warriors (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Action / Fighting', 'Beenox', '2', 'Beat ''em up', '3D brawler and action-adventure with stylus-based combat.', 'Defeat the Tai Lung remnants and restore peace to the Valley.', 'Action-packed Kung Fu Panda adventure featuring the Furious Five.', 'Kung Fu Panda: Legendary Warriors brings the DreamWorks magic to NDS. Control Po and his friends using unique touch-screen gestures to unleash powerful combos, explore vibrant levels, and defeat waves of enemies in this multi-language European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-panda---legendary-warriors-usa-enfr', 'NDS', 'Kung Fu Panda - Legendary Warriors (USA) (En,Fr)', '2008', 'Action / Fighting', 'Beenox', '2', 'Beat ''em up', '3D brawler and action-adventure with stylus-based combat.', 'Defeat the Tai Lung remnants and restore peace to the Valley.', 'Action-packed Kung Fu Panda adventure featuring the Furious Five.', 'Kung Fu Panda: Legendary Warriors brings the DreamWorks magic to NDS. Control Po and his friends using unique touch-screen gestures to unleash powerful combos, explore vibrant levels, and defeat waves of enemies in this North American action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-panda-europe', 'NDS', 'Kung Fu Panda (Europe)', '2008', 'Action / Adventure', 'XPEC Entertainment', '1', 'Adventure', 'Platforming and combat-oriented action game based on the film.', 'Follow Po''s journey to become the legendary Dragon Warrior.', 'The official movie tie-in action game for Nintendo DS.', 'Relive the story of the first film in Kung Fu Panda for DS. This European version features acrobatic platforming, intuitive touch-screen combat, and a variety of upgrades as Po transforms from a clumsy fan to a martial arts master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-panda-france', 'NDS', 'Kung Fu Panda (France)', '2008', 'Action / Adventure', 'XPEC Entertainment', '1', 'Adventure', 'Platforming and combat-oriented action game based on the film.', 'Follow Po''s journey to become the legendary Dragon Warrior.', 'The official movie tie-in action game for Nintendo DS.', 'Relive the story of the first film in Kung Fu Panda for DS. This French version features acrobatic platforming, intuitive touch-screen combat, and a variety of upgrades as Po transforms from a clumsy fan to a martial arts master.');
