INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-panda-korea', 'NDS', 'Kung Fu Panda (Korea)', '2008', 'Action / Adventure', 'XPEC Entertainment', '1', 'Adventure', 'Platforming and combat-oriented action game based on the film.', 'Follow Po''s journey to become the legendary Dragon Warrior.', 'The official movie tie-in action game for Nintendo DS.', 'Relive the story of the first film in Kung Fu Panda for DS. This Korean version features acrobatic platforming, intuitive touch-screen combat, and a variety of upgrades as Po transforms from a clumsy fan to a martial arts master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-panda-netherlands', 'NDS', 'Kung Fu Panda (Netherlands)', '2008', 'Action / Adventure', 'XPEC Entertainment', '1', 'Adventure', 'Platforming and combat-oriented action game based on the film.', 'Follow Po''s journey to become the legendary Dragon Warrior.', 'The official movie tie-in action game for Nintendo DS.', 'Relive the story of the first film in Kung Fu Panda for DS. This Dutch version features acrobatic platforming, intuitive touch-screen combat, and a variety of upgrades as Po transforms from a clumsy fan to a martial arts master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-panda-spain', 'NDS', 'Kung Fu Panda (Spain)', '2008', 'Action / Adventure', 'XPEC Entertainment', '1', 'Adventure', 'Platforming and combat-oriented action game based on the film.', 'Follow Po''s journey to become the legendary Dragon Warrior.', 'The official movie tie-in action game for Nintendo DS.', 'Relive the story of the first film in Kung Fu Panda for DS. This Spanish version features acrobatic platforming, intuitive touch-screen combat, and a variety of upgrades as Po transforms from a clumsy fan to a martial arts master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-panda-usa', 'NDS', 'Kung Fu Panda (USA)', '2008', 'Action / Adventure', 'XPEC Entertainment', '1', 'Adventure', 'Platforming and combat-oriented action game based on the film.', 'Follow Po''s journey to become the legendary Dragon Warrior.', 'The official movie tie-in action game for Nintendo DS.', 'Relive the story of the first film in Kung Fu Panda for DS. This North American version features acrobatic platforming, intuitive touch-screen combat, and a variety of upgrades as Po transforms from a clumsy fan to a martial arts master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-panda-2-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Kung Fu Panda 2 (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2011', 'Action / Adventure', 'Griptonite Games', '1', 'Adventure', 'Beat ''em up and strategy-action using the NDSi camera for customization.', 'Defeat Lord Shen and his wolf army to save Kung Fu.', 'The thrilling sequel adventure with DSi enhanced features.', 'Kung Fu Panda 2 on DS takes the fight to Lord Shen. Utilize unique combat styles, solve environmental puzzles, and take advantage of NDSi enhanced features to customize your experience as you lead the Furious Five in an epic battle across China.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-zhu-europe', 'NDS', 'Kung Zhu (Europe)', '2011', 'Action / Adventure', 'Game Factory', '1', 'Action', 'Side-scrolling action platformer based on the Kung Zhu toy line.', 'Battle through enemy territories to reach the Zhu-Niverse.', 'High-energy hamster combat and platforming action.', 'Kung Zhu transforms the popular motorized hamsters into elite warriors. Choose your favorite Zhu Zhu Pet, equip them with heavy armor and weapons, and fight through side-scrolling levels filled with enemies and hazards in this European exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kunio-kun-no-chou-nekketsu!---daiundoukai-japan', 'NDS', 'Kunio-kun no Chou Nekketsu! - Daiundoukai (Japan)', '2010', 'Sports', 'Arc System Works', '4', 'Sports Party', 'Retro-style sports and brawler featuring Kunio and Riki.', 'Compete in a variety of athletic events and win by any means.', 'Over-the-top high school sports competition for DS.', 'Kunio-kun no Chou Nekketsu! - Daiundoukai brings back the classic "Downtown" sports chaos. Participate in running, swimming, and fighting events where violence isn''t just allowed—it''s encouraged. A perfect nostalgic trip for fans of the River City Ransom series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kunio-kun-no-chou-nekketsu!---soccer-league-plus---world-hyper-cup-hen-japan', 'NDS', 'Kunio-kun no Chou Nekketsu! - Soccer League Plus - World Hyper Cup Hen (Japan)', '2010', 'Sports', 'Arc System Works', '4', 'Soccer', 'Arcady soccer game with super-moves and aggressive playstyles.', 'Win the World Hyper Cup by defeating international soccer teams.', 'Super-powered soccer action featuring the Kunio-kun cast.', 'This is soccer like you''ve never seen it! Kunio-kun no Chou Nekketsu! Soccer League Plus features physics-defying special shots, muddy pitches, and aggressive tackles. Lead Kunio''s team to global glory in this hyper-kinetic sports title for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kunitori-zunou-battle---nobunaga-no-yabou-japan', 'NDS', 'Kunitori Zunou Battle - Nobunaga no Yabou (Japan)', '2009', 'Strategy', 'Koei', '1', 'Strategy', 'Turn-based strategy and board game hybrid with a Sengoku theme.', 'Conquer the provinces of Japan to unify the country under one banner.', 'Strategic "Game of Go" style conquest in feudal Japan.', 'Kunitori Zunou Battle: Nobunaga no Yabou blends the deep strategy of Nobunaga''s Ambition with accessible, board-game style mechanics. Outsmart rival warlords, manage your territory, and use tactical maneuvers to seize control of Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kupuu!!-mamegoma!-japan', 'NDS', 'Kupuu!! Mamegoma! (Japan)', '2008', 'Simulation', 'Bandai Namco', '1', 'Virtual Pet', 'Virtual pet simulation for the Mamegoma seal characters.', 'Care for your baby seal and participate in mini-games.', 'Relaxing seal-raising simulation for all ages.', 'Kupuu!! Mamegoma! is a gentle simulation game where you raise the adorable palm-sized seals known as Mamegoma. Feed them, clean them, and play mini-games to bond with your aquatic pets in this charming and stress-free Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurayami-no-hate-de-kimi-o-matsu-japan', 'NDS', 'Kurayami no Hate de Kimi o Matsu (Japan)', '2007', 'RPG', 'Bandai Namco', '1', 'RPG', 'Otome visual novel with suspense and horror elements.', 'Solve the mystery of a haunted school and find romance.', 'A dark, romantic suspense visual novel for a female audience.', 'Kurayami no Hate de Kimi o Matsu (Waiting for You at the Edge of Darkness) is a gripping Otome game. Trapped in an abandoned school, you must solve puzzles and make choices that determine your survival and your romantic destiny with one of several male companions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurikin---nano-island-story-japan', 'NDS', 'Kurikin - Nano Island Story (Japan)', '2008', 'Action', 'Bandai Namco', '1', 'Platformer', 'Strategic "micro-organism" battle game using the stylus.', 'Conquer the island by breeding and commanding colonies of "Kurikin."', 'Unique real-time strategy with microscopic creatures.', 'Kurikin: Nano Island Story is a hidden gem on the DS. Use the stylus to guide colonies of bacteria-like creatures in real-time battles. Manage different species with unique strengths and weaknesses to dominate the microscopic ecosystem of Nano Island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurikuri-ds---otasuke-island-japan', 'NDS', 'Kurikuri DS - Otasuke Island (Japan)', '2009', 'Action / Adventure', 'Square Enix', '1', 'Adventure', 'Action-puzzle game featuring competitive "spinning" mechanics.', 'Clear stages and defeat opponents by manipulating objects on screen.', 'A colorful and quirky action-puzzler sequel.', 'Kurikuri DS: Otasuke Island brings the chaotic puzzle fun of the original to the handheld. Use the dual screens and touch controls to solve environmental puzzles and outmaneuver rivals in this vibrant, high-energy title from FromSoftware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuroshitsuji---phantom-&-ghost-japan', 'NDS', 'Kuroshitsuji - Phantom & Ghost (Japan)', '2007', 'Action', 'Bandai Namco', '1', 'Arcade', 'Adventure and mystery visual novel based on the Black Butler anime.', 'Solve cases as Ciel and Sebastian while maintaining the Phantomhive honor.', 'A gothic mystery adventure set in Victorian London.', 'Kuroshitsuji: Phantom & Ghost allows players to step into the world of the hit anime. Switch between Ciel and his demonic butler Sebastian to gather clues, interact with iconic characters, and solve original mysteries through touch-screen mini-games and dialogue.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurukuru-chameleon-ds-japan', 'NDS', 'KuruKuru Chameleon DS (Japan)', '2007', 'Action', 'Bandai Namco', '1', 'Arcade', 'Competitive color-matching puzzle game with a revolving mechanic.', 'Clear the board of colored blocks before your opponent does.', 'Fast-paced chameleon-themed puzzle action.', 'KuruKuru Chameleon DS is a frantic puzzle game where you must match colors by rotating a central grid. With multiple modes and quirky characters, it offers a fresh take on the match-3 genre, perfect for quick sessions or competitive multiplayer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurukuru-princess---figure-de-kirakira-koori-no-angel-japan', 'NDS', 'KuruKuru Princess - Figure de KiraKira Koori no Angel (Japan)', '2008', 'Sports', 'Taito', '1', 'Figure Skating', 'Rhythm-based figure skating simulation with touch controls.', 'Perform perfect routines and win the ice skating championship.', 'Cute figure skating rhythm game for NDS.', 'KuruKuru Princess - Figure de KiraKira Koori no Angel features rhythmic touch-screen gameplay. Guide your skater through beautiful ice routines, customize her outfits, and compete to become the ultimate ice angel in this charming Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurukuru-princess---tokimeki-figure---mezase!-vancouver-japan', 'NDS', 'KuruKuru Princess - Tokimeki Figure - Mezase! Vancouver (Japan)', '2009', 'Sports', 'Taito', '1', 'Figure Skating', 'Sport simulation and rhythm game with a winter Olympics theme.', 'Train hard and win the gold medal at the Vancouver games.', 'Olympic-themed figure skating and training sim.', 'KuruKuru Princess - Tokimeki Figure - Mezase! Vancouver lets you experience the journey of an Olympic skater. Balance practice, social life, and high-stakes competitions as you aim for the podium in Vancouver using intuitive DS stylus controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurukuru-princess---yume-no-white-quartet-japan', 'NDS', 'KuruKuru Princess - Yume no White Quartet (Japan)', '2007', 'Sports', 'Taito', '1', 'Figure Skating', 'Multi-character rhythm and skating simulation.', 'Lead a team of four skaters to success in the White Quartet.', 'Figure skating team management and rhythm action.', 'KuruKuru Princess - Yume no White Quartet expands the series with four playable characters. Master complex skating maneuvers on the touch screen, unlock elegant costumes, and perform synchronized routines to win the hearts of the judges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurupoto---atama-ni-piritto-supplement-puzzle-japan', 'NDS', 'Kurupoto - Atama ni Piritto Supplement Puzzle (Japan)', '2007', 'Puzzle', 'Namco Bandai', '1', 'Brain Training', 'Physics-based puzzle game involving rotating the game world.', 'Guide falling stars into their targets by spinning the environment.', 'Brain-teasing gravity and rotation puzzle game.', 'Kurupoto: Atama ni Piritto Supplement Puzzle challenges your spatial reasoning. Rotate the entire puzzle field to maneuver stars through obstacles, providing a "brain supplement" of logic puzzles that range from simple to highly complex.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurupoto---cool-cool-stars-usa', 'NDS', 'Kurupoto - Cool Cool Stars (USA)', '2008', 'Puzzle', 'Namco Bandai', '1', 'Arcade Puzzle', 'Physics-based puzzle game involving rotating the game world.', 'Guide falling stars into their targets by spinning the environment.', 'US version of the gravity-shifting puzzle hit.', 'Kurupoto: Cool Cool Stars is the North American release of the addictive rotation puzzler. Use the DS stylus to flip and turn the world, helping stars reach their destination through dozens of increasingly difficult, physics-based levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kururin-doughnut---okashi-na-recipe-japan', 'NDS', 'Kururin Doughnut - Okashi na Recipe (Japan)', '2009', 'Simulation', 'Namco Bandai', '1', 'Cooking', 'Cooking and puzzle hybrid focused on making doughnuts.', 'Run a successful bakery by creating the perfect doughnut recipes.', 'Sweet doughnut-making simulation and puzzle game.', 'Kururin Doughnut: Okashi na Recipe lets you play as a pastry chef. Mix ingredients, shape dough, and decorate delicious doughnuts using the touch screen in a series of fun mini-games designed for casual players and fans of cooking sims.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kutsushita-nyanko---shiroi-kutsushita-o-haita-neko-to-kurashi-hajimemashita-japan', 'NDS', 'Kutsushita Nyanko - Shiroi Kutsushita o Haita Neko to Kurashi Hajimemashita. (Japan)', '2008', 'Simulation', 'Namco Bandai', '1', 'Virtual Pet', 'Virtual pet simulation and room decoration.', 'Care for the "Sock Cat" and create a cozy home for your pets.', 'Heartwarming life simulation with San-X characters.', 'Kutsushita Nyanko: Shiroi Kutsushita o Haita Neko brings the famous "cat with socks" to the DS. Bond with your feline friends, buy furniture to decorate your room, and enjoy a relaxing, slow-paced life with these adorable Japanese mascot characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuukan-zukei---hirameki-training---kuutore-japan', 'NDS', 'Kuukan Zukei - Hirameki Training - Kuutore (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Brain Training', 'Educational brain training focused on 3D geometry.', 'Solve 3D spatial puzzles to improve mental visualization.', '3D spatial awareness and geometry training tool.', 'Kuukan Zukei: Hirameki Training - Kuutore is designed to sharpen your mind. Through a variety of 3D visualization exercises and geometric puzzles, this educational title helps users improve their ability to perceive and manipulate objects in three-dimensional space.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuwagata-tsumami---kuttsuke!-tsumami-bako-japan', 'NDS', 'Kuwagata Tsumami - Kuttsuke! Tsumami Bako (Japan)', '2009', 'Puzzle', 'Takara Tomy', '1', 'Logic Puzzle', 'Mini-game collection based on the Kuwagata Tsumami anime.', 'Win various touch-screen challenges starring the beetle girl.', 'Quirky Japanese mini-games based on the popular anime.', 'Kuwagata Tsumami - Kuttsuke! Tsumami Bako is a collection of fast-paced, humorous mini-games. Utilize every feature of the DS to help the tiny beetle-girl Tsumami and her family through a series of bizarre and entertaining daily life challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyokugen-dasshutsu---9-jikan-9-nin-9-no-tobira-japan', 'NDS', 'Kyokugen Dasshutsu - 9-jikan, 9-nin, 9 no Tobira (Japan)', '2009', 'Adventure', 'Spike Chunsoft', '1', 'Visual Novel', 'Visual novel with "Escape the Room" puzzle segments.', 'Escape the sinking ship by solving puzzles and making life-or-death choices.', 'Intense psychological thriller and escape room masterpiece.', 'Kyokugen Dasshutsu (9 Hours, 9 Persons, 9 Doors) is a gripping narrative experience. Solve intricate puzzles to unlock doors while navigating a dark story with multiple endings where every choice determines who lives and who dies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyou-kara-ds---calorie-navi-japan', 'NDS', 'Kyou kara DS - Calorie Navi (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Health', 'Health and nutrition management tool for calorie counting.', 'Track daily food intake and exercise to reach weight goals.', 'Practical calorie navigation and diet tracking software.', 'Kyou kara DS: Calorie Navi turns your NDS into a personal nutritionist. With an extensive database of Japanese foods, you can log meals, calculate calorie burn, and monitor your health progress through easy-to-read graphs and expert advice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyouryuu-ikusei-battle-rpg---kyouryuu-monster-japan', 'NDS', 'Kyouryuu Ikusei Battle RPG - Kyouryuu Monster (Japan)', '2008', 'RPG', 'Takara Tomy', '1', 'RPG', 'Monster-collecting RPG with dinosaur raising and combat.', 'Excavate fossils, revive dinosaurs, and win the battle league.', 'Dinosaur-themed RPG with creature breeding and battles.', 'Kyouryuu Ikusei Battle RPG: Kyouryuu Monster lets you become a dino-master. Explore prehistoric lands, dig for fossils using the stylus, and train your prehistoric beasts to compete in strategic turn-based battles for the championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyouryuu-ouja-ketteisen---kyouryuu-grand-prix-japan', 'NDS', 'Kyouryuu Ouja Ketteisen - Kyouryuu Grand Prix (Japan)', '2008', 'Action', 'Takara Tomy', '2', 'Action', 'Action-oriented dinosaur battle game with card elements.', 'Win the Grand Prix by defeating rival dinosaur trainers.', 'Competitive dinosaur tournament and action-battle game.', 'Kyouryuu Ouja Ketteisen: Kyouryuu Grand Prix features high-energy dinosaur fights. Use different skills and attributes to outmatch opponents in the arena, focusing on fast reflexes and tactical creature match-ups to win the ultimate title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyouryuu-taisen-dino-champ---saikyou-dna-hakkutsu-daisakusen-japan', 'NDS', 'Kyouryuu Taisen Dino Champ - Saikyou DNA Hakkutsu Daisakusen (Japan)', '2009', 'Action', 'Takara Tomy', '2', 'Action', 'Fossil excavation and DNA-based dinosaur RPG.', 'Collect DNA samples to create the strongest "Dino Champ."', 'Strategic dinosaur excavation and battling adventure.', 'Kyouryuu Taisen Dino Champ features a deep excavation mechanic. Use the DS touch screen to carefully uncover fossils, extract DNA to customize your dinosaurs, and engage in tactical combat to see which species truly reigns supreme.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyuukyuu-kyuumei-caduceus-2-japan', 'NDS', 'Kyuukyuu Kyuumei Caduceus 2 (Japan)', '2008', 'Simulation', 'Atlus', '1', 'Medical', 'Medical simulation with touch-screen surgical procedures.', 'Save patients by performing complex surgeries under pressure.', 'Intense surgical action-drama (Trauma Center sequel).', 'Kyuukyuu Kyumei Caduceus 2 (Trauma Center: Under the Knife 2) returns to the high-stakes world of medicine. Use your stylus as a scalpel, laser, and needle to treat exotic diseases and emergency traumas in this fast-paced medical thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('l---the-prologue-to-death-note---rasen-no-trap-japan', 'NDS', 'L - The Prologue to Death Note - Rasen no Trap (Japan)', '2008', 'Adventure', 'Konami', '1', 'Visual Novel', 'Mystery adventure and puzzle-solving based on the Death Note series.', 'Solve a series of traps set by Kira as the detective L.', 'Psychological mystery and trap-defying puzzle game.', 'L: The Prologue to Death Note - Rasen no Trap is a prequel to the hit anime. Play as the legendary detective L, solving environmental puzzles and deactivating traps in a race against time to outsmart your opponents in this tense investigation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('l---the-prologue-to-death-note---rasen-no-trap-japan-t-en-by-anime-game-translations-team-v12', 'NDS', 'L - The Prologue to Death Note - Rasen no Trap (Japan) [T-En by Anime Game Translations Team v1.2]', '2008', 'Adventure', 'Konami', '1', 'Visual Novel', 'Mystery adventure and puzzle-solving based on the Death Note series.', 'Solve a series of traps set by Kira as the detective L.', 'English-translated version of the L prequel mystery.', 'This fan-translated version of Rasen no Trap allows English speakers to experience L''s investigation. Navigate a dangerous building, use L''s unique logic to solve puzzles, and uncover the story leading up to the events of the Death Note series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lol-usa', 'NDS', 'L.O.L. (USA)', '2008', 'Action', 'Electronic Arts', '4', 'Party', 'Experimental life simulation with minimalist graphics.', 'Interact with a virtual creature to see how it evolves.', 'Quirky and experimental "Lack of Love" simulation.', 'L.O.L. (Lack of Love) is a unique simulation where you interact with a small organism. By influencing its environment and communicating through simple actions, you watch it grow and adapt in this artistic and non-traditional handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('labyrinth-europe-enfrdeesit', 'NDS', 'Labyrinth (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Creatures', '4', 'Board Game', 'Digital version of the classic Ravensburger board game.', 'Move through the shifting maze to collect all your treasures.', 'Classic tile-shifting board game for Nintendo DS.', 'Labyrinth brings the beloved family board game to life. Shift the walls of the maze to create new paths and block your opponents. This European version features multiple modes and the classic strategic gameplay that has made the physical game a hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('labyrinth-europe-enfrdeit-rev-1-ravensburger', 'NDS', 'Labyrinth (Europe) (En,Fr,De,It) (Rev 1) (Ravensburger)', '2009', 'Puzzle', 'Ravensburger', '4', 'Board Game', 'Digital version of the classic Ravensburger board game.', 'Move through the shifting maze to collect all your treasures.', 'Updated digital board game with Ravensburger branding.', 'This revised edition of Labyrinth offers refined controls and the same addictive board game logic. Perfect for fans of strategy, it allows for portable play of the classic "shoving" maze game against AI or friends in this European multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('labyrinth-europe-enfrde-ravensburger', 'NDS', 'Labyrinth (Europe) (En,Fr,De) (Ravensburger)', '2009', 'Puzzle', 'Ravensburger', '4', 'Board Game', 'Digital version of the classic Ravensburger board game.', 'Move through the shifting maze to collect all your treasures.', 'Authentic Ravensburger maze strategy game.', 'Experience the official Ravensburger Labyrinth on your DS. Navigate a constantly changing maze by strategically shifting corridors to reach your objectives first in this high-quality digital adaptation of the world-famous strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('labyrinth-europe-frnl-ravensburger', 'NDS', 'Labyrinth (Europe) (Fr,Nl) (Ravensburger)', '2009', 'Puzzle', 'Ravensburger', '4', 'Board Game', 'Digital version of the classic Ravensburger board game.', 'Move through the shifting maze to collect all your treasures.', 'French/Dutch language edition of the strategy classic.', 'This specific regional release of Labyrinth provides the full board game experience for French and Dutch speakers. Master the art of maze manipulation and outthink your opponents in this portable version of the Ravensburger classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('labyrinth-usa', 'NDS', 'Labyrinth (USA)', '2009', 'Puzzle', 'Ravensburger', '4', 'Board Game', 'Digital version of the classic Ravensburger board game.', 'Move through the shifting maze to collect all your treasures.', 'The North American release of the shifting maze game.', 'Labyrinth for the USA market brings the strategy and fun of the original board game to the NDS. Slide maze tiles to reach treasures while navigating a board that changes with every turn, offering endless replayability for puzzle lovers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lakitu', 'NDS', 'Lakitu', '2008', 'Action', 'Nintendo', '1', 'Arcade', 'Platforming and puzzle-solving featuring Lakitu characters.', 'Navigate levels using clouds and environmental interaction.', 'Niche platformer/puzzle title featuring classic Mario enemies.', 'Lakitu focuses on the sky-dwelling characters from the Mario universe. Use unique cloud-based mechanics to navigate levels, avoid hazards, and solve environmental puzzles in this charming, albeit lesser-known, handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lanfeust-of-troy-europe-enfrdeesit', 'NDS', 'Lanfeust of Troy (Europe) (En,Fr,De,Es,It)', '2007', 'Action / Adventure', 'Atari', '1', 'Adventure', 'Action-adventure RPG based on the French comic series.', 'Save the world of Troy by mastering the power of Magohamoth.', 'Epic fantasy RPG based on the popular Lanfeust comic.', 'Lanfeust of Troy brings the vibrant world of the comics to the DS. Engage in tactical combat, explore the vast world of Troy, and utilize the unique magical powers of the protagonists in this action-packed quest to stop the villainous Thanos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langenscheidt-basic-woerterbuch-englisch-europe-enfrdeesit', 'NDS', 'Langenscheidt Basic-Woerterbuch Englisch (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Langenscheidt', '1', 'Dictionary', 'Language learning tool for basic English vocabulary.', 'Learn fundamental English words and phrases for daily use.', 'English dictionary and basic language trainer.', 'Langenscheidt Basic-Woerterbuch Englisch is a practical tool for non-English speakers. Featuring a robust dictionary and interactive exercises, it helps users build a foundation in English through the convenience of the Nintendo DS touch screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langenscheidt-vokabelstar-englisch-fuer-einsteiger-europe-enfrdeesit', 'NDS', 'Langenscheidt VokabelStar Englisch fuer Einsteiger (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Langenscheidt', '1', 'Language Learning', 'Interactive vocabulary trainer for English beginners.', 'Master essential English vocabulary through repetitive training.', 'Beginner-level English vocabulary training software.', 'VokabelStar Englisch fuer Einsteiger uses the Langenscheidt method to teach English. With voice output and various testing modes, it provides an effective way for beginners to memorize and retain important words and phrases on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langenscheidt-vokabelstar-englisch-fuer-fortgeschrittene-europe-enfrdeesit', 'NDS', 'Langenscheidt VokabelStar Englisch fuer Fortgeschrittene (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Langenscheidt', '1', 'Language Learning', 'Interactive vocabulary trainer for intermediate English learners.', 'Expand your English vocabulary with advanced terms and concepts.', 'Advanced English vocabulary training for NDS.', 'Designed for those who already have a foundation, VokabelStar fuer Fortgeschrittene pushes your English skills further. Focus on complex terminology and advanced usage through specialized drills and the comprehensive Langenscheidt database.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lapin-malin---japprends-a-lire-et-a-ecrire-france', 'NDS', 'Lapin Malin - J''Apprends a Lire et a Ecrire (France)', '2007', 'Educational', 'Mindscape', '1', 'Education', 'Educational mini-games for reading and writing skills.', 'Help the rabbit character solve puzzles to learn French literacy.', 'French language early-learning software for children.', 'Lapin Malin (Reader Rabbit) is designed to help young children develop literacy skills. Through engaging mini-games and colorful characters, kids learn to read and write in French while exploring a fun, interactive world on their DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lara-croft-tomb-raider---legend-europe-enfrdeesit', 'NDS', 'Lara Croft Tomb Raider - Legend (Europe) (En,Fr,De,Es,It)', '2006', 'Action / Adventure', 'Crystal Dynamics', '1', 'Action Adventure', 'Third-person action-adventure with platforming and puzzles.', 'Recover the lost pieces of a mythical sword across the globe.', 'Lara Croft''s epic global adventure on the handheld.', 'Tomb Raider: Legend brings the full Lara Croft experience to the DS. Explore ancient ruins, utilize high-tech gadgets, and engage in cinematic combat and platforming as Lara searches for the truth about her past in this multi-language European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lara-croft-tomb-raider---legend-usa-enfrdeesit', 'NDS', 'Lara Croft Tomb Raider - Legend (USA) (En,Fr,De,Es,It)', '2006', 'Action / Adventure', 'Crystal Dynamics', '1', 'Action Adventure', 'Third-person action-adventure with platforming and puzzles.', 'Recover the lost pieces of a mythical sword across the globe.', 'North American release of the hit Tomb Raider title.', 'Join Lara Croft in her search for Excalibur in the US version of Tomb Raider: Legend. Featuring 3D environments, touch-screen inventory management, and intense action sequences, this title captures the spirit of the console versions in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-bullet-japan', 'NDS', 'Last Bullet (Japan)', '2008', 'Action', 'Konami', '1', 'Action', 'Sniper-based action adventure with visual novel storytelling.', 'Take down targets with precision while uncovering a dark conspiracy.', 'Intense sniper action and mystery visual novel.', 'Last Bullet combines high-stakes sniping missions with a deep narrative. As Karin, a female sniper, you must use the DS stylus to steady your aim, account for wind, and eliminate targets across various urban environments while navigating a complex Japanese storyline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-window---mayonaka-no-yakusoku-japan', 'NDS', 'Last Window - Mayonaka no Yakusoku (Japan)', '2010', 'Adventure', 'CING', '1', 'Detective', 'Noir-style point-and-click adventure with touch-based puzzles.', 'Solve the mystery of a hidden treasure in the Cape West Apartments.', 'The acclaimed sequel to Hotel Dusk: Room 215.', 'Last Window: Mayonaka no Yakusoku follows Kyle Hyde in 1980s Los Angeles. Featuring a unique "sketchbook" art style, players must hold the DS like a book to interview suspects, solve environmental puzzles, and uncover the truth behind Kyle''s father''s past.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-window---the-secret-of-cape-west-europe-enfrdeesit', 'NDS', 'Last Window - The Secret of Cape West (Europe) (En,Fr,De,Es,It)', '2010', 'Adventure', 'CING', '1', 'Detective', 'Noir-style point-and-click adventure with touch-based puzzles.', 'Solve the mystery of a hidden treasure in the Cape West Apartments.', 'Detective Kyle Hyde returns in this atmospheric mystery.', 'Last Window: The Secret of Cape West is the European English release of the hit noir adventure. Engage in deep dialogue, manipulate objects with the stylus, and enjoy a rich, jazz-infused story that concludes the saga of ex-cop Kyle Hyde in a gripping finale.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('layton-gyosuwa-isanghan-maeul-korea', 'NDS', 'Layton Gyosuwa Isanghan Maeul (Korea)', '2009', 'Puzzle', 'Level-5', '1', 'Brain Training', 'Puzzle-solving adventure with logic riddles and brain teasers.', 'Solve the mystery of the Golden Apple in the town of St. Mystere.', 'Korean version of the famous Professor Layton debut.', 'Layton Gyosuwa Isanghan Maeul brings the charming puzzles of Professor Layton to the Korean audience. Explore a hand-drawn world, solve over 130 logic puzzles, and enjoy fully voiced cutscenes as you unravel the secrets of a mysterious village.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('layton-kyouju-to-akuma-no-hako---friendly-ban-japan', 'NDS', 'Layton Kyouju to Akuma no Hako - Friendly Ban (Japan)', '2007', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Logic puzzle adventure with enhanced difficulty and extra hints.', 'Discover the truth behind the cursed Pandora''s Box.', 'Enhanced "Friendly" edition of the Diabolical Box.', 'Layton Kyouju to Akuma no Hako - Friendly Ban is an updated Japanese version featuring more accessible hints and localized adjustments. Travel on the Molentary Express and solve intricate brain teasers in this beloved sequel to the Layton franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('layton-kyouju-to-akuma-no-hako-japan', 'NDS', 'Layton Kyouju to Akuma no Hako (Japan)', '2007', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Logic puzzle adventure with brain teasers and narrative exploration.', 'Investigate the deaths linked to the mysterious Pandora''s Box.', 'The classic Japanese release of the Diabolical Box.', 'Layton Kyouju to Akuma no Hako set the standard for puzzle adventures. Join Layton and Luke as they travel across the country, meeting eccentric characters and solving dozens of "Akira Tago" puzzles to stop the curse of the Diabolical Box.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('layton-kyouju-to-fushigi-na-machi---friendly-ban-japan', 'NDS', 'Layton Kyouju to Fushigi na Machi - Friendly Ban (Japan)', '2005', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Puzzle-solving adventure with improved UI and easier hint access.', 'Find the Golden Apple and inherit a massive fortune.', 'Enhanced "Friendly" edition of the Curious Village.', 'This "Friendly Ban" version of the first Layton game offers a more polished experience for Japanese players. It includes refined puzzle descriptions and an easier entry point for newcomers to the series'' signature blend of logic and mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('layton-kyouju-to-fushigi-na-machi-japan', 'NDS', 'Layton Kyouju to Fushigi na Machi (Japan)', '2005', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Logic puzzle adventure with brain teasers and narrative exploration.', 'Solve the town''s riddles to find the legendary Golden Apple.', 'The original Japanese debut of Professor Layton.', 'Layton Kyouju to Fushigi na Machi introduced the world to the gentleman detective. Using the stylus to input answers, players solve 135 puzzles ranging from math riddles to sliding blocks in a beautifully animated adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('layton-kyouju-to-fushigi-na-machi-japan-rev-2', 'NDS', 'Layton Kyouju to Fushigi na Machi (Japan) (Rev 2)', '2005', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Logic puzzle adventure with brain teasers and narrative exploration.', 'Solve the town''s riddles to find the legendary Golden Apple.', 'Revised 2nd edition of the first Layton game.', 'This Revision 2 of the Japanese original includes bug fixes and minor text adjustments, ensuring the smoothest possible puzzle-solving experience as you explore the whimsical and secret-filled town of St. Mystere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('layton-kyouju-to-majin-no-fue-japan', 'NDS', 'Layton Kyouju to Majin no Fue (Japan)', '2009', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Prequel adventure with logic puzzles and RPG-lite elements.', 'Investigate the legend of a "specter" destroying a misty town.', 'The first prequel in the Professor Layton series.', 'Layton Kyouju to Majin no Fue (The Last Specter) explores the origins of Layton and Luke''s partnership. Solve a new set of challenging riddles and enjoy the "London Life" bonus RPG mode included in this expansive Japanese release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('layton-kyouju-to-saigo-no-jikan-ryokou-japan', 'NDS', 'Layton Kyouju to Saigo no Jikan Ryokou (Japan)', '2008', 'Puzzle', 'Level-5', '1', 'Puzzle Adventure', 'Time-traveling puzzle adventure with a cinematic story.', 'Save future London from a mysterious scientific threat.', 'The epic conclusion to the first Layton trilogy.', 'Layton Kyouju to Saigo no Jikan Ryokou (Unwound Future) takes the duo to a futuristic London. Solve the most complex puzzles yet and experience an emotional story involving time machines and the Professor''s own tragic past.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('learn-chess-usa', 'NDS', 'Learn Chess (USA)', '2005', 'Educational', 'Odyssey Interactive', '2', 'Board Game', 'Strategy board game with tutorials and move analysis.', 'Learn the rules of chess and defeat AI opponents.', 'Educational chess trainer for beginners and pros.', 'Learn Chess on NDS offers a portable way to master the classic game. Featuring interactive lessons on openings, tactics, and endgames, it provides a comprehensive training ground for players of all ages to improve their ELO rating.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('learn-geography-usa-enfres', 'NDS', 'Learn Geography (USA) (En,Fr,Es)', '2007', 'Educational', 'Odyssey Interactive', '1', 'Education', 'Educational trivia and map-based mini-games.', 'Master world geography, capitals, and cultural facts.', 'Fun and interactive geography learning tool.', 'Learn Geography makes world facts accessible through the DS touch screen. Explore maps, identify flags, and take quizzes in English, French, or Spanish to expand your global knowledge through engaging, gamified lessons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('learn-math-usa-enes', 'NDS', 'Learn Math (USA) (En,Es)', '2007', 'Educational', 'Odyssey Interactive', '1', 'Education', 'Educational math drills and logic challenges.', 'Improve arithmetic skills across various difficulty levels.', 'Practical math tutor for students and adults.', 'Learn Math provides a structured curriculum for improving mental math. From basic addition to complex algebra, the game tracks your progress and offers bilingual support in English and Spanish to help you master numbers anywhere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('learn-science-usa', 'NDS', 'Learn Science (USA)', '2007', 'Educational', 'Odyssey Interactive', '1', 'Education', 'Science trivia and interactive experiments.', 'Learn core concepts of biology, physics, and chemistry.', 'Comprehensive science education game for the NDS.', 'Learn Science covers a wide range of scientific topics through interactive mini-games. Perfect for students, it uses the DS stylus to simulate experiments and tests your knowledge with thousands of questions across multiple scientific disciplines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('learn-to-play-chess-with-fritz-&-chesster-europe-enfrdeesit', 'NDS', 'Learn to Play Chess with Fritz & Chesster (Europe) (En,Fr,De,Es,It)', '2006', 'Educational', 'Chessbase', '2', 'Board Game', 'Story-driven chess tutorials for children.', 'Save the king from the black king by learning chess moves.', 'Child-friendly chess adventure based on the PC series.', 'Learn to Play Chess with Fritz & Chesster turns a complex game into a fun adventure. Through a series of mini-games that teach how pieces move, kids learn professional chess strategies without even realizing they are studying.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('learning-maths-europe-enfrit', 'NDS', 'Learning Maths (Europe) (En,Fr,It)', '2007', 'Educational', 'Oxygen Studios', '1', 'Education', 'Math-focused educational mini-games and quizzes.', 'Complete daily exercises to improve mathematical speed.', 'European math training tool for younger students.', 'Learning Maths provides a series of mental arithmetic challenges designed for the European school curriculum. Track your improvement over time and master multiplication tables and logic puzzles in English, French, or Italian.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lecons-de-cuisine---quallons-nous-manger-aujourdhui-france', 'NDS', 'Lecons de Cuisine - Qu''Allons-Nous Manger Aujourd''hui (France)', '2008', 'Simulation', 'Namco Bandai', '1', 'Cooking', 'Interactive digital cookbook with voice recognition.', 'Follow step-by-step recipes to cook delicious meals.', 'The definitive French digital cooking assistant.', 'Lecons de Cuisine (Cooking Guide) turns your DS into a chef''s assistant. Use voice commands to turn pages while your hands are busy, follow 250+ international recipes, and learn culinary techniques through helpful video demonstrations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lecons-de-cuisine---quallons-nous-manger-aujourdhui-france-rev-1', 'NDS', 'Lecons de Cuisine - Qu''Allons-Nous Manger Aujourd''hui (France) (Rev 1)', '2008', 'Simulation', 'Namco Bandai', '1', 'Cooking', 'Interactive digital cookbook with voice recognition.', 'Follow step-by-step recipes to cook delicious meals.', 'Updated version of the popular French cookbook.', 'This Revision 1 of Lecons de Cuisine features updated recipe data and refined voice controls. It remains the perfect kitchen companion for French speakers looking to expand their culinary repertoire with easy-to-follow digital instructions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('left-brain-right-brain---use-both-hands-train-both-sides-usa', 'NDS', 'Left Brain, Right Brain - Use Both Hands, Train Both Sides (USA)', '2008', 'Educational', 'Interchannel', '1', 'Brain Training', 'Mini-games designed for simultaneous ambidextrous play.', 'Balance your brain power by using both hands at once.', 'Unique brain training focused on ambidexterity.', 'Left Brain, Right Brain challenges you to use the stylus with your non-dominant hand. By performing tasks that stimulate both hemispheres of the brain, you improve your coordination and mental flexibility in a fun, fast-paced environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('left-brain-right-brain-2-europe-enfrde', 'NDS', 'Left Brain, Right Brain 2 (Europe) (En,Fr,De)', '2009', 'Educational', 'Interchannel', '1', 'Brain Training', 'Enhanced ambidextrous mini-games and logic tests.', 'Improve mental agility through dual-hand coordination.', 'Multi-language sequel to the brain-training hit.', 'Left Brain, Right Brain 2 offers more complex challenges than the original. Developed for the European market, it features new categories of puzzles that force players to switch between logical and creative thinking using both hands on the DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('left-brain-right-brain-2-usa', 'NDS', 'Left Brain, Right Brain 2 (USA)', '2009', 'Educational', 'Interchannel', '1', 'Brain Training', 'Mini-games designed for simultaneous ambidextrous play.', 'Balance your brain power by using both hands at once.', 'North American sequel to the hand-coordination trainer.', 'Left Brain, Right Brain 2 (USA) features a refined set of exercises aimed at "awakening" your brain. With updated graphics and new mini-games, it provides a daily mental workout that focuses on the balance between logical and artistic processing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('left-or-right---ambidextrous-challenge-europe-enfrdeesit', 'NDS', 'Left or Right - Ambidextrous Challenge (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Zushi Games', '1', 'Brain Training', 'Reflex and logic puzzles requiring left and right hand use.', 'Prove your ambidextrous skills by beating high scores.', 'European-exclusive hand-coordination challenge.', 'Left or Right: Ambidextrous Challenge is a collection of games that test your speed and accuracy. By rotating the DS and using both hands, you''ll improve your motor skills while tackling puzzles that require split-second decision-making.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legacy-of-ys---books-i-&-ii-usa', 'NDS', 'Legacy of Ys - Books I & II (USA)', '2005', 'RPG', 'Hudson Soft', '1', 'Action RPG', 'Action RPG with real-time combat and exploration.', 'Uncover the mystery of the ancient kingdom of Ys.', 'Remastered bundle of the first two Ys classics.', 'Legacy of Ys: Books I & II brings the legendary Falcom series to the DS. Featuring 3D graphics, a rearranged soundtrack, and touch-screen combat, this collection is the definitive way to experience the beginning of Adol Christin''s epic journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-kage-2-the-europe-enfrdeesit', 'NDS', 'Legend of Kage 2, The (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Natsume', '1', 'Action', 'Side-scrolling ninja action with fast-paced combat.', 'Rescue Princess Yuki from the forces of evil.', 'Modern sequel to the classic arcade ninja game.', 'The Legend of Kage 2 features two playable characters with distinct fighting styles. Use ninja magic, wall-climbing, and rapid sword strikes across beautiful hand-drawn stages to defeat massive bosses in this European action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-kage-2-the-usa-enfrdeesit', 'NDS', 'Legend of Kage 2, The (USA) (En,Fr,De,Es,It)', '2008', 'Action', 'Natsume', '1', 'Action', 'Side-scrolling ninja action with fast-paced combat.', 'Rescue Princess Yuki from the forces of evil.', 'High-octane ninja combat for North American players.', 'This USA version of The Legend of Kage 2 delivers intense retro-style action. Master the art of the katana and shuriken as you battle through 12 stages filled with supernatural enemies, all rendered in a striking dual-screen presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-kay-europe-enfrdeesit', 'NDS', 'Legend of Kay (Europe) (En,Fr,De,Es,It)', '2005', 'Action / Adventure', 'Neon Studios', '1', 'Action Adventure', '3D action-adventure platformer with martial arts.', 'Save the island from the invading Gorilla and Rat armies.', 'A colorful cat-themed martial arts adventure.', 'Legend of Kay on NDS follows the journey of a young cat warrior. Explore diverse environments, solve puzzles, and engage in "combo-heavy" martial arts combat to protect your village from a tyrannical emperor in this multi-language European port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-kay-usa-enfres', 'NDS', 'Legend of Kay (USA) (En,Fr,Es)', '2005', 'Action / Adventure', 'Neon Studios', '1', 'Action Adventure', '3D action-adventure platformer with martial arts.', 'Save the island from the invading Gorilla and Rat armies.', 'North American release of the feline action-adventure.', 'Play as Kay, a brave cat mastering the Way of the Sword. This US release features platforming, puzzle-solving, and a deep combat system that allows you to swap between different weapons as you fight to liberate your world from animal invaders.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-spyro-the---a-new-beginning-europe-enfrdeesitnl', 'NDS', 'Legend of Spyro, The - A New Beginning (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Action / Adventure', 'Krome Studios', '1', 'Action Adventure', '2D side-scrolling action with breath-based attacks.', 'Discover Spyro''s true power and stop Cynder.', 'The start of the epic Legend of Spyro trilogy.', 'A New Beginning reboots the Spyro franchise with a focus on combat. Use the touch screen to unleash elemental breaths like fire, ice, and electricity to defeat the Dark Master''s minions in this European multi-language action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-spyro-the---a-new-beginning-usa', 'NDS', 'Legend of Spyro, The - A New Beginning (USA)', '2006', 'Action / Adventure', 'Krome Studios', '1', 'Action Adventure', '2D side-scrolling action with breath-based attacks.', 'Discover Spyro''s true power and stop Cynder.', 'North American debut of the rebooted Spyro saga.', 'The Legend of Spyro: A New Beginning brings a darker, more cinematic feel to the series. Combat hordes of enemies and upgrade your elemental powers as you follow the purple dragon''s destiny in this high-energy handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-spyro-the---dawn-of-the-dragon-europe-enfrdeesitnl', 'NDS', 'Legend of Spyro, The - Dawn of the Dragon (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Action / Adventure', 'Krome Studios', '1', 'Action Adventure', '3D action platformer with co-op flying mechanics.', 'Defeat the Dark Master Malefor and save the world.', 'The climactic final chapter of the Spyro trilogy.', 'Dawn of the Dragon introduces flight-at-will and a unique partnership between Spyro and Cynder. This European release allows you to swap between the two dragons, using their combined elemental powers to solve puzzles and defeat massive bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-spyro-the---dawn-of-the-dragon-usa-enfrdeesitnl', 'NDS', 'Legend of Spyro, The - Dawn of the Dragon (USA) (En,Fr,De,Es,It,Nl)', '2008', 'Action / Adventure', 'Krome Studios', '1', 'Action Adventure', '3D action platformer with co-op flying mechanics.', 'Defeat the Dark Master Malefor and save the world.', 'The epic conclusion for the US Spyro audience.', 'In Dawn of the Dragon (USA), players experience the ultimate battle for the Dragon World. Featuring upgraded elemental abilities and a focus on epic scale, this title concludes Spyro''s origins story with a satisfying blend of flight and combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-spyro-the---the-eternal-night-europe-enfrdeesitnl', 'NDS', 'Legend of Spyro, The - The Eternal Night (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Action / Adventure', 'Krome Studios', '1', 'Action Adventure', '2D action platformer with "Dragon Time" mechanics.', 'Stop the Ape King from resurrecting the Dark Master.', 'The challenging second entry in the Spyro trilogy.', 'The Eternal Night features the "Dragon Time" ability, allowing Spyro to slow down time to solve puzzles and defeat fast enemies. This European version offers a difficult, combat-heavy experience with massive boss fights and elemental upgrades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-spyro-the---the-eternal-night-usa', 'NDS', 'Legend of Spyro, The - The Eternal Night (USA)', '2007', 'Action / Adventure', 'Krome Studios', '1', 'Action Adventure', '2D action platformer with "Dragon Time" mechanics.', 'Stop the Ape King from resurrecting the Dark Master.', 'North American release of Spyro''s second adventure.', 'Follow Spyro as he journeys to the Well of Souls in The Eternal Night. Master new elemental breaths and use your time-manipulation powers to navigate dangerous platforms and defeat the forces of darkness in this intense handheld action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-the-guardians---the-owls-of-gahoole-europe-enfrdeesitnl', 'NDS', 'Legend of the Guardians - The Owls of Ga''Hoole (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Action / Adventure', 'Krome Studios', '1', 'Action Adventure', 'Aerial combat and flight simulation with touch-screen maneuvers.', 'Join the Guardians and defeat the Pure Ones to save the owl kingdom.', 'Epic avian combat adventure based on the film.', 'Take to the skies in Legend of the Guardians: The Owls of Ga''Hoole. Master the art of aerial combat, customize your owl warrior, and engage in high-speed dogfights across the European territories in this stunning cinematic adaptation for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-the-guardians---the-owls-of-gahoole-usa-enfrespt', 'NDS', 'Legend of the Guardians - The Owls of Ga''Hoole (USA) (En,Fr,Es,Pt)', '2010', 'Action / Adventure', 'Krome Studios', '1', 'Action Adventure', 'Aerial combat and flight simulation with touch-screen maneuvers.', 'Join the Guardians and defeat the Pure Ones to save the owl kingdom.', 'North American release of the owl-themed flight action game.', 'Fly and fight as a Guardian in this US version of the hit movie game. Use unique talons and armor, navigate treacherous weather, and participate in large-scale aerial battles to protect the Great Tree of Ga''Hoole from the evil Pure Ones.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legendary-starfy-the-usa', 'NDS', 'Legendary Starfy, The (USA)', '2009', 'Platformer', 'Nintendo', '1', 'Platformer', 'Side-scrolling platformer with swimming and spin-attack mechanics.', 'Help Starfy return to Pufftop while assisting a mysterious amnesiac.', 'The legendary Japanese platforming icon''s Western debut.', 'The Legendary Starfy brings high-speed platforming and aquatic exploration to the NDS. Help the Prince of Pufftop solve puzzles, defeat quirky bosses, and collect hidden treasures in this charming, colorful adventure perfect for fans of Kirby and Mario.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-batman---the-videogame-europe-enfrdeesitda', 'NDS', 'LEGO Batman - The Videogame (Europe) (En,Fr,De,Es,It,Da)', '2008', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with character-swapping and building mechanics.', 'Clean up Gotham City by defeating the Joker and other villains.', 'Classic LEGO action featuring the Dark Knight.', 'LEGO Batman: The Videogame lets you play as Batman and Robin to stop Gotham''s most notorious criminals. Utilize specialized suits, build complex gadgets, and explore iconic locations in this European multi-language release full of humor and brick-building fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-batman---the-videogame-japan', 'NDS', 'LEGO Batman - The Videogame (Japan)', '2008', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with character-swapping and building mechanics.', 'Clean up Gotham City by defeating the Joker and other villains.', 'Japanese localized edition of the LEGO Batman hit.', 'Experience the brick-built adventures of Batman in Japan. This version retains the classic gameplay of swapping between heroes and villains, solving environmental puzzles, and collecting studs across the dark but humorous streets of LEGO Gotham.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-batman---the-videogame-usa-enfres', 'NDS', 'LEGO Batman - The Videogame (USA) (En,Fr,Es)', '2008', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with character-swapping and building mechanics.', 'Clean up Gotham City by defeating the Joker and other villains.', 'The North American debut of the LEGO Batman series.', 'Fight crime in Gotham with a LEGO twist. Control a massive roster of DC characters, drive iconic vehicles like the Batmobile, and use the unique abilities of different suits to uncover secrets in this highly replayable action-adventure for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-batman-2---dc-super-heroes-europe-ende', 'NDS', 'LEGO Batman 2 - DC Super Heroes (Europe) (En,De)', '2012', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Isometric action-adventure with collectible heroes and villains.', 'Stop Lex Luthor and the Joker from destroying Gotham City.', 'Team up with the Justice League in LEGO form.', 'LEGO Batman 2: DC Super Heroes expands the roster to include Superman, Wonder Woman, and more. Use the DS touch screen to trigger super-powers and navigate the streets of Gotham to stop the ultimate villainous alliance in this European edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-batman-2---dc-super-heroes-europe-enfrdeesitnlda', 'NDS', 'LEGO Batman 2 - DC Super Heroes (Europe) (En,Fr,De,Es,It,Nl,Da)', '2012', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Isometric action-adventure with collectible heroes and villains.', 'Stop Lex Luthor and the Joker from destroying Gotham City.', 'Multi-language European version of the DC sequel.', 'Join the Justice League in LEGO Batman 2. This version offers a huge variety of playable characters and special abilities. Solve puzzles and engage in combat as you work to save Gotham from the combined might of Lex Luthor and the Joker.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-batman-2---dc-super-heroes-europe-enfr', 'NDS', 'LEGO Batman 2 - DC Super Heroes (Europe) (En,Fr)', '2012', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Isometric action-adventure with collectible heroes and villains.', 'Stop Lex Luthor and the Joker from destroying Gotham City.', 'French/English regional release of the DC Super Heroes game.', 'Play as the world''s finest heroes in LEGO Batman 2. This specific release focuses on the English and French markets, delivering the same high-quality brick-building action, character unlocks, and tactical combat the series is known for.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-batman-2---dc-super-heroes-usa-enfrespt', 'NDS', 'LEGO Batman 2 - DC Super Heroes (USA) (En,Fr,Es,Pt)', '2012', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Isometric action-adventure with collectible heroes and villains.', 'Stop Lex Luthor and the Joker from destroying Gotham City.', 'North American release featuring the Justice League.', 'The Caped Crusader returns in LEGO Batman 2: DC Super Heroes (USA). Fly, blast, and build your way through levels as you unlock iconic DC heroes. Perfect for fans looking for a portable superhero experience with deep replayability.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-battles---ninjago-usa-enfres', 'NDS', 'LEGO Battles - Ninjago (USA) (En,Fr,Es)', '2011', 'Strategy', 'Hellbent Games', '4', 'Strategy', 'Real-time strategy and tower defense with Ninjago characters.', 'Defeat the skeleton army and master the art of Spinjitzu.', 'Tactical LEGO strategy based on the Ninjago series.', 'LEGO Battles: Ninjago brings a strategic twist to the NDS. Build bases, train your ninja warriors, and deploy tactical maneuvers to win battles against the underworld forces in this action-packed strategy title for North American players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-battles-europe-enfrdeesitda', 'NDS', 'LEGO Battles (Europe) (En,Fr,De,Es,It,Da)', '2009', 'Strategy', 'Hellbent Games', '4', 'Strategy', 'Real-time strategy with base building and unit management.', 'Conquer enemy territories using LEGO themed armies.', 'Cross-over strategy game featuring classic LEGO themes.', 'LEGO Battles combines Pirates, Castle, and Space themes into one RTS experience. Manage resources, build your army, and engage in tactical warfare across various maps in this European multi-language strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-battles-usa-enfres', 'NDS', 'LEGO Battles (USA) (En,Fr,Es)', '2009', 'Strategy', 'Hellbent Games', '4', 'Strategy', 'Real-time strategy with base building and unit management.', 'Conquer enemy territories using LEGO themed armies.', 'The US release of the multi-theme LEGO strategy game.', 'Command diverse LEGO units in LEGO Battles (USA). Whether you prefer Ninjas, Astronauts, or Knights, this game offers deep strategy gameplay with three distinct campaigns and wireless multiplayer support for tactical duels on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-harry-potter---years-1-4-europe-enfrdeesitda', 'NDS', 'LEGO Harry Potter - Years 1-4 (Europe) (En,Fr,De,Es,It,Da)', '2010', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Adventure and puzzle-solving based on the first four books.', 'Attend Hogwarts, learn spells, and defeat Voldemort''s forces.', 'Magical brick-building fun from years 1 to 4.', 'LEGO Harry Potter: Years 1-4 brings the Wizarding World to life. Explore Diagon Alley and the Forbidden Forest, master spells like Wingardium Leviosa, and solve environmental puzzles in this European multi-language magical adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-harry-potter---years-1-4-usa-enfres', 'NDS', 'LEGO Harry Potter - Years 1-4 (USA) (En,Fr,Es)', '2010', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Adventure and puzzle-solving based on the first four books.', 'Attend Hogwarts, learn spells, and defeat Voldemort''s forces.', 'North American release of Harry''s early years.', 'Experience the magic of Harry Potter''s first four years at Hogwarts in LEGO form. Brew potions, fly on broomsticks, and unlock over 100 characters in this charming and humorous adaptation of the beloved film series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-harry-potter---years-5-7-europe-enfrdeesitnlda', 'NDS', 'LEGO Harry Potter - Years 5-7 (Europe) (En,Fr,De,Es,It,Nl,Da)', '2011', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure and spell-casting based on the final books.', 'Prepare for the ultimate showdown with Lord Voldemort.', 'The epic conclusion to the LEGO Harry Potter saga.', 'LEGO Harry Potter: Years 5-7 covers the final chapters of the story. Learn advanced magic, participate in duels, and explore new locations like Godric''s Hollow in this European version designed for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-harry-potter---years-5-7-usa-enfres', 'NDS', 'LEGO Harry Potter - Years 5-7 (USA) (En,Fr,Es)', '2011', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure and spell-casting based on the final books.', 'Prepare for the ultimate showdown with Lord Voldemort.', 'US release of the final Harry Potter adventure.', 'The battle for Hogwarts reaches its peak in LEGO Harry Potter: Years 5-7. Use the DS stylus to cast powerful spells and navigate the dark path toward the final confrontation with the Dark Lord in this keyword-rich LEGO adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-indiana-jones---the-original-adventures-europe-enfrdeesitda', 'NDS', 'LEGO Indiana Jones - The Original Adventures (Europe) (En,Fr,De,Es,It,Da)', '2008', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with puzzle-solving and whip-swinging.', 'Relive the adventures of the first three Indiana Jones films.', 'Classic Indy moments recreated with LEGO bricks.', 'LEGO Indiana Jones: The Original Adventures follows Indy from the jungles of South America to the deserts of Egypt. Use Indy''s whip to swing across pits and manipulate objects in this European multi-language puzzle-action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-indiana-jones---the-original-adventures-usa-enfrdeesitda', 'NDS', 'LEGO Indiana Jones - The Original Adventures (USA) (En,Fr,De,Es,It,Da)', '2008', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with puzzle-solving and whip-swinging.', 'Relive the adventures of the first three Indiana Jones films.', 'The US release of Indy''s original brick adventures.', 'Grab your fedora and whip in LEGO Indiana Jones (USA). This title features the humor and charm of the LEGO series while letting players play through the most iconic scenes of the original trilogy with a massive cast of unlockable characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-indiana-jones-2---the-adventure-continues-europe-enfrdeesitda', 'NDS', 'LEGO Indiana Jones 2 - The Adventure Continues (Europe) (En,Fr,De,Es,It,Da)', '2009', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure including Kingdom of the Crystal Skull content.', 'Explore new levels and create your own adventures.', 'Expanded Indiana Jones sequel with more levels.', 'LEGO Indiana Jones 2: The Adventure Continues brings new mechanics and stories to the NDS. This European version includes the Crystal Skull storyline and a refined level-building focus for endless creative play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-indiana-jones-2---the-adventure-continues-usa-enfres', 'NDS', 'LEGO Indiana Jones 2 - The Adventure Continues (USA) (En,Fr,Es)', '2009', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure including Kingdom of the Crystal Skull content.', 'Explore new levels and create your own adventures.', 'The North American sequel to LEGO Indy.', 'Relive all four movies in LEGO Indiana Jones 2 (USA). With new puzzles, updated vehicle sections, and humorous takes on the Kingdom of the Crystal Skull, this game offers the ultimate portable Indy experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-legends-of-chima---lavals-journey-europe-enfrdeesitnlda', 'NDS', 'LEGO Legends of Chima - Laval''s Journey (Europe) (En,Fr,De,Es,It,Nl,Da)', '2013', 'Action / Adventure', 'Traveller’s Tales', '1', 'Action Adventure', 'Action-adventure with animal-themed powers and exploration.', 'Find the legendary Chi and save the world of Chima.', 'Explore the world of Chima in this LEGO epic.', 'LEGO Legends of Chima: Laval''s Journey takes you to a land of warring animal tribes. Play as Laval the lion and unlock the powers of other animals to solve puzzles and restore balance to the Chi in this European multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-legends-of-chima---lavals-journey-germany-enfrdeesitnlda', 'NDS', 'LEGO Legends of Chima - Laval''s Journey (Germany) (En,Fr,De,Es,It,Nl,Da)', '2013', 'Action / Adventure', 'Traveller’s Tales', '1', 'Action Adventure', 'Action-adventure with animal-themed powers and exploration.', 'Find the legendary Chi and save the world of Chima.', 'German regional edition of the Chima adventure.', 'Join Laval on a quest through the kingdom of Chima. This German release features the same deep exploration and combat mechanics, allowing players to utilize different animal abilities to uncover secrets and defeat the crocodile tribe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-legends-of-chima---lavals-journey-usa-enfrespt', 'NDS', 'LEGO Legends of Chima - Laval''s Journey (USA) (En,Fr,Es,Pt)', '2013', 'Action / Adventure', 'Traveller’s Tales', '1', 'Action Adventure', 'Action-adventure with animal-themed powers and exploration.', 'Find the legendary Chi and save the world of Chima.', 'North American release of Laval''s Journey.', 'Embark on an epic quest in LEGO Legends of Chima: Laval''s Journey. Use the power of Chi to enhance your combat skills and explore the vast lands of Chima in this action-packed title for the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-marvel-super-heroes---universe-in-peril-europe-enfrdeesitnlda', 'NDS', 'LEGO Marvel Super Heroes - Universe in Peril (Europe) (En,Fr,De,Es,It,Nl,Da)', '2013', 'Action / Adventure', 'Traveller’s Tales', '1', 'Action Adventure', 'Isometric action-adventure with a massive superhero roster.', 'Stop Doctor Doom and Loki from creating a world-ending weapon.', 'Marvel''s greatest heroes unite in LEGO form.', 'LEGO Marvel Super Heroes: Universe in Peril features fast-paced action and character-based puzzles. Play as Spider-Man, Iron Man, and Thor to thwart a cosmic threat in this European multi-language Marvel adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-marvel-super-heroes---universe-in-peril-usa-enfrespt', 'NDS', 'LEGO Marvel Super Heroes - Universe in Peril (USA) (En,Fr,Es,Pt)', '2013', 'Action / Adventure', 'Traveller’s Tales', '1', 'Action Adventure', 'Isometric action-adventure with a massive superhero roster.', 'Stop Doctor Doom and Loki from creating a world-ending weapon.', 'The US release of the Marvel Universe in Peril.', 'Unleash your inner hero in LEGO Marvel Super Heroes for NDS. With over 90 playable characters and a story that spans the Marvel Universe, this game offers intense combat and clever puzzles for fans of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-ninjago---the-videogame-europe-enfrdeesitnlda', 'NDS', 'LEGO Ninjago - The Videogame (Europe) (En,Fr,De,Es,It,Nl,Da)', '2011', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-strategy with Spinjitzu combat and building.', 'Defeat the evil Lord Garmadon and his skeleton army.', 'The definitive Ninjago action game for NDS.', 'LEGO Ninjago: The Videogame allows players to master the four elements. Build your ninja fortress, train your skills, and engage in epic Spinjitzu battles to protect the golden weapons in this European multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-pirates-of-the-caribbean---the-video-game-europe-enfrdeesitnlsvnoda', 'NDS', 'LEGO Pirates of the Caribbean - The Video Game (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2011', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with swashbuckling combat and puzzle-solving.', 'Play through the events of all four Pirates movies.', 'LEGO humor meets the Caribbean high seas.', 'LEGO Pirates of the Caribbean brings Jack Sparrow to the NDS. Explore Tortuga, find hidden treasures, and use unique character abilities like Jack''s compass to navigate this European multi-language pirate adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-pirates-of-the-caribbean---the-video-game-usa-enfres', 'NDS', 'LEGO Pirates of the Caribbean - The Video Game (USA) (En,Fr,Es)', '2011', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with swashbuckling combat and puzzle-solving.', 'Play through the events of all four Pirates movies.', 'The US release of the LEGO Pirates saga.', 'Set sail for adventure in LEGO Pirates of the Caribbean (USA). Relive the story of the films with LEGO''s signature wit, engaging combat, and hundreds of secrets to discover across the mysterious Caribbean waters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-rock-band-europe-enfrdeesitda', 'NDS', 'LEGO Rock Band (Europe) (En,Fr,De,Es,It,Da)', '2009', 'Music', 'Harmonix', '4', 'Rhythm', 'Rhythm-action music game with LEGO-style customization.', 'Build a rock band and become a global superstar.', 'Music and rhythm gameplay with a LEGO twist.', 'LEGO Rock Band brings the rhythm genre to NDS. Tap along to hit songs, customize your band members, and perform in wild venues to win over the fans in this European multi-language musical experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-rock-band-usa-enfrdeesitda', 'NDS', 'LEGO Rock Band (USA) (En,Fr,De,Es,It,Da)', '2009', 'Music', 'Harmonix', '4', 'Rhythm', 'Rhythm-action music game with LEGO-style customization.', 'Build a rock band and become a global superstar.', 'North American release of the LEGO rhythm game.', 'Rock out with LEGO Rock Band (USA). Featuring a family-friendly soundtrack and the ability to customize your instruments and stage, this game offers a portable way to master the beat and become a legend of rock.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-star-wars---the-complete-saga-europe-enfrdeesitda', 'NDS', 'LEGO Star Wars - The Complete Saga (Europe) (En,Fr,De,Es,It,Da)', '2007', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure spanning the first six Star Wars films.', 'Defeat the Empire and the Sith to bring balance to the Force.', 'The definitive LEGO Star Wars experience on NDS.', 'LEGO Star Wars: The Complete Saga combines the original trilogy and the prequels. Use the Force, engage in lightsaber duels, and play through over 30 levels in this European multi-language sci-fi classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-star-wars---the-complete-saga-usa', 'NDS', 'LEGO Star Wars - The Complete Saga (USA)', '2007', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure spanning the first six Star Wars films.', 'Defeat the Empire and the Sith to bring balance to the Force.', 'The North American release of the Star Wars saga.', 'Relive the entire Skywalker saga in LEGO Star Wars: The Complete Saga (USA). Unlock over 160 characters, participate in epic space battles, and use the DS touch screen to solve puzzles in the galaxy far, far away.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-star-wars-ii---the-original-trilogy-europe-enfrdeesitda', 'NDS', 'LEGO Star Wars II - The Original Trilogy (Europe) (En,Fr,De,Es,It,Da)', '2006', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with character swapping and vehicle segments.', 'Defeat the Galactic Empire and relive the original movie trilogy.', 'LEGO humor meets the classic Star Wars trilogy.', 'LEGO Star Wars II: The Original Trilogy on NDS brings the classic films to life. Play through A New Hope, The Empire Strikes Back, and Return of the Jedi with a LEGO twist, featuring character customization and iconic space battles in this European multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-star-wars-ii---the-original-trilogy-japan', 'NDS', 'LEGO Star Wars II - The Original Trilogy (Japan)', '2006', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with character swapping and vehicle segments.', 'Defeat the Galactic Empire and relive the original movie trilogy.', 'The Japanese edition of the classic LEGO Star Wars sequel.', 'Relive the epic battle between the Rebels and the Empire in LEGO form. This Japanese version allows players to build and battle through iconic Star Wars scenes, unlocking hundreds of characters and utilizing the DS touch screen for unique interactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-star-wars-ii---the-original-trilogy-usa', 'NDS', 'LEGO Star Wars II - The Original Trilogy (USA)', '2006', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with character swapping and vehicle segments.', 'Defeat the Galactic Empire and relive the original movie trilogy.', 'The North American release of the Original Trilogy.', 'Experience the definitive LEGO Star Wars adventure in the USA version of the game. Build your own custom characters, pilot the Millennium Falcon, and use the Force to solve environmental puzzles across the most famous locations in the galaxy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-star-wars-iii---the-clone-wars-europe-enfrdeesitda', 'NDS', 'LEGO Star Wars III - The Clone Wars (Europe) (En,Fr,De,Es,It,Da)', '2011', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with real-time strategy elements and combat.', 'Fight through the Clone Wars and stop the Separatist threat.', 'Epic Star Wars action based on the hit animated series.', 'LEGO Star Wars III: The Clone Wars features a massive scale of combat. Take command of clone armies, swap between Jedi and Clones, and explore the galaxy during the height of the war in this European version featuring various language options.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-star-wars-iii---the-clone-wars-usa-enfres', 'NDS', 'LEGO Star Wars III - The Clone Wars (USA) (En,Fr,Es)', '2011', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Action-adventure with real-time strategy elements and combat.', 'Fight through the Clone Wars and stop the Separatist threat.', 'The North American release of the Clone Wars saga.', 'Join Anakin and Obi-Wan in LEGO Star Wars III (USA). Experience new combat mechanics, control multiple characters simultaneously to solve complex puzzles, and master new Force abilities in this action-packed handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-the-lord-of-the-rings-europe-enfrdeesitnlda', 'NDS', 'LEGO The Lord of the Rings (Europe) (En,Fr,De,Es,It,Nl,Da)', '2012', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Isometric action-adventure with item-based puzzle solving.', 'Journey to Mount Doom and destroy the One Ring.', 'Tolkien''s epic trilogy reimagined with LEGO bricks.', 'LEGO The Lord of the Rings follows the journey of Frodo and the Fellowship. Use the DS stylus to manage your inventory, use unique character items like the Mithril shirt, and battle orcs across Middle-earth in this European multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-the-lord-of-the-rings-france-enfrdeesitnlda', 'NDS', 'LEGO The Lord of the Rings (France) (En,Fr,De,Es,It,Nl,Da)', '2012', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Isometric action-adventure with item-based puzzle solving.', 'Journey to Mount Doom and destroy the One Ring.', 'French regional release of the Lord of the Rings quest.', 'Relive the cinematic masterpiece in LEGO form. This version, tailored for the French market, features the full quest through Middle-earth, allowing players to unlock legendary heroes and solve puzzles inspired by the epic film trilogy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-the-lord-of-the-rings-germany-enfrdeesitnlda', 'NDS', 'LEGO The Lord of the Rings (Germany) (En,Fr,De,Es,It,Nl,Da)', '2012', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Isometric action-adventure with item-based puzzle solving.', 'Journey to Mount Doom and destroy the One Ring.', 'German regional edition of the epic LEGO adventure.', 'Experience the magic of Middle-earth in LEGO The Lord of the Rings. This German release provides deep exploration, tactical combat against Nazgûl, and a charming brick-built take on the legendary story of the Fellowship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-the-lord-of-the-rings-usa-enfrespt', 'NDS', 'LEGO The Lord of the Rings (USA) (En,Fr,Es,Pt)', '2012', 'Action / Adventure', 'Traveller’s Tales', '2', 'Action Adventure', 'Isometric action-adventure with item-based puzzle solving.', 'Journey to Mount Doom and destroy the One Ring.', 'The North American release of the LEGO Middle-earth saga.', 'Explore the Shire, Rivendell, and Mordor in LEGO The Lord of the Rings (USA). With a focus on cooperative-style puzzles and character abilities, this handheld version offers a rich and humorous adaptation of the beloved fantasy world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemyuoul-no-renkinjutsushi-japan', 'NDS', 'Lemyuoul no Renkinjutsushi (Japan)', '2009', 'RPG', 'Gust', '1', 'Alchemy RPG', 'Alchemy simulation with shop management and crafting.', 'Run a successful alchemy shop and pay off your debts.', 'Charming Japanese alchemy and management sim.', 'Lemyuoul no Renkinjutsushi (The Alchemist of Lemyuoul) is a deep management game. Gather ingredients, craft magical items, and set prices in your shop to build a thriving business in this colorful and engaging Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lernerfolg-grundschule---deutsch---der-rechtschreibtrainer-europe-detr', 'NDS', 'Lernerfolg Grundschule - Deutsch - Der Rechtschreibtrainer (Europe) (De,Tr)', '2008', 'Educational', 'Tivola', '1', 'Education', 'Educational spelling drills and writing exercises.', 'Improve German spelling and grammar through mini-games.', 'German language spelling trainer for primary school.', 'Lernerfolg Grundschule: Deutsch - Der Rechtschreibtrainer is an essential educational tool. Designed for German-speaking students, it offers interactive lessons that make learning correct spelling and grammar fun and rewarding on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lernerfolg-grundschule---deutsch---klasse-1-4-europe-detr', 'NDS', 'Lernerfolg Grundschule - Deutsch - Klasse 1-4 (Europe) (De,Tr)', '2007', 'Educational', 'Tivola', '1', 'Education', 'Comprehensive educational curriculum for German and Turkish.', 'Master reading, writing, and language basics for grades 1-4.', 'Multi-level German primary school educational suite.', 'This comprehensive German language trainer covers four years of primary education. With a variety of interactive tasks and progress tracking, it helps students master their native language through the engaging interface of the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lernerfolg-grundschule---englisch---der-vokabeltrainer-europe-frdeesittr', 'NDS', 'Lernerfolg Grundschule - Englisch - Der Vokabeltrainer (Europe) (Fr,De,Es,It,Tr)', '2008', 'Educational', 'Tivola', '1', 'Language Learning', 'Vocabulary training with interactive quizzes and audio.', 'Learn essential English words through repetition and games.', 'Multi-language English vocabulary trainer for kids.', 'Lernerfolg Grundschule: Englisch helps students build a strong English foundation. Using the Vokabeltrainer system, kids can learn and test themselves on hundreds of words, featuring localized support for French, German, Spanish, and Italian.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lernerfolg-grundschule---englisch-germany-frde', 'NDS', 'Lernerfolg Grundschule - Englisch (Germany) (Fr,De)', '2007', 'Educational', 'Tivola', '1', 'Language Learning', 'Introductory English language lessons for primary students.', 'Learn basic English phrases and school-level vocabulary.', 'Beginner English learning tool for German students.', 'Designed specifically for the German market, this title introduces young learners to the English language. Through simple games and clear audio, students can practice their pronunciation and vocabulary in a stress-free environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lernerfolg-grundschule---konzentration---der-aufmerksamkeitstrainer-europe-endetr', 'NDS', 'Lernerfolg Grundschule - Konzentration - Der Aufmerksamkeitstrainer (Europe) (En,De,Tr)', '2008', 'Educational', 'Tivola', '1', 'Brain Training', 'Concentration and memory exercises with a vampire theme.', 'Improve focus and attention span through specialized tasks.', 'Fun attention and concentration training for kids.', 'Lernerfolg Grundschule: Konzentration uses a "vampire school" theme to keep kids engaged. The exercises are scientifically designed to improve focus, memory, and spatial reasoning, providing a valuable mental workout for primary school children.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lernerfolg-grundschule---mathematik-germany', 'NDS', 'Lernerfolg Grundschule - Mathematik (Germany)', '2007', 'Educational', 'Tivola', '1', 'Mathematics', 'Mathematical drills and arithmetic puzzles for students.', 'Master addition, subtraction, and multiplication skills.', 'German primary school mathematics training software.', 'This German-exclusive math trainer offers a structured way to practice arithmetic. With a reward system and clear explanations, it helps students gain confidence in their math abilities through portable, daily practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lernerfolg-grundschule---mathematik-intensiv---klasse-1-4-europe-enfrdeesittr', 'NDS', 'Lernerfolg Grundschule - Mathematik Intensiv - Klasse 1-4 (Europe) (En,Fr,De,Es,It,Tr)', '2008', 'Educational', 'Tivola', '1', 'Mathematics', 'Intensive mathematics curriculum for grades 1-4.', 'Solve complex math problems across multiple school levels.', 'Multi-language intensive primary math trainer.', 'Lernerfolg Grundschule: Mathematik Intensiv provides a deep dive into the math curriculum. Supporting multiple European languages, it allows students to practice everything from basic counting to complex long division in an interactive digital format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lernerfolg-vorschule---captn-sharky-europe-detr', 'NDS', 'Lernerfolg Vorschule - Capt''n Sharky (Europe) (De,Tr)', '2008', 'Educational', 'Tivola', '1', 'Education', 'Preschool preparatory games with a pirate theme.', 'Learn basic logic, shapes, and numbers with Capt''n Sharky.', 'Pirate-themed educational games for preschoolers.', 'Lernerfolg Vorschule: Capt''n Sharky is designed for children getting ready for school. With the help of the popular pirate character, kids develop foundational skills in a playful, German-language environment tailored for the DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lernerfolg-vorschule---prinzessin-lillifee-europe-detr', 'NDS', 'Lernerfolg Vorschule - Prinzessin Lillifee (Europe) (De,Tr)', '2008', 'Educational', 'Tivola', '1', 'Education', 'Preschool preparatory games with a fairy theme.', 'Learn foundational skills through creative fairy-themed play.', 'Fairy-themed educational games for young girls.', 'Join Prinzessin Lillifee in this charming preschool trainer. Designed for the European market, it offers gentle puzzles and educational activities that help young children prepare for school while exploring a magical, colorful world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-draw!-europe-enesit', 'NDS', 'Let''s Draw! (Europe) (En,Es,It)', '2009', 'Creative', 'Majesco', '1', 'Drawing', 'Digital art studio with step-by-step drawing tutorials.', 'Learn to draw characters and objects using the stylus.', 'Creative drawing and art instruction tool for NDS.', 'Let''s Draw! (Europe) turns your DS into a portable canvas. With over 100 things to learn to draw, the game provides easy-to-follow guides and fun mini-games that teach basic art principles and stylus control for aspiring young artists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-draw!-usa-enfres', 'NDS', 'Let''s Draw! (USA) (En,Fr,Es)', '2009', 'Creative', 'Majesco', '1', 'Drawing', 'Digital art studio with step-by-step drawing tutorials.', 'Learn to draw characters and objects using the stylus.', 'North American release of the creative art tutor.', 'Unleash your creativity with Let''s Draw! (USA). The game uses the DS touch screen to provide a comprehensive drawing experience, complete with various brushes, colors, and interactive tutorials that make learning to draw accessible and fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-pilates!-usa-enfrdeesit', 'NDS', 'Let''s Pilates! (USA) (En,Fr,De,Es,It)', '2008', 'Fitness', 'Destineer', '1', 'Exercise', 'Fitness simulation with guided Pilates routines.', 'Complete daily Pilates workouts to stay fit and healthy.', 'Portable Pilates instructor for the Nintendo DS.', 'Let''s Pilates! brings a personal trainer to your handheld. Featuring 3D models and clear instructions, the game guides you through various exercises aimed at improving core strength and flexibility, with difficulty levels for beginners and experts alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-ballerina-usa-enfres', 'NDS', 'Let''s Play Ballerina (USA) (En,Fr,Es)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Career simulation focusing on ballet training and performance.', 'Train as a ballerina and perform on the world stage.', 'Ballet career and performance simulation for girls.', 'Let''s Play Ballerina lets you live the life of a professional dancer. Manage your practice schedule, choose your costumes, and use the stylus to perform graceful moves in a series of rhythmic challenges and competitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-fashion-designer-europe-enfrdeesit', 'NDS', 'Let''s Play Fashion Designer (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Creative fashion design and management simulation.', 'Design clothes and run your own fashion boutique.', 'Fashion design and shop management sim for NDS.', 'Let''s Play Fashion Designer gives you the keys to the runway. Create unique outfits, select fabrics, and manage your store''s inventory. This European release allows you to build a fashion empire through creative design and savvy business.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-firemen-europe-enfrdeesit', 'NDS', 'Let''s Play Firemen (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Career simulation focused on firefighting and rescue.', 'Complete dangerous rescue missions and put out fires.', 'Exciting firefighter career simulation for kids.', 'Step into the boots of a hero in Let''s Play Firemen. This European title features various emergency scenarios where you must drive fire trucks, use hoses to douse flames, and rescue citizens from hazardous situations using touch-screen controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-flight-attendant-europe-enfrdeesit', 'NDS', 'Let''s Play Flight Attendant (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Career simulation focusing on airline service and hospitality.', 'Provide excellent service to passengers on various flights.', 'Unique flight attendant career and service sim.', 'Let''s Play Flight Attendant offers a glimpse into the world of aviation. From serving meals to ensuring passenger safety, you must manage multiple tasks under pressure to earn high ratings and advance your career in this European simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-flight-attendant-usa-enfrdeesit', 'NDS', 'Let''s Play Flight Attendant (USA) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Career simulation focusing on airline service and hospitality.', 'Provide excellent service to passengers on various flights.', 'North American release of the airline service sim.', 'Travel the world as a flight attendant in this US release. Master the art of customer service, handle mid-flight emergencies, and explore different international destinations while managing the needs of your passengers using the DS stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-garden-usa-enfres', 'NDS', 'Let''s Play Garden (USA) (En,Fr,Es)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Gardening simulation with plant care and landscape design.', 'Grow a beautiful garden by planting and tending to flowers.', 'Relaxing gardening and plant care simulation.', 'Let''s Play Garden lets you cultivate your own digital backyard. Learn about different plant species, manage water and sunlight, and decorate your garden with various items in this peaceful and creative title for the North American market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-journalists-europe-enfrdeesit', 'NDS', 'Let''s Play Journalists (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Career simulation focusing on news reporting and media.', 'Investigate stories, conduct interviews, and write reports.', 'Journalism and investigative career simulation.', 'Become a star reporter in Let''s Play Journalists. Explore the city for scoops, take photos, and piece together the news in this unique European career sim that tests your investigative skills and ability to meet deadlines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-mums-europe-enfrdeesit', 'NDS', 'Let''s Play Mums (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Baby care simulation and household management.', 'Look after infants and complete daily parenting tasks.', 'Heartwarming baby care and parenting simulation.', 'Let''s Play Mums (also known as My Little Baby) allows you to experience the joys of parenting. Feed, bathe, and play with your virtual baby, tracking their growth and development through various interactive mini-games in this European title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-pet-hospitals-europe-enfrdeesit', 'NDS', 'Let''s Play Pet Hospitals (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Veterinary simulation with diagnostic and surgical mini-games.', 'Treat sick animals and manage a successful pet clinic.', 'Animal care and veterinary clinic simulation.', 'Let''s Play Pet Hospitals puts you in charge of a busy vet clinic. Use the DS stylus to perform check-ups on cats, dogs, and rabbits. Diagnose illnesses, perform minor surgeries, and ensure every furry patient leaves happy and healthy in this European multi-language simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-schools-europe-enfrdeesit', 'NDS', 'Let''s Play Schools (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'School management and teaching simulation.', 'Manage a classroom and help students succeed in their studies.', 'Fun teacher and classroom management sim.', 'Let''s Play Schools allows you to step into the role of a teacher. Organize your classroom, plan lessons, and grade assignments across various subjects. Balance discipline and fun to become the most respected teacher in this engaging European career simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-play-shops-europe-enfrdeesit', 'NDS', 'Let''s Play Shops (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Destineer', '1', 'Life Simulation', 'Shop management and customer service simulation.', 'Run various retail stores and satisfy customer demands.', 'Retail management and shopkeeper simulation.', 'Let''s Play Shops offers a variety of retail environments to master. From a florist to a grocery store, you must manage inventory, serve customers quickly, and handle transactions using the touch screen to grow your business empire in this European title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-ride---friends-forever-usa', 'NDS', 'Let''s Ride - Friends Forever (USA)', '2008', 'Sports', 'ValuSoft', '1', 'Horse Riding', 'Equestrian simulation with horse care and competition.', 'Raise, train, and compete with your horse to win championships.', 'Horse raising and riding adventure for NDS.', 'Let''s Ride: Friends Forever focuses on the bond between a rider and her horse. Groom your horse, practice jumping and dressage, and explore beautiful trails. Compete in prestigious events to prove you and your horse are the ultimate team in this US release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-yoga!-europe-enfrdeesit', 'NDS', 'Let''s Yoga! (Europe) (En,Fr,De,Es,It)', '2009', 'Fitness', 'Destineer', '1', 'Exercise', 'Fitness simulation with guided yoga poses and breathing.', 'Improve flexibility and mindfulness through daily yoga routines.', 'Portable yoga instructor with 3D models.', 'Let''s Yoga! turns your DS into a personal zen studio. Follow 3D avatars as they demonstrate dozens of poses. With clear instructions and progress tracking, it’s an ideal tool for beginners and enthusiasts to practice yoga and meditation anywhere in Europe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-yoga!-usa-enfrdeesit', 'NDS', 'Let''s Yoga! (USA) (En,Fr,De,Es,It)', '2009', 'Fitness', 'Destineer', '1', 'Exercise', 'Fitness simulation with guided yoga poses and breathing.', 'Improve flexibility and mindfulness through daily yoga routines.', 'The North American release of the yoga trainer.', 'Master the art of yoga with Let''s Yoga! for the USA. Featuring a wide range of routines targeting health, beauty, and relaxation, this title uses the DS screens to provide a comprehensive guide to poses, breathing techniques, and holistic wellness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lettriq---evaluez-votre-qi-lettrique-france', 'NDS', 'Lettriq - Evaluez Votre QI Lettrique (France)', '2007', 'Puzzle', 'Mindscape', '1', 'Brain Training', 'Word-based puzzle and IQ testing game.', 'Solve linguistic challenges to measure your "Literary IQ."', 'French language word puzzle and IQ trainer.', 'Lettriq is a specialized brain trainer for French speakers. It evaluates your vocabulary, spelling, and logic through a series of timed word puzzles. Track your progress and improve your mental sharpness with this sophisticated linguistic challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lewis-to-mirai-dorobou---wilbur-no-kiken-na-jikan-ryokou-japan', 'NDS', 'Lewis to Mirai Dorobou - Wilbur no Kiken na Jikan Ryokou (Japan)', '2007', 'Adventure', '505 Games', '1', 'Adventure', 'Action-adventure platformer based on "Meet the Robinsons."', 'Navigate the future and stop the Bowler Hat Guy.', 'Japanese adaptation of the Disney sci-fi adventure.', 'Lewis to Mirai Dorobou brings the world of Disney''s Meet the Robinsons to life. Use futuristic gadgets, solve environmental puzzles, and travel through time to save the future in this action-packed Japanese release for the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('licca-chan-ds---motto!-onnanoko-lesson---oshare-oshigoto-otetsudai-daisuki!-japan-ndsi-enhanced', 'NDS', 'Licca-chan DS - Motto! Onnanoko Lesson - Oshare, Oshigoto, Otetsudai Daisuki! (Japan) (NDSi Enhanced)', '2010', 'Simulation', 'Namco Bandai', '1', 'Life Simulation', 'Life simulation with fashion, jobs, and home activities.', 'Experience a busy life as the famous Licca-chan doll.', 'Enhanced Licca-chan life sim with DSi features.', 'Licca-chan DS: Motto! Onnanoko Lesson offers an expanded world for the iconic Japanese doll. This NDSi enhanced version includes extra mini-games for fashion design, household chores, and various career paths, all aimed at teaching young players life skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('licca-chan-ds---onnanoko-lesson---oshare-mo-oshigoto-mo-omakase!-japan', 'NDS', 'Licca-chan DS - Onnanoko Lesson - Oshare mo Oshigoto mo Omakase! (Japan)', '2009', 'Simulation', 'Namco Bandai', '1', 'Life Simulation', 'Life simulation with fashion and career mini-games.', 'Practice "girl skills" through fashion and work tasks.', 'The original Licca-chan life simulation for DS.', 'Join Licca-chan in her daily adventures. This Japanese title focuses on "Onnanoko Lesson" (Girl Lessons), where players engage in dress-up, interior design, and professional role-playing mini-games to earn points and unlock new items in Licca''s world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lifesigns---hospital-affairs-europe-enfrdeesit', 'NDS', 'LifeSigns - Hospital Affairs (Europe) (En,Fr,De,Es,It)', '2007', 'Simulation', 'Spike Chunsoft', '1', 'Medical', 'Medical drama adventure with diagnostic and social gameplay.', 'Solve medical mysteries while managing hospital relationships.', 'Emotional medical drama and diagnostic adventure.', 'LifeSigns: Hospital Affairs is a narrative-driven simulation. Play as a young doctor, using the stylus to perform exams and surgeries, while navigating the complex personal lives of the hospital staff in this European-exclusive medical thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lifesigns---surgical-unit-usa', 'NDS', 'LifeSigns - Surgical Unit (USA)', '2005', 'Simulation', 'Spike Chunsoft', '1', 'Medical', 'Medical drama adventure with diagnostic and social gameplay.', 'Solve medical mysteries while managing hospital relationships.', 'North American release of the medical drama sim.', 'Known as LifeSigns: Surgical Unit in the USA, this game blends intense surgical mini-games with a deep, branching visual novel story. Examine patients, find the root cause of their symptoms, and save lives while dealing with high-stakes hospital politics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lilpri-ds---hime-chen!-apple-pink-japan', 'NDS', 'LilPri DS - Hime Chen! Apple Pink (Japan)', '2010', 'Simulation', 'Namco Bandai', '1', 'Life Simulation', 'Rhythmic action and idol management based on the anime.', 'Transform into idols and perform perfect dance routines.', 'Magical girl idol rhythm game for NDS.', 'LilPri DS: Hime Chen! Apple Pink follows the stars of the LilPri anime. Use the touch screen to change outfits and perform rhythmic dance battles. Collect "Happiness Notes" to help the fairy-tale world in this vibrant and musical Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lina-no-atelier---strahl-no-renkinjutsushi-japan', 'NDS', 'Lina no Atelier - Strahl no Renkinjutsushi (Japan)', '2007', 'RPG', 'Gust', '1', 'Alchemy RPG', 'Alchemy RPG with item crafting and exploration.', 'Master the art of alchemy to help the town of Strahl.', 'Classic Atelier-style alchemy and adventure.', 'Lina no Atelier: Strahl no Renkinjutsushi brings the popular alchemy series to the DS. Help Lina gather rare ingredients through exploration and combat, then use a deep crafting system to create powerful items and fulfill town requests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('line-rider---freestyle-europe-enfrdeesit', 'NDS', 'Line Rider - Freestyle (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'InXile Entertainment', '1', 'Physics Puzzle', 'Creative physics puzzle where you draw paths for a sledder.', 'Create elaborate tracks and watch the rider navigate them.', 'Physics-based creative sandbox and puzzle game.', 'Line Rider - Freestyle allows you to unleash your imagination. Use the stylus to draw lines that become ramps and loops for "Bosh" the sledder. This European release features a story mode with specific challenges and a free-play sandbox mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('line-rider-2---unbound-usa', 'NDS', 'Line Rider 2 - Unbound (USA)', '2011', 'Puzzle', 'InXile Entertainment', '1', 'Physics Puzzle', 'Creative physics puzzle where you draw paths for a sledder.', 'Complete track challenges and share your creations.', 'US sequel to the physics drawing phenomenon.', 'Line Rider 2: Unbound expands on the original premise with more tools, new characters, and a comprehensive level editor. Solve complex physics puzzles by drawing the perfect path and share your craziest designs with the community in this USA release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lingo-met-lucille-werner-netherlands', 'NDS', 'Lingo met Lucille Werner (Netherlands)', '2009', 'Puzzle', 'Media Republic', '1', 'Word Puzzle', 'Word puzzle and trivia game based on the TV show.', 'Solve word puzzles and find the "Lingo" to win.', 'Dutch language word game hosted by Lucille Werner.', 'Lingo met Lucille Werner brings the popular Dutch game show to the NDS. Test your vocabulary and logic by guessing 5-letter words within a limited time. It features the likeness and voice of the famous host for an authentic TV experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lionel-trains---on-track-europe-enfrdeesit', 'NDS', 'Lionel Trains - On Track (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Electronic Arts', '1', 'Model Trains', 'Model train simulation and track management.', 'Build and manage your own Lionel train layouts.', 'Detailed model train simulation for enthusiasts.', 'Lionel Trains: On Track offers a portable model railroading experience. Design complex track layouts, manage signals, and drive iconic Lionel locomotives through various environments. This European version is perfect for train fans of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lionel-trains---on-track-usa', 'NDS', 'Lionel Trains - On Track (USA)', '2009', 'Simulation', 'Electronic Arts', '1', 'Model Trains', 'Model train simulation and track management.', 'Build and manage your own Lionel train layouts.', 'The US release of the Lionel train simulator.', 'Celebrate the heritage of Lionel Trains on your DS. Build the ultimate railway, manage cargo and passengers, and unlock classic trains from different eras. Use the touch screen to precisely lay tracks and control your fleet in this detailed simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lise-no-atelier---oldor-no-renkinjutsushi-japan', 'NDS', 'Lise no Atelier - O''ldor no Renkinjutsushi (Japan)', '2007', 'RPG', 'Gust', '1', 'Alchemy RPG', 'Turn-based alchemy RPG with time management.', 'Save your family and kingdom using alchemical skills.', 'Portable Atelier RPG with deep crafting systems.', 'Lise no Atelier: O''ldor no Renkinjutsushi follows Lise on her quest to pay off a massive debt. Engage in turn-based combat, explore the kingdom for ingredients, and master a complex alchemy system in this charming Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lise-no-atelier---oldor-no-renkinjutsushi-japan-rev-1', 'NDS', 'Lise no Atelier - O''ldor no Renkinjutsushi (Japan) (Rev 1)', '2007', 'RPG', 'Gust', '1', 'Alchemy RPG', 'Turn-based alchemy RPG with time management.', 'Save your family and kingdom using alchemical skills.', 'Revised edition of Lise''s alchemy adventure.', 'This Revision 1 of Lise no Atelier includes gameplay balances and bug fixes for the Japanese original. Experience the complete story of Princess Lise as she transforms from a spoiled royal into a master alchemist to save her fallen kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-bears-usa-enfres', 'NDS', 'Little Bears (USA) (En,Fr,Es)', '2008', 'Educational', 'Destineer', '1', 'Education', 'Virtual pet simulation with bear cubs.', 'Care for and play with adorable bear cubs.', 'Heartwarming bear-raising simulation for kids.', 'Little Bears allows players to adopt and raise their very own bear cubs. Feed them, play mini-games to bond, and watch them grow in a safe, virtual environment. This US release is a gentle simulation designed for younger animal lovers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-league-world-series-baseball---double-play-usa', 'NDS', 'Little League World Series Baseball - Double Play (USA)', '2007', 'Sports', 'Now Production', '4', 'Baseball', 'Arcade-style baseball simulation with youth league rules.', 'Lead your team to the Little League World Series title.', 'Double-feature baseball action for North America.', 'Little League World Series Baseball: Double Play offers a fun, accessible take on the sport. Featuring kid-friendly mechanics and power-ups, this title focuses on the excitement of the journey from local fields to the international championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-league-world-series-baseball-2008-usa', 'NDS', 'Little League World Series Baseball 2008 (USA)', '2008', 'Sports', 'Now Production', '4', 'Baseball', 'Arcade-style baseball simulation with motion-controlled hits.', 'Win the regional and world tournaments with your team.', 'The official 2008 Little League baseball game.', 'Experience the thrill of the 2008 season in Little League World Series Baseball. Create your own player, join a team, and use the stylus for precision pitching and batting as you aim for the top of the youth baseball world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-league-world-series-baseball-2009-usa', 'NDS', 'Little League World Series Baseball 2009 (USA)', '2009', 'Sports', 'Now Production', '4', 'Baseball', 'Updated arcade-style baseball with new teams and stadiums.', 'Dominate the 2009 season and win the World Series.', 'The 2009 edition of the Little League baseball series.', 'Little League World Series Baseball 2009 (USA) improves on the original with better graphics and refined controls. Compete in various mini-games and full matches to earn your spot in the championship game at Williamsport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-mermaid---ariel-no-umi-no-takaramono-japan', 'NDS', 'Little Mermaid - Ariel no Umi no Takaramono (Japan)', '2006', 'Action / Adventure', 'Taito', '1', 'Adventure', 'Adventure and rhythm game based on the Disney film.', 'Explore the ocean and collect treasures as Ariel.', 'Japanese version of Ariel''s undersea adventure.', 'Little Mermaid: Ariel no Umi no Takaramono takes players under the sea. Join Ariel and Flounder in a series of mini-games, including singing, dancing, and treasure hunting, all themed around the classic Disney animated movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-mermaid-the---ariels-undersea-adventure-europe-enfrdeesit', 'NDS', 'Little Mermaid, The - Ariel''s Undersea Adventure (Europe) (En,Fr,De,Es,It)', '2006', 'Action / Adventure', 'Taito', '1', 'Adventure', 'Adventure and rhythm game based on the Disney film.', 'Explore the ocean and collect treasures as Ariel.', 'European multi-language Little Mermaid adventure.', 'Experience the magic of Disney''s The Little Mermaid on the NDS. This version features beautiful 2D art, touch-screen puzzles, and musical sequences that allow fans to relive the story of the film while exploring the depths of the ocean.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-mermaid-the---ariels-undersea-adventure-usa-enfrdeesit', 'NDS', 'Little Mermaid, The - Ariel''s Undersea Adventure (USA) (En,Fr,De,Es,It)', '2006', 'Action / Adventure', 'Taito', '1', 'Adventure', 'Adventure and rhythm game based on the Disney film.', 'Explore the ocean and collect treasures as Ariel.', 'The North American release of Ariel''s DS journey.', 'Dive into adventure with The Little Mermaid: Ariel''s Undersea Adventure (USA). Use the stylus to uncover hidden items, interact with beloved characters like Sebastian, and participate in a variety of oceanic challenges designed for young Disney fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-red-riding-hoods-zombie-bbq-usa', 'NDS', 'Little Red Riding Hood''s Zombie BBQ (USA)', '2010', 'Action', 'Zombie Studios', '2', 'Action', 'Rail-shooter action with a horror-comedy theme.', 'Survive the zombie apocalypse as Red Riding Hood.', 'Cult-classic horror-action shooter for NDS.', 'Little Red Riding Hood''s Zombie BBQ is a fast-paced "shoot ''em up." Use the touch screen to aim and fire at waves of grotesque zombies in a dark, twisted fairy-tale world. It''s a high-energy arcade experience with massive boss fights and a unique art style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-wingels-germany', 'NDS', 'Little Wingels (Germany)', '2009', 'Educational', 'Tivola', '1', 'Education', 'Mini-game collection and digital toy based on the Wingels brand.', 'Complete various tasks with the cute Wingel characters.', 'German-exclusive collection of kid-friendly mini-games.', 'Little Wingels brings the popular German characters to the DS. Featuring a variety of simple, engaging mini-games focused on creativity and logic, it provides a safe and entertaining experience for young children in a colorful, celestial setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---beach-friends-europe-enfrdeesnlptsvnodafi', 'NDS', 'Littlest Pet Shop - Beach Friends (Europe) (En,Fr,De,Es,Nl,Pt,Sv,No,Da,Fi)', '2008', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with mini-games and customization.', 'Collect and care for pets while exploring a beach environment.', 'Beach-themed pet care and collection game.', 'Littlest Pet Shop: Beach Friends (Europe) brings the popular toy line to the NDS. Explore sunny shorelines, participate in beach-themed mini-games, and collect a variety of adorable pets while unlocking new accessories and playsets in this multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---beach-friends-usa-enfres', 'NDS', 'Littlest Pet Shop - Beach Friends (USA) (En,Fr,Es)', '2008', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with mini-games and customization.', 'Collect and care for pets while exploring a beach environment.', 'North American release of the beach pet simulator.', 'Dive into fun with Littlest Pet Shop: Beach Friends (USA). Use the touch screen to interact with your pets, earn kibble to buy new outfits, and complete tasks to unlock unique beach-dwelling animals in this colorful and engaging pet simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---city-friends-europe-enfrdeesnlptsvnodafi', 'NDS', 'Littlest Pet Shop - City Friends (Europe) (En,Fr,De,Es,Nl,Pt,Sv,No,Da,Fi)', '2008', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with mini-games and customization.', 'Manage pets in a bustling metropolitan setting.', 'Urban-themed pet simulation and collection.', 'Littlest Pet Shop: City Friends (Europe) features a variety of city-centric pets. Navigate urban environments, play skyscraper-themed mini-games, and dress up your pets in the latest city fashions in this comprehensive European multi-language edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---city-friends-usa-enfres', 'NDS', 'Littlest Pet Shop - City Friends (USA) (En,Fr,Es)', '2008', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with mini-games and customization.', 'Manage pets in a bustling metropolitan setting.', 'US release of the city-themed pet simulator.', 'Experience life in the big city with Littlest Pet Shop: City Friends. This North American version allows you to collect exclusive city pets, compete in urban challenges, and design custom living spaces for your animal friends using the DS stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---country-friends-europe-enfrdeesnlptsvnodafi', 'NDS', 'Littlest Pet Shop - Country Friends (Europe) (En,Fr,De,Es,Nl,Pt,Sv,No,Da,Fi)', '2008', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with mini-games and customization.', 'Raise pets in a rural, farm-like atmosphere.', 'Country-themed pet care and exploration.', 'Littlest Pet Shop: Country Friends (Europe) focuses on domestic and farm animals. Explore wide-open fields, participate in country fairs, and collect rare pets while managing your very own pet shop in this multi-language European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---country-friends-usa-enfres', 'NDS', 'Littlest Pet Shop - Country Friends (USA) (En,Fr,Es)', '2008', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with mini-games and customization.', 'Raise pets in a rural, farm-like atmosphere.', 'North American release of the country pet simulator.', 'Head to the countryside in Littlest Pet Shop: Country Friends. Collect iconic farm pets, play rural-themed mini-games, and earn rewards to decorate your shop and dress up your animal companions in this fun and charming USA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---garden-europe-enfrdeesitnlsvnodafiplcs', 'NDS', 'Littlest Pet Shop - Garden (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi,Pl,Cs)', '2009', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with gardening elements.', 'Grow flowers and care for pets in a garden sanctuary.', 'Garden-themed pet simulation for NDS.', 'Littlest Pet Shop: Garden (Europe) combines pet care with nature. Plant beautiful flowers to attract new pets, play nature-inspired mini-games, and customize your garden sanctuary in this expansive multi-language European edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---garden-korea', 'NDS', 'Littlest Pet Shop - Garden (Korea)', '2009', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with gardening elements.', 'Grow flowers and care for pets in a garden sanctuary.', 'Korean localized edition of the Garden pet sim.', 'Experience the charm of Littlest Pet Shop: Garden in Korea. This version features localized text and the same addictive gameplay of collecting colorful pets and maintaining a beautiful garden through interactive DS touch-screen tasks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---garden-usa-enfres', 'NDS', 'Littlest Pet Shop - Garden (USA) (En,Fr,Es)', '2009', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with gardening elements.', 'Grow flowers and care for pets in a garden sanctuary.', 'US release of the popular garden pet simulation.', 'Littlest Pet Shop: Garden (USA) lets you nurture both pets and plants. Use the DS stylus to water flowers, feed your animals, and unlock over 20 different pets as you create the most vibrant garden in the neighborhood.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---jungle-europe-enfrdeesitnlsvnodafiplcs', 'NDS', 'Littlest Pet Shop - Jungle (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi,Pl,Cs)', '2009', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with exploration in a tropical setting.', 'Discover and care for exotic jungle pets.', 'Tropical jungle-themed pet collection game.', 'Littlest Pet Shop: Jungle (Europe) takes you deep into the rainforest. Discover exotic animals like monkeys and tigers, play jungle-themed mini-games, and unlock unique tropical accessories in this multi-language European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---jungle-usa-enfres', 'NDS', 'Littlest Pet Shop - Jungle (USA) (En,Fr,Es)', '2009', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with exploration in a tropical setting.', 'Discover and care for exotic jungle pets.', 'North American release of the Jungle pet sim.', 'Embark on a tropical adventure with Littlest Pet Shop: Jungle. This USA version features unique jungle environments to explore, interactive pet care mechanics, and a wide variety of exotic animals to collect and customize.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---spring-europe-enfrdeesit', 'NDS', 'Littlest Pet Shop - Spring (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with seasonal spring themes.', 'Celebrate the arrival of spring with new pets and games.', 'Spring-themed pet care and mini-games.', 'Littlest Pet Shop: Spring (Europe) features a fresh, seasonal aesthetic. Collect spring-exclusive pets, participate in flower-themed mini-games, and enjoy a bright and colorful world designed for young fans in this European multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---spring-usa-enfres', 'NDS', 'Littlest Pet Shop - Spring (USA) (En,Fr,Es)', '2009', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with seasonal spring themes.', 'Celebrate the arrival of spring with new pets and games.', 'US release of the seasonal spring pet simulator.', 'Hop into fun with Littlest Pet Shop: Spring (USA). Manage your pet shop during the spring season, earn kibble through rhythmic mini-games, and unlock seasonal outfits for your favorite animal friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---winter-europe-enfrdeesitnlsvnodafiplcs', 'NDS', 'Littlest Pet Shop - Winter (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi,Pl,Cs)', '2010', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with winter-themed activities.', 'Care for pets in a snowy, festive environment.', 'Winter-themed pet simulation and collection.', 'Littlest Pet Shop: Winter (Europe) brings a snowy wonderland to your DS. Play ice-skating mini-games, collect winter-ready pets like huskies and penguins, and decorate your shop for the holidays in this multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop---winter-usa-enfres', 'NDS', 'Littlest Pet Shop - Winter (USA) (En,Fr,Es)', '2010', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Virtual pet simulation with winter-themed activities.', 'Care for pets in a snowy, festive environment.', 'North American release of the Winter pet sim.', 'Chill out with Littlest Pet Shop: Winter. This USA version features festive mini-games and exclusive winter pets. Use the touch screen to toss snowballs, feed your pets hot cocoa, and unlock cozy winter fashions for your animal collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop-3---biggest-stars---blue-team-usa-enfr', 'NDS', 'Littlest Pet Shop 3 - Biggest Stars - Blue Team (USA) (En,Fr)', '2010', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Talent show simulation with rhythmic mini-games.', 'Compete in the Biggest Stars competition with the Blue Team.', 'Competitive pet talent show simulation.', 'Littlest Pet Shop 3: Biggest Stars - Blue Team focuses on gymnastics and fashion. Lead your team of pets through rigorous training and perform in front of judges to win the ultimate talent trophy in this US release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop-3---biggest-stars---pink-team-usa-enfr', 'NDS', 'Littlest Pet Shop 3 - Biggest Stars - Pink Team (USA) (En,Fr)', '2010', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Talent show simulation with rhythmic mini-games.', 'Compete in the Biggest Stars competition with the Pink Team.', 'Competitive pet talent show simulation.', 'Littlest Pet Shop 3: Biggest Stars - Pink Team features a focus on dance and performance. Master rhythmic touch-screen challenges to make your pets the stars of the show and unlock exclusive pink-themed accessories.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('littlest-pet-shop-3---biggest-stars---purple-team-usa-enfr', 'NDS', 'Littlest Pet Shop 3 - Biggest Stars - Purple Team (USA) (En,Fr)', '2010', 'Simulation', 'Electronic Arts', '1', 'Virtual Pet', 'Talent show simulation with rhythmic mini-games.', 'Compete in the Biggest Stars competition with the Purple Team.', 'Competitive pet talent show simulation.', 'Littlest Pet Shop 3: Biggest Stars - Purple Team emphasizes art and creativity. Use the stylus to complete creative tasks, win competitions, and lead your purple-themed pet squad to the top of the leaderboards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('live-battle-card---live-on-ds-japan', 'NDS', 'Live Battle Card - Live On DS (Japan)', '2008', 'Card Battle', 'Bandai Namco', '2', 'Strategy', 'Strategic card battling based on the anime.', 'Defeat opponents in tactical card duels to become the champion.', 'Card battle RPG based on the Live On anime.', 'Live Battle Card: Live On DS brings the high-energy card game to NDS. Build a powerful deck, summon creatures, and use strategic card placements to outmaneuver rivals in this faithful adaptation of the Japanese TV series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('livly-garden-japan', 'NDS', 'Livly Garden (Japan)', '2008', 'Simulation', 'GungHo Online Entertainment', '1', 'Virtual Pet', 'Virtual gardening and creature raising simulation.', 'Cultivate a digital garden to attract and raise "Livly" creatures.', 'Unique Japanese garden and pet simulation.', 'Livly Garden is a charming spin-off of the browser game. Use the DS stylus to till soil, plant seeds, and care for bizarrely cute Livly creatures. Customize your avatar and your garden to create a unique ecosystem in this relaxing Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('locks-quest---shinmai-archineer-no-hyakunichi-sensou-japan', 'NDS', 'Lock''s Quest - Shinmai Archineer no Hyakunichi Sensou (Japan)', '2008', 'Strategy', '5th Cell', '1', 'Tower Defense', 'Action-strategy and tower defense with building mechanics.', 'Defend the kingdom by building walls and traps against the Clockwork.', 'Japanese version of the acclaimed strategy hit.', 'Lock''s Quest (Shinmai Archineer) combines real-time action with tactical building. As Lock, you must construct complex defenses during the day and fight off waves of robotic enemies at night in this unique and challenging Japanese release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('locks-quest-europe-enfrdeesit', 'NDS', 'Lock''s Quest (Europe) (En,Fr,De,Es,It)', '2008', 'Strategy', '5th Cell', '1', 'Tower Defense', 'Action-strategy and tower defense with building mechanics.', 'Defend the kingdom by building walls and traps against the Clockwork.', 'Highly-rated strategy and tower defense hybrid.', 'Lock''s Quest (Europe) offers a deep story-driven campaign. Design intricate layouts of turrets, walls, and traps using the touch screen, then step onto the battlefield to repair structures and engage in combat in this multi-language European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('locks-quest-usa-enfr', 'NDS', 'Lock''s Quest (USA) (En,Fr)', '2008', 'Strategy', '5th Cell', '1', 'Tower Defense', 'Action-strategy and tower defense with building mechanics.', 'Defend the kingdom by building walls and traps against the Clockwork.', 'US release of the innovative building strategy game.', 'Master the art of the Archineer in Lock''s Quest (USA). Featuring a gripping narrative and deep tactical gameplay, this title requires quick thinking and clever resource management to stop the advance of the mechanical Clockwork army.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lode-runner-japan', 'NDS', 'Lode Runner (Japan)', '2006', 'Puzzle', 'Hudson Soft', '1', 'Action Puzzle', 'Puzzle-platformer involving digging and trap-setting.', 'Collect all gold pieces in a level while avoiding enemies.', 'Classic arcade puzzle action revitalized for NDS.', 'Lode Runner (Japan) brings the legendary 80s gameplay to the handheld. Dig holes to trap enemies and navigate complex vertical stages to recover treasure. This version includes new levels and updated graphics for a modern puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('logic-island-europe-enfrdeesit', 'NDS', 'Logic Island (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Oxygen Studios', '1', 'Logic Puzzle', 'Logic-based puzzle game with various brain teasers.', 'Solve a series of logic puzzles to unlock new islands.', 'Tropical-themed logic puzzle collection.', 'Logic Island features a variety of brain-teasing games like Sudoku and Kakuro set against a relaxing island backdrop. Challenge your mind across hundreds of levels designed to improve your deduction skills in this European multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('logic-machines-europe-enfrdeesit', 'NDS', 'Logic Machines (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Oxygen Studios', '1', 'Logic Puzzle', 'Physics-based puzzle game with Rube Goldberg-style machines.', 'Solve complex engineering puzzles using limited parts.', 'Challenging physics and mechanical puzzle game.', 'Logic Machines (Europe) tasks players with creating functional machines to solve specific goals. Use gears, pulleys, and ramps to create chain reactions in this mentally stimulating title that rewards creativity and mechanical logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('logic-machines-usa-enfres', 'NDS', 'Logic Machines (USA) (En,Fr,Es)', '2008', 'Puzzle', 'Oxygen Studios', '1', 'Logic Puzzle', 'Physics-based puzzle game with Rube Goldberg-style machines.', 'Solve complex engineering puzzles using limited parts.', 'North American release of the mechanical puzzle hit.', 'Put your thinking cap on in Logic Machines (USA). Featuring dozens of increasingly difficult levels, this game uses the DS touch screen to let you drag and drop parts to build the perfect contraption to overcome scientific obstacles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lola-&-virginia-europe-enfrdeesitpt', 'NDS', 'Lola & Virginia (Europe) (En,Fr,De,Es,It,Pt)', '2009', 'Adventure', 'Magic Pockets', '1', 'Adventure', 'Adventure game based on the animated series.', 'Help Lola and Virginia navigate school life and rivalries.', 'School-based social adventure and mini-games.', 'Lola & Virginia brings the cat-and-dog rivalry of the cartoon to NDS. Complete missions, participate in school activities, and manage social relationships in this European multi-language title aimed at fans of the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('londonian-gothics---meikyuu-no-lolita-japan', 'NDS', 'Londonian Gothics - Meikyuu no Lolita (Japan)', '2008', 'Adventure', 'Konami', '1', 'Visual Novel', 'Action RPG with a gothic lolita aesthetic and dungeon crawling.', 'Navigate a 2D labyrinth to stop an ancient evil.', 'Stylized gothic action RPG and dungeon crawler.', 'Londonian Gothics: Meikyuu no Lolita features a unique Victorian aesthetic. Customize your character''s gothic lolita fashion, which affects your stats, and fight through challenging labyrinths in this atmospheric and visually distinct Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('long-vacation---iruka-to-watashi-japan', 'NDS', 'Long Vacation - Iruka to Watashi (Japan)', '2008', 'Simulation', 'Success', '1', 'Life Simulation', 'Dolphin training and ocean exploration simulation.', 'Bond with your dolphin and explore the wonders of the sea.', 'Relaxing dolphin simulation and aquatic adventure.', 'Long Vacation: Iruka to Watashi (Dolphin and Me) focuses on the friendship between a girl and a dolphin. Train your aquatic friend to perform tricks, explore coral reefs, and enjoy a peaceful virtual vacation in this charming Japanese sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lonq!-highland-in-ds---puu-puu-seijin-arawaru!!-shukketsu-dai-service!-onara-no-saiten-sp-japan', 'NDS', 'LonQ! Highland in DS - Puu Puu Seijin Arawaru!! Shukketsu Dai-service! Onara no Saiten SP (Japan)', '2009', 'Party', 'Game Studio', '4', 'Party', 'Humorous quiz and mini-game collection with crude humor.', 'Win a series of bizarre contests on "Highland Island."', 'Quirky and irreverent Japanese mini-game collection.', 'LonQ! Highland in DS is a parody-filled title featuring crude humor and surreal challenges. Participate in high-speed quizzes and bizarre physical contests in this unique and offbeat experience that captures a specific niche of Japanese comedy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---cartoon-concerto-europe-enfrdeesit', 'NDS', 'Looney Tunes - Cartoon Concerto (Europe) (En,Fr,De,Es,It)', '2008', 'Music', 'Amaze Entertainment', '1', 'Rhythm', 'Rhythm-action gameplay using the stylus to conduct music.', 'Lead a Looney Tunes orchestra through classic cartoon scores.', 'Musical rhythm game featuring Bugs Bunny and friends.', 'Looney Tunes: Cartoon Concerto (Europe) lets you conduct the music of legendary cartoons. Use the stylus to tap and slide in rhythm with the Looney Tunes'' most famous musical scores while watching classic animated scenes unfold on the dual screens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---cartoon-conductor-usa-enfrdeesit', 'NDS', 'Looney Tunes - Cartoon Conductor (USA) (En,Fr,De,Es,It)', '2008', 'Music', 'Amaze Entertainment', '1', 'Rhythm', 'Rhythm-action gameplay using the stylus to conduct music.', 'Lead a Looney Tunes orchestra through classic cartoon scores.', 'North American release of the Looney Tunes music game.', 'Become the conductor in Looney Tunes: Cartoon Conductor (USA). Master the tempo of iconic orchestral tracks while interacting with characters like Daffy Duck and Porky Pig in this high-energy rhythm title designed for the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---duck-amuck-europe', 'NDS', 'Looney Tunes - Duck Amuck (Europe)', '2007', 'Puzzle', 'Amaze Entertainment', '1', 'Puzzle', 'Interactive sandbox and mini-game collection.', 'Annoy Daffy Duck until his "rage meter" reaches the maximum.', 'A creative interactive cartoon sandbox with Daffy Duck.', 'Looney Tunes: Duck Amuck (Europe) is a unique meta-game where you play as the animator. Use the touch screen to poke, prod, and mess with Daffy Duck across various mini-games, trying to make him lose his temper in hilarious ways.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---duck-amuck-france', 'NDS', 'Looney Tunes - Duck Amuck (France)', '2007', 'Puzzle', 'Amaze Entertainment', '1', 'Puzzle', 'Interactive sandbox and mini-game collection.', 'Annoy Daffy Duck until his "rage meter" reaches the maximum.', 'French regional release of the Daffy Duck annoyance sim.', 'Experience the humor of Duck Amuck in France. Use the DS stylus to paint over Daffy, erase his surroundings, and trigger classic slapstick reactions in this creative adaptation of the famous "Duck Amuck" short film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---duck-amuck-germany', 'NDS', 'Looney Tunes - Duck Amuck (Germany)', '2007', 'Puzzle', 'Amaze Entertainment', '1', 'Puzzle', 'Interactive sandbox and mini-game collection.', 'Annoy Daffy Duck until his "rage meter" reaches the maximum.', 'German regional release of the Daffy Duck interactive game.', 'Looney Tunes: Duck Amuck (Germany) brings the fourth-wall-breaking humor of Looney Tunes to life. Challenge Daffy in diverse mini-games that utilize the DS microphone and touch screen to drive the unlucky duck to total frustration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---duck-amuck-italy', 'NDS', 'Looney Tunes - Duck Amuck (Italy)', '2007', 'Puzzle', 'Amaze Entertainment', '1', 'Puzzle', 'Interactive sandbox and mini-game collection.', 'Annoy Daffy Duck until his "rage meter" reaches the maximum.', 'Italian regional release of the interactive cartoon sim.', 'Play the role of the mischievous animator in the Italian version of Duck Amuck. Engage in stylus-based combat and puzzles against Daffy Duck, ensuring he never gets a moment of peace in this highly interactive experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---duck-amuck-spain', 'NDS', 'Looney Tunes - Duck Amuck (Spain)', '2007', 'Puzzle', 'Amaze Entertainment', '1', 'Puzzle', 'Interactive sandbox and mini-game collection.', 'Annoy Daffy Duck until his "rage meter" reaches the maximum.', 'Spanish regional release of the Daffy Duck prank game.', 'Master the art of cartoon mischief in Looney Tunes: Duck Amuck (Spain). Tap and slide to disrupt Daffy''s life in a series of clever mini-games that pay homage to the classic Warner Bros. animation style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---duck-amuck-usa', 'NDS', 'Looney Tunes - Duck Amuck (USA)', '2007', 'Puzzle', 'Amaze Entertainment', '1', 'Puzzle', 'Interactive sandbox and mini-game collection.', 'Annoy Daffy Duck until his "rage meter" reaches the maximum.', 'North American release of the Daffy Duck interaction game.', 'Duck Amuck (USA) turns the DS into a canvas for comedy. Poke and pull at Daffy Duck to fill his anger meter through dozens of creative mini-games, proving that being the animator is just as fun as watching the cartoon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lord-of-the-rings-the---aragorns-quest-europe-enfrdeesitnl', 'NDS', 'Lord of the Rings, The - Aragorn''s Quest (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Action / Adventure', 'Headstrong Games', '1', 'Action Adventure', 'Isometric action-adventure with combat and exploration.', 'Relive the epic events of the Lord of the Rings trilogy.', 'Action-packed retelling of the LOTR saga as Aragorn.', 'Lord of the Rings: Aragorn''s Quest (Europe) offers a family-friendly take on Middle-earth. Control Aragorn as he journeys through legendary battles, using swordplay and archery to protect his friends and defeat the forces of Sauron.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lord-of-the-rings-the---aragorns-quest-usa-enfrespt', 'NDS', 'Lord of the Rings, The - Aragorn''s Quest (USA) (En,Fr,Es,Pt)', '2010', 'Action / Adventure', 'Headstrong Games', '1', 'Action Adventure', 'Isometric action-adventure with combat and exploration.', 'Relive the epic events of the Lord of the Rings trilogy.', 'North American release of the Aragorn action-adventure.', 'Embark on an epic journey in Aragorn''s Quest (USA). This NDS title allows players to engage in real-time combat and exploration, reliving the most heroic moments of the Lord of the Rings films through the eyes of the future King of Gondor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lord-of-the-rings-the---conquest-europe-enfrdeesit', 'NDS', 'Lord of the Rings, The - Conquest (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Pandemic Studios', '1', 'Action', 'Tactical action and real-time combat with unit management.', 'Fight the greatest battles of Middle-earth as Good or Evil.', 'Strategic battle simulator set in the LOTR universe.', 'Lord of the Rings: Conquest (Europe) lets you participate in massive scale battles. Choose to fight for the Free Peoples or the forces of Sauron, utilizing different classes like warriors and mages in this action-heavy adaptation for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lord-of-the-rings-the---conquest-usa-enfrdeesit', 'NDS', 'Lord of the Rings, The - Conquest (USA) (En,Fr,De,Es,It)', '2009', 'Action', 'Pandemic Studios', '1', 'Action', 'Tactical action and real-time combat with unit management.', 'Fight the greatest battles of Middle-earth as Good or Evil.', 'North American release of the LOTR battle game.', 'Conquer Middle-earth in Lord of the Rings: Conquest (USA). Engage in squad-based combat and master the unique abilities of heroes and villains alike as you fight through the cinematic storylines of the legendary film trilogy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-in-blue-europe-enfrdeesit', 'NDS', 'Lost in Blue (Europe) (En,Fr,De,Es,It)', '2006', 'Adventure', 'Konami', '1', 'Survival', 'Survival simulation with resource management and crafting.', 'Survive on a deserted island and find a way back home.', 'Intense survival adventure and island simulation.', 'Lost in Blue (Europe) challenges you to survive after a shipwreck. Manage your hunger, thirst, and stamina while exploring the island, crafting tools, and foraging for food in this deep and realistic survival experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-in-blue-usa', 'NDS', 'Lost in Blue (USA)', '2006', 'Adventure', 'Konami', '1', 'Survival', 'Survival simulation with resource management and crafting.', 'Survive on a deserted island and find a way back home.', 'The North American debut of the island survival hit.', 'Experience the struggle of survival in Lost in Blue (USA). Use the DS touch screen to build fires, catch fish, and explore a vast mysterious island. Every decision matters as you try to stay alive and uncover the secrets of your environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-in-blue-2-europe-enfrdeesit', 'NDS', 'Lost in Blue 2 (Europe) (En,Fr,De,Es,It)', '2007', 'Adventure', 'Konami', '1', 'Survival', 'Survival simulation with dual-protagonist mechanics.', 'Survive and escape the island while managing two characters.', 'Enhanced survival sequel with more crafting and stories.', 'Lost in Blue 2 (Europe) expands the survival formula. Play as a boy or a girl and work together to gather resources, cook meals, and navigate treacherous terrain. Featuring new mini-games and deeper exploration than the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-in-blue-2-usa-enjafrdeesit', 'NDS', 'Lost in Blue 2 (USA) (En,Ja,Fr,De,Es,It)', '2007', 'Adventure', 'Konami', '1', 'Survival', 'Survival simulation with dual-protagonist mechanics.', 'Survive and escape the island while managing two characters.', 'North American release of the second survival adventure.', 'Double the survival challenge in Lost in Blue 2 (USA). This version includes multiple language options and refined touch controls, making the process of building shelter and hunting for food more engaging than ever on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-in-blue-3-europe-enfrdeesit', 'NDS', 'Lost in Blue 3 (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Konami', '1', 'Survival', 'Survival simulation with multiple characters and storylines.', 'Escaped a doomed ship and lead a group to safety.', 'The third installment of the deep island survival series.', 'Lost in Blue 3 (Europe) features a larger cast of survivors, each with unique skills. Explore a massive island, solve environmental puzzles, and manage the complex needs of your group in this ambitious survival-drama sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-in-blue-3-usa', 'NDS', 'Lost in Blue 3 (USA)', '2008', 'Adventure', 'Konami', '1', 'Survival', 'Survival simulation with multiple characters and storylines.', 'Escaped a doomed ship and lead a group to safety.', 'North American release of the third survival saga.', 'Survive against all odds in Lost in Blue 3 (USA). With more complex crafting systems and a branch narrative based on your choices, this title offers the ultimate portable survival experience for fans of the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lostmagic-europe-enfrdees', 'NDS', 'LostMagic (Europe) (En,Fr,De,Es)', '2006', 'Strategy', 'Taito', '1', 'Strategy RPG', 'Real-time strategy RPG with stylus-drawn magic runes.', 'Defeat the Seven Sages and restore balance to the world.', 'Innovative magic-based RTS and RPG hybrid.', 'LostMagic (Europe) uses the DS stylus in a unique way—you must draw runes on the screen to cast spells. Capture monsters to fight alongside you and explore a beautiful fantasy world in this acclaimed strategic RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lostmagic-japan', 'NDS', 'LostMagic (Japan)', '2006', 'Strategy', 'Taito', '1', 'Strategy RPG', 'Real-time strategy RPG with stylus-drawn magic runes.', 'Defeat the Seven Sages and restore balance to the world.', 'Japanese original of the rune-casting magic RPG.', 'Experience the origins of rune-based combat in LostMagic (Japan). Master the art of drawing complex spells in real-time battles, collect powerful creatures, and enjoy a deep narrative in this Taito-developed strategic gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lostmagic-usa-enfrdees', 'NDS', 'LostMagic (USA) (En,Fr,De,Es)', '2006', 'Strategy', 'Taito', '1', 'Strategy RPG', 'Real-time strategy RPG with stylus-drawn magic runes.', 'Defeat the Seven Sages and restore balance to the world.', 'North American release of the rune-drawing RPG.', 'Draw your way to victory in LostMagic (USA). This game combines the depth of an RPG with the fast pace of real-time strategy. Customize your spellbook by combining different elemental runes to unleash devastating attacks on your enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('love-cat-life-japan', 'NDS', 'Love Cat Life (Japan)', '2009', 'Simulation', 'Idea Factory', '1', 'Dating Sim', 'Virtual pet simulation focused on caring for cats.', 'Raise, groom, and play with a variety of cute kittens.', 'Charming Japanese cat-raising simulation for NDS.', 'Love Cat Life is a must-play for feline lovers. Use the DS touch screen to pet your cats, feed them, and teach them tricks. Customize your room and participate in various activities to build a deep bond with your virtual pets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('love-is-in-bloom---the-flower-shop-garden-europe-enfrdeesitnlru', 'NDS', 'Love Is... in Bloom - The Flower Shop Garden (Europe) (En,Fr,De,Es,It,Nl,Ru)', '2009', 'Simulation', 'Rondomedia', '1', 'Gardening', 'Management simulation with floral design and gardening.', 'Run a successful flower shop and find romance.', 'Romantic flower shop management and gardening sim.', 'Love Is... in Bloom combines business management with a sweet narrative. Grow a variety of flowers, arrange beautiful bouquets for customers, and navigate a heartwarming story in this multi-language European simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('love-love-hamster-japan', 'NDS', 'Love Love Hamster (Japan)', '2007', 'Simulation', 'Success', '1', 'Virtual Pet', 'Virtual pet simulation with hamster-themed mini-games.', 'Care for your hamster and participate in local festivals.', 'Adorable hamster-raising sim for the Japanese market.', 'Love Love Hamster lets you look after the cutest rodents on the NDS. Feed your hamster, decorate its cage, and play a variety of mini-games to win prizes and keep your tiny companion happy in this relaxing Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('love-plus-japan', 'NDS', 'Love Plus (Japan)', '2009', 'Simulation', 'Konami', '1', 'Dating Sim', 'Real-time dating simulation and social interaction.', 'Build a relationship with one of three high school girls.', 'The revolutionary Japanese dating sim phenomenon.', 'Love Plus changed the genre by allowing real-time interaction. Using the DS internal clock, players experience daily life with their virtual girlfriend, going on dates and having conversations that evolve over weeks and months.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('love-plus+-japan', 'NDS', 'Love Plus+ (Japan)', '2010', 'Simulation', 'Konami', '1', 'Dating Sim', 'Enhanced real-time dating simulation with new events.', 'Deepen your bond with your girlfriend through new activities.', 'Expanded version of the cult-classic dating sim.', 'Love Plus+ adds even more content to the original experience. Featuring overnight trips, new dialogue, and improved touch-screen interactions, it remains the definitive way to experience this famous Japanese social simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lovely-lisa-europe-enfres', 'NDS', 'Lovely Lisa (Europe) (En,Fr,Es)', '2008', 'Simulation', 'Ubisoft', '1', 'Life Simulation', 'Career simulation and mini-game collection.', 'Help Lisa complete various chores and career tasks.', 'Fun and educational life-sim for young girls.', 'Lovely Lisa (Europe) features a variety of mini-games centered around daily life. From cooking and cleaning to working as a fashion designer, help Lisa master her "lovely" skills in this charming multi-language handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lovely-lisa-usa-enfres', 'NDS', 'Lovely Lisa (USA) (En,Fr,Es)', '2008', 'Simulation', 'Ubisoft', '1', 'Life Simulation', 'Career simulation and mini-game collection.', 'Help Lisa complete various chores and career tasks.', 'North American release of the Lisa life-sim.', 'Join Lisa in her daily routines in Lovely Lisa (USA). Use the stylus to complete household tasks, dress up in different outfits, and unlock new mini-games as you help Lisa become the most helpful and talented girl in town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lucky-luke---the-daltons-europe-enfrdeesitnl', 'NDS', 'Lucky Luke - The Daltons (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Action', 'Atari', '1', 'Action', 'Platforming and puzzle-solving with the Dalton brothers.', 'Help the Daltons escape jail and evade Lucky Luke.', 'Side-scrolling adventure based on the Western comic.', 'Lucky Luke: The Daltons (Europe) lets you play as the bumbling outlaws. Navigate a series of trap-filled levels, solve environmental puzzles, and try to stay one step ahead of the fastest gunslinger in the West in this multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lucky-star---moe-drill-japan', 'NDS', 'Lucky Star - Moe Drill (Japan)', '2005', 'Educational', 'Kadokawa Shoten', '1', 'Quiz', 'Mini-game collection and quiz with anime characters.', 'Win quizzes and mini-games to bond with the Lucky Star cast.', 'Quirky Japanese quiz game based on the hit anime.', 'Lucky Star: Moe Drill features the iconic cast of the anime in a series of brain-teasing challenges. Test your knowledge of pop culture and school subjects while enjoying the humorous dialogue and art style the series is famous for.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia---curse-of-the-sinistrals-usa', 'NDS', 'Lufia - Curse of the Sinistrals (USA)', '2010', 'RPG', 'Neverland', '1', 'JRPG', 'Action-RPG with fast-paced combat and puzzle-solving.', 'Defeat the Sinistrals and save the world from destruction.', '3D reimagining of the classic Lufia II RPG.', 'Lufia: Curse of the Sinistrals (USA) transforms the classic turn-based RPG into a high-octane action experience. Swap between six unique characters in real-time, solve complex 3D puzzles, and battle massive bosses in this epic handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luminous-arc-europe', 'NDS', 'Luminous Arc (Europe)', '2007', 'Strategy RPG', 'Imageepoch', '1', 'Tactical RPG', 'Turn-based tactical RPG with grid-based movement and magic.', 'Defeat the rogue witches and protect the Luminous Church.', 'Fantasy strategy RPG with deep character customization.', 'Luminous Arc (Europe) offers a classic tactical RPG experience on the NDS. Command a diverse group of knights and mages, utilize elemental "Flash Drive" attacks, and experience an epic story with multiple endings and high-quality anime voice acting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luminous-arc-japan', 'NDS', 'Luminous Arc (Japan)', '2007', 'Strategy RPG', 'Imageepoch', '1', 'Tactical RPG', 'Turn-based tactical RPG with grid-based movement and magic.', 'Defeat the rogue witches and protect the Luminous Church.', 'Original Japanese version of the tactical hit.', 'Luminous Arc (Japan) introduces the innovative "Lapis" system for skill customization. Engage in strategic battles on isometric maps and build relationships with your party members through the "Intermission" dialogue system between story chapters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luminous-arc-usa', 'NDS', 'Luminous Arc (USA)', '2007', 'Strategy RPG', 'Imageepoch', '1', 'Tactical RPG', 'Turn-based tactical RPG with grid-based movement and magic.', 'Defeat the rogue witches and protect the Luminous Church.', 'North American release of the acclaimed strategy RPG.', 'Experience Luminous Arc (USA) for tactical combat and rich storytelling. Master the positioning of your units to unleash powerful team attacks, unlock secret characters, and enjoy a polished localization of this fan-favorite fantasy strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luminous-arc-2---will-japan', 'NDS', 'Luminous Arc 2 - Will (Japan)', '2009', 'Strategy RPG', 'Imageepoch', '1', 'Tactical RPG', 'Strategic RPG with improved combat and "Engagement" system.', 'Choose between witches and knights to decide the fate of the world.', 'The expanded Japanese sequel to Luminous Arc.', 'Luminous Arc 2 - Will expands the series with more characters and the "Engagement" mechanic, allowing for powerful stat boosts. This Japanese edition features deep branching paths and strategic combat designed for fans of the first game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luminous-arc-2-europe', 'NDS', 'Luminous Arc 2 (Europe)', '2009', 'Strategy RPG', 'Imageepoch', '1', 'Tactical RPG', 'Strategic RPG with improved combat and "Engagement" system.', 'Choose between witches and knights to decide the fate of the world.', 'The strategic RPG sequel for European players.', 'Luminous Arc 2 (Europe) brings the epic conflict to the NDS with refined tactical gameplay. Manage your mana carefully, form pacts with magical witches, and navigate a complex political narrative through dozens of turn-based battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luminous-arc-2-usa', 'NDS', 'Luminous Arc 2 (USA)', '2009', 'Strategy RPG', 'Imageepoch', '1', 'Tactical RPG', 'Strategic RPG with improved combat and "Engagement" system.', 'Choose between witches and knights to decide the fate of the world.', 'North American release of the enhanced sequel.', 'Luminous Arc 2 (USA) features an extensive campaign with multiple endings. Use the "Flash Drive" attacks and a refined level-up system to dominate the battlefield in this content-rich strategy RPG that improves on every aspect of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luminous-arc-3---eyes-japan', 'NDS', 'Luminous Arc 3 - Eyes (Japan)', '2011', 'Strategy RPG', 'Imageepoch', '1', 'Tactical RPG', 'Tactical RPG with academy simulation and social bonding.', 'Investigate the mysteries of the academy and fight the Holy Eye.', 'The final NDS entry in the Luminous Arc trilogy.', 'Luminous Arc 3 - Eyes (Japan) introduces a "School Life" element to the series. Balance your studies and relationships during the day to gain combat advantages at night in this polished tactical RPG featuring high-quality anime cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunar---dragon-song-usa', 'NDS', 'Lunar - Dragon Song (USA)', '2005', 'RPG', 'Game Arts', '1', 'JRPG', 'Turn-based RPG with traditional leveling and combat.', 'Solve the mystery of a world where people are losing their voices.', 'A new adventure in the classic Lunar universe.', 'Lunar: Dragon Song (USA) is the first original NDS entry in the series. Experience a unique combat system where you choose between "Combat Mode" to earn XP or "Virtue Mode" to earn items, exploring the origins of the Lunar legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunar---genesis-europe', 'NDS', 'Lunar - Genesis (Europe)', '2005', 'RPG', 'Game Arts', '1', 'JRPG', 'Turn-based RPG with traditional leveling and combat.', 'Solve the mystery of a world where people are losing their voices.', 'The European release of the Lunar NDS prequel.', 'Lunar: Genesis (known as Dragon Song in the US) offers classic RPG exploration. Guide Jian and his friends through the world of Lunar, mastering elemental magic and uncovering a plot that threatens the peace of the entire planet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunar---genesis-japan', 'NDS', 'Lunar - Genesis (Japan)', '2005', 'RPG', 'Game Arts', '1', 'JRPG', 'Turn-based RPG with traditional leveling and combat.', 'Solve the mystery of a world where people are losing their voices.', 'The Japanese debut of the Lunar prequel.', 'Lunar: Genesis (Japan) brings the beloved franchise to the dual-screen handheld. Featuring a new card-based power-up system and stylus-controlled menus, it provides a nostalgic yet fresh take on the classic RPG formula for longtime fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunar-knights-europe-enfrdeesit', 'NDS', 'Lunar Knights (Europe) (En,Fr,De,Es,It)', '2007', 'Action / Adventure', 'Kojima Productions', '1', 'Action Adventure', 'Isometric action-RPG with weather-based combat.', 'Hunt vampires and stop the eternal night from consuming the world.', 'Stylish vampire-hunting action from Kojima Productions.', 'Lunar Knights (Europe) is the spiritual successor to Boktai. Utilize the "Solar" and "Lunar" weapon systems to defeat undead foes. Solve puzzles and engage in fast-paced combat that reacts to a dynamic in-game weather and time-of-day system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunar-knights-usa-enes', 'NDS', 'Lunar Knights (USA) (En,Es)', '2007', 'Action / Adventure', 'Kojima Productions', '1', 'Action Adventure', 'Isometric action-RPG with weather-based combat.', 'Hunt vampires and stop the eternal night from consuming the world.', 'Action-packed vampire hunting for North America.', 'Master the dual powers of the sun and moon in Lunar Knights (USA). Switch between two heroes with unique playstyles, upgrade your weapons with elemental crystals, and participate in high-speed space shooter mini-games in this deep action RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunnis-spain', 'NDS', 'Lunnis (Spain)', '2007', 'Platformer', 'Bit Managers', '1', 'Platformer', 'Educational mini-games based on the popular TV show.', 'Learn basic logic, colors, and numbers with the Lunnis.', 'Spanish-language educational game for young children.', 'Lunnis (Spain) features the beloved characters from the Spanish children''s program. Through a series of interactive and colorful mini-games, kids develop foundational skills in a fun and encouraging environment tailored for the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lupin-sansei---shijou-saidai-no-zunousen-japan', 'NDS', 'Lupin Sansei - Shijou Saidai no Zunousen (Japan)', '2009', 'Adventure', 'Banpresto', '1', 'Visual Novel', 'Stealth-action and puzzle-solving starring Lupin III.', 'Pull off the greatest heist in history using stealth and gadgets.', 'A high-stakes heist adventure featuring the famous thief.', 'Lupin Sansei - Shijou Saidai no Zunousen is a tactical adventure game. Control Lupin, Jigen, and Goemon to bypass security systems, solve complex logic puzzles, and evade Inspector Zenigata in this stylish Japanese adaptation of the hit anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lux-pain-europe', 'NDS', 'Lux-Pain (Europe)', '2008', 'Adventure', 'Killaware', '1', 'Psychological Adventure', 'Mystery visual novel with supernatural investigation.', 'Uncover the truth behind a wave of suicides in Kisaragi City.', 'A dark, psychological mystery and visual novel.', 'Lux-Pain (Europe) puts you in the role of an investigator using "Sigma" powers. Use the stylus to "scratch" the screen and reveal hidden emotions or parasites in people''s minds, solving a dark conspiracy in this text-heavy supernatural thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lux-pain-japan', 'NDS', 'Lux-Pain (Japan)', '2008', 'Adventure', 'Killaware', '1', 'Psychological Adventure', 'Mystery visual novel with supernatural investigation.', 'Uncover the truth behind a wave of suicides in Kisaragi City.', 'The original Japanese psychological mystery.', 'Lux-Pain (Japan) features an atmospheric soundtrack and deep narrative choices. Explore the city, interview suspects, and use your psychic abilities to delve into the collective unconscious and stop a silent epidemic from destroying the town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lux-pain-usa', 'NDS', 'Lux-Pain (USA)', '2008', 'Adventure', 'Killaware', '1', 'Psychological Adventure', 'Mystery visual novel with supernatural investigation.', 'Uncover the truth behind a wave of suicides in Kisaragi City.', 'North American release of the supernatural investigator.', 'Experience the intense story of Lux-Pain (USA). This visual novel utilizes the DS touch screen for unique investigative mechanics, allowing players to physically "uncover" the secrets buried within the hearts of the characters in Kisaragi City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luxor---pharaohs-challenge-europe-enfrdeesit', 'NDS', 'Luxor - Pharaoh''s Challenge (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'MumboJumbo', '1', 'Match-3', 'Match-3 marble shooter with an Egyptian theme.', 'Clear the chain of marbles before they reach the pyramid.', 'Addictive puzzle action set in ancient Egypt.', 'Luxor: Pharaoh''s Challenge (Europe) brings the classic PC puzzle gameplay to the NDS. Use the stylus to aim and shoot colored orbs, creating matches and unleashing powerful Egyptian power-ups to save your kingdom across 88 challenging levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luxor---pharaohs-challenge-usa', 'NDS', 'Luxor - Pharaoh''s Challenge (USA)', '2008', 'Puzzle', 'MumboJumbo', '1', 'Match-3', 'Match-3 marble shooter with an Egyptian theme.', 'Clear the chain of marbles before they reach the pyramid.', 'The North American release of the hit marble shooter.', 'Battle through the lands of Egypt in Luxor: Pharaoh''s Challenge (USA). Featuring vibrant graphics and fast-paced gameplay, this title challenges your reflexes and strategy as you work to stop the advancing spheres and unlock ancient treasures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lyra-no-bouken---ougon-no-rashinban-japan', 'NDS', 'Lyra no Bouken - Ougon no Rashinban (Japan)', '2009', 'Adventure', 'Taito', '1', 'Action Adventure', '3D action-adventure based on "The Golden Compass."', 'Guide Lyra and her daemon Pantalaimon to the North.', 'Epic fantasy adventure based on the movie and book.', 'Lyra no Bouken: Ougon no Rashinban is the Japanese adaptation of The Golden Compass. Use the Alethiometer to find secrets, solve environmental puzzles, and participate in mini-games featuring armored bears in this cinematic handheld quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('m-night-shyamalan-the-last-airbender-europe-enfrdeesit-ndsi-enhanced', 'NDS', 'M. Night Shyamalan The Last Airbender (Europe) (En,Fr,De,Es,It) (NDSi Enhanced)', '2010', 'Action / Adventure', 'THQ Studio Australia', '1', 'Action Adventure', 'Action-adventure with elemental combat and platforming.', 'Master the four elements and stop the Fire Nation''s conquest.', 'DSi enhanced action game based on the movie.', 'M. Night Shyamalan''s The Last Airbender (Europe) allows you to control Aang and Zuko. Use the DSi camera for special interactions and master elemental bending moves to defeat enemies in this action-packed tie-in to the motion picture.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('m-night-shyamalan-the-last-airbender-usa-enfr-ndsi-enhanced', 'NDS', 'M. Night Shyamalan The Last Airbender (USA) (En,Fr) (NDSi Enhanced)', '2010', 'Action / Adventure', 'THQ Studio Australia', '1', 'Action Adventure', 'Action-adventure with elemental combat and platforming.', 'Master the four elements and stop the Fire Nation''s conquest.', 'US release of the Airbender action game for NDSi.', 'Play through the events of the movie in The Last Airbender (USA). Harness the power of Air and Fire bending with touch-screen controls, unlock special abilities, and explore detailed levels while experiencing the journey of the Avatar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('m&ms---adventure-usa', 'NDS', 'M&M''s - Adventure (USA)', '2008', 'Action', 'Sensory Sweep', '1', 'Action', 'Adventure platformer featuring M&M''s characters.', 'Explore different worlds to collect spilled M&M''s candies.', 'Colorful candy-themed adventure for kids.', 'M&M''s Adventure (USA) takes the iconic characters to diverse locations like the factory and the wild west. Solve simple puzzles and navigate platforms to recover the lost M&M''s in this family-friendly title designed for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('m&ms---break-em-europe-enfrdeesit', 'NDS', 'M&M''s - Break ''em (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Frame Studios', '1', 'Arcade Puzzle', 'Block-breaking puzzle game with M&M''s themes.', 'Clear the screen of blocks to progress through levels.', 'Simple and fun M&M''s puzzle action.', 'M&M''s Break ''em (Europe) is a classic "Breakout" style game. Use the stylus to control your paddle and bounce the ball to clear blocks, featuring the various M&M''s personalities and colorful graphics in this multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('m&ms---break-em-usa', 'NDS', 'M&M''s - Break ''em (USA)', '2007', 'Puzzle', 'Frame Studios', '1', 'Arcade Puzzle', 'Block-breaking puzzle game with M&M''s themes.', 'Clear the screen of blocks to progress through levels.', 'US release of the candy-themed puzzle game.', 'Break through the fun in M&M''s Break ''em (USA). This title offers dozens of levels across different difficulty settings, challenging players to clear the board and earn high scores while interacting with Red, Yellow, and the rest of the gang.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('m&ms---kart-racing-usa-rev-1', 'NDS', 'M&M''s - Kart Racing (USA) (Rev 1)', '2008', 'Racing', 'Sidhe Interactive', '4', 'Kart Racing', 'Kart racing with power-ups and M&M''s characters.', 'Race against rivals to win the candy championship.', 'Fast-paced candy-themed racing for the NDS.', 'M&M''s Kart Racing (USA) puts you behind the wheel of a personalized chocolate kart. Drift through candy-coated tracks, collect power-ups, and outpace your opponents to prove you''re the fastest racer in the M&M''s universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mabeopcheonjamun-ds-korea', 'NDS', 'Mabeopcheonjamun DS (Korea)', '2007', 'Educational', 'Daesung C&C', '1', 'Language Learning', 'Educational RPG teaching Hanja (Chinese characters).', 'Defeat enemies by drawing the correct Hanja characters.', 'Popular Korean educational RPG based on the comic.', 'Mabeopcheonjamun DS uses the "Magic Thousand Character Classic" theme to teach language. Use the stylus to draw specific characters to cast spells, making the process of learning Hanja an engaging part of an epic fantasy adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mabeopcheonjamun-ds-2---choehuui-hanjamabeop-korea', 'NDS', 'Mabeopcheonjamun DS 2 - Choehuui Hanjamabeop (Korea)', '2008', 'Educational', 'Daesung C&C', '1', 'Language Learning', 'Educational RPG sequel teaching advanced Hanja.', 'Use your magic to save the world from the Great Demon King.', 'The high-stakes sequel to the Korean educational hit.', 'Mabeopcheonjamun DS 2 offers more complex characters and deeper RPG mechanics. Master the final Hanja magic through challenging drawing exercises and epic boss battles in this successful educational title for Korean students.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('machi-no-pet-ya-san-ds---200-piki-wan-chan-daishuugou-japan', 'NDS', 'Machi no Pet-ya-san DS - 200 Piki Wan-chan Daishuugou (Japan)', '2008', 'Simulation', 'Namco Bandai', '1', 'Pet Simulation', 'Pet shop management and dog raising simulation.', 'Manage a successful pet shop and care for 200 different dogs.', 'Extensive dog breeding and pet shop sim.', 'Machi no Pet-ya-san DS features a massive roster of dog breeds. Manage your store''s inventory, groom your pets, and help customers find their perfect canine companion in this detailed and adorable Japanese pet management simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('machi-no-pet-ya-san-ds-2---wannyan-333-hiki-daishuugou!-japan', 'NDS', 'Machi no Pet-ya-san DS 2 - Wannyan 333-hiki Daishuugou! (Japan)', '2009', 'Simulation', 'Namco Bandai', '1', 'Pet Simulation', 'Expanded pet shop management with both dogs and cats.', 'Expand your business by caring for over 333 pets.', 'The massive sequel to the Japanese pet shop sim.', 'Machi no Pet-ya-san DS 2 adds cats to the mix. With over 333 total pets to collect and care for, this sequel offers more mini-games, deeper management options, and a wider variety of animals to ensure every customer leaves happy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar---escape-2-africa-europe', 'NDS', 'Madagascar - Escape 2 Africa (Europe)', '2008', 'Action / Adventure', 'Beenox', '1', 'Action Adventure', 'Action-adventure with platforming and character-specific mini-games.', 'Help the Zoosters survive the African wilderness and fix the plane.', 'Wild African adventure based on the movie sequel.', 'Madagascar: Escape 2 Africa (Europe) features Alex, Marty, Melman, and Gloria in a series of fun missions. Explore the African savanna, play rhythmic mini-games, and use unique animal abilities to solve puzzles in this multi-language European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar---escape-2-africa-usa', 'NDS', 'Madagascar - Escape 2 Africa (USA)', '2008', 'Action / Adventure', 'Beenox', '1', 'Action Adventure', 'Action-adventure with platforming and character-specific mini-games.', 'Help the Zoosters survive the African wilderness and fix the plane.', 'North American release of the hit movie sequel.', 'Join the Madagascar crew in Escape 2 Africa (USA). This version features the same high-energy platforming and touch-screen challenges, allowing fans to relive the film''s funniest moments while exploring vast African environments on their DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-europe', 'NDS', 'Madagascar (Europe)', '2005', 'Action / Adventure', 'Toys for Bob', '1', 'Platform Adventure', '3D platforming and action with multiple playable characters.', 'Escape from the Central Park Zoo and reach the island of Madagascar.', 'The original movie adventure in portable form.', 'Madagascar (Europe) brings the first film''s story to your NDS. Master Alex’s roar, Marty’s kick, and Gloria’s butt-bounce to overcome obstacles and defeat the Foosa in this action-packed multi-language platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-france', 'NDS', 'Madagascar (France)', '2005', 'Action / Adventure', 'Toys for Bob', '1', 'Platform Adventure', '3D platforming and action with multiple playable characters.', 'Escape from the Central Park Zoo and reach the island of Madagascar.', 'French version of the classic movie adventure.', 'Revivez l''aventure du premier film Madagascar sur DS. Controllez vos animaux favoris du zoo de Central Park et utilisez leurs capacités uniques pour explorer des niveaux variés et atteindre l''île sauvage de Madagascar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-germany', 'NDS', 'Madagascar (Germany)', '2005', 'Action / Adventure', 'Toys for Bob', '1', 'Platform Adventure', '3D platforming and action with multiple playable characters.', 'Escape from the Central Park Zoo and reach the island of Madagascar.', 'German version of the classic movie adventure.', 'Erlebe das Abenteuer von Madagascar auf dem NDS. Nutze die Spezialmanöver von Alex, Marty, Melman und Gloria, um Rätsel zu lösen und die gefährliche Reise vom Zoo bis in den Dschungel zu meistern.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-italy', 'NDS', 'Madagascar (Italy)', '2005', 'Action / Adventure', 'Toys for Bob', '1', 'Platform Adventure', '3D platforming and action with multiple playable characters.', 'Escape from the Central Park Zoo and reach the island of Madagascar.', 'Italian version of the classic movie adventure.', 'Gioca nei panni di Alex, Marty, Melman e Gloria nella versione italiana di Madagascar. Supera ostacoli, raccogli oggetti e sconfiggi i nemici in questa fedele trasposizione videoludica del primo capolavoro DreamWorks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-japan', 'NDS', 'Madagascar (Japan)', '2005', 'Action / Adventure', 'Toys for Bob', '1', 'Platform Adventure', '3D platforming and action with multiple playable characters.', 'Escape from the Central Park Zoo and reach the island of Madagascar.', 'Japanese version of the Madagascar movie game.', 'Madagascar (Japan) features localized text and the same fun platforming gameplay. Use the DS touch screen for character swaps and navigate through vibrant levels inspired by the global animated hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-netherlands', 'NDS', 'Madagascar (Netherlands)', '2005', 'Action / Adventure', 'Toys for Bob', '1', 'Platform Adventure', '3D platforming and action with multiple playable characters.', 'Escape from the Central Park Zoo and reach the island of Madagascar.', 'Dutch version of the classic movie adventure.', 'Help de dieren uit de Central Park Zoo te ontsnappen in Madagascar (Netherlands). Gebruik de unieke krachten van elk personage om gevaarlijke hindernissen te overwinnen en de wildernis van het eiland te bereiken.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-spain', 'NDS', 'Madagascar (Spain)', '2005', 'Action / Adventure', 'Toys for Bob', '1', 'Platform Adventure', '3D platforming and action with multiple playable characters.', 'Escape from the Central Park Zoo and reach the island of Madagascar.', 'Spanish version of the classic movie adventure.', 'Únete a Alex el león y sus amigos en Madagascar (Spain). Domina las habilidades de cada animal para escapar del zoo de Nueva York y sobrevivir a los peligros de la selva en esta divertida aventura de plataformas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-usa', 'NDS', 'Madagascar (USA)', '2005', 'Action / Adventure', 'Toys for Bob', '1', 'Platform Adventure', '3D platforming and action with multiple playable characters.', 'Escape from the Central Park Zoo and reach the island of Madagascar.', 'North American release of the movie tie-in.', 'Madagascar (USA) offers a great mix of action and humor. Switch between characters to solve puzzles, collect survival cards, and complete mini-games in this definitive handheld version of the original DreamWorks story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-2-canada', 'NDS', 'Madagascar 2 (Canada)', '2008', 'Action / Adventure', 'Beenox', '1', 'Action Adventure', 'Action-adventure platforming with touch-screen interactions.', 'Survive the savanna and reunite with the animal community.', 'Canadian release of the second Madagascar game.', 'This Canadian edition of Escape 2 Africa provides the full adventure of the Zoosters in the wild. Engage in combat, racing, and puzzle-solving across diverse African biomes in this polished handheld sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-2-france', 'NDS', 'Madagascar 2 (France)', '2008', 'Action / Adventure', 'Beenox', '1', 'Action Adventure', 'Action-adventure platforming with touch-screen interactions.', 'Survive the savanna and reunite with the animal community.', 'French version of Escape 2 Africa.', 'Explorez l''Afrique avec Alex et ses amis. Cette version propose des mini-jeux tactiles, des séquences de plateforme dynamiques et toute l''humour du second film de la franchise Madagascar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-2-germany', 'NDS', 'Madagascar 2 (Germany)', '2008', 'Action / Adventure', 'Beenox', '1', 'Action Adventure', 'Action-adventure platforming with touch-screen interactions.', 'Survive the savanna and reunite with the animal community.', 'German version of Escape 2 Africa.', 'Madagascar 2 bringt den Spaß des Kinofilms auf den DS. Meistere lustige Herausforderungen in der afrikanischen Steppe und hilf den Pinguinen beim Bau des Flugzeugs in diesem abwechslungsreichen Action-Adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-2-italy', 'NDS', 'Madagascar 2 (Italy)', '2008', 'Action / Adventure', 'Beenox', '1', 'Action Adventure', 'Action-adventure platforming with touch-screen interactions.', 'Survive the savanna and reunite with the animal community.', 'Italian version of Escape 2 Africa.', 'Torna con il cast di Madagascar in questa seconda avventura africana. Affronta mini-giochi divertenti e livelli platform stimolanti per aiutare Alex a diventare il vero re della savana.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-2-netherlands', 'NDS', 'Madagascar 2 (Netherlands)', '2008', 'Action / Adventure', 'Beenox', '1', 'Action Adventure', 'Action-adventure platforming with touch-screen interactions.', 'Survive the savanna and reunite with the animal community.', 'Dutch version of Escape 2 Africa.', 'Ga op een wild avontuur in Afrika. Gebruik de stylus van de DS om puzzels op te lossen en speel als je favoriete personages in deze vrolijke opvolger van de originele Madagascar game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-2-spain', 'NDS', 'Madagascar 2 (Spain)', '2008', 'Action / Adventure', 'Beenox', '1', 'Action Adventure', 'Action-adventure platforming with touch-screen interactions.', 'Survive the savanna and reunite with the animal community.', 'Spanish version of Escape 2 Africa.', 'Madagascar 2 (Spain) te lleva al corazón de África. Disfruta de una gran variedad de misiones, desde carreras locas hasta desafíos de sigilo con los pingüinos, todo adaptado perfectamente para la pantalla táctil de la DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-3---europes-most-wanted-europe-enfrdeesitnlru', 'NDS', 'Madagascar 3 - Europe''s Most Wanted (Europe) (En,Fr,De,Es,It,Nl,Ru)', '2012', 'Action / Adventure', 'Torus Games', '1', 'Action Adventure', 'Action-adventure with stealth, platforming, and circus mini-games.', 'Travel across Europe as a circus act to reach New York.', 'The third movie adventure featuring a European tour.', 'Madagascar 3: Europe''s Most Wanted (Europe) adds a circus twist. Play as the main cast and new friends like Gia and Vitaly, performing stunts and completing missions across famous European cities to evade Captain Chantel DuBois.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-3-usa-enfres', 'NDS', 'Madagascar 3 (USA) (En,Fr,Es)', '2012', 'Action / Adventure', 'Torus Games', '1', 'Action Adventure', 'Action-adventure with stealth, platforming, and circus mini-games.', 'Travel across Europe as a circus act to reach New York.', 'US release of the circus-themed third installment.', 'Experience the spectacle of Madagascar 3 (USA). This version features high-stakes stealth missions and colorful circus mini-games, tasking players with building the greatest traveling show in Europe to find their way home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-kartz-europe-enfrdeesitnlsv', 'NDS', 'Madagascar Kartz (Europe) (En,Fr,De,Es,It,Nl,Sv)', '2009', 'Racing', 'Sidhe Interactive', '4', 'Kart Racing', 'Kart racing with power-ups and stunt mechanics.', 'Win races across movie-themed tracks to be the kart champion.', 'High-speed racing featuring the Madagascar cast.', 'Madagascar Kartz (Europe) delivers arcade racing action. Drift through tracks inspired by the films, collect zany power-ups, and perform mid-air stunts to gain boosts in this multi-language European racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madagascar-kartz-usa-enfr', 'NDS', 'Madagascar Kartz (USA) (En,Fr)', '2009', 'Racing', 'Sidhe Interactive', '4', 'Kart Racing', 'Kart racing with power-ups and stunt mechanics.', 'Win races across movie-themed tracks to be the kart champion.', 'North American release of the Madagascar racer.', 'Get behind the wheel in Madagascar Kartz (USA). Choose from your favorite characters and karts, master the short-cuts on every track, and compete in Championship or Time Trial modes for the ultimate racing victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-06-europe', 'NDS', 'Madden NFL 06 (Europe)', '2005', 'Sports', 'Electronic Arts', '4', 'American Football', 'Sports simulation with touch-screen play-calling and passing.', 'Lead an NFL team to Super Bowl victory.', 'The first Madden NFL title for the Nintendo DS.', 'Madden NFL 06 (Europe) introduces American football to the handheld. Featuring real NFL teams and players, it uses the dual screens for strategic play-calling and a kicking meter, providing a surprisingly deep football experience on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-06-usa', 'NDS', 'Madden NFL 06 (USA)', '2005', 'Sports', 'Electronic Arts', '4', 'American Football', 'Sports simulation with touch-screen play-calling and passing.', 'Lead an NFL team to Super Bowl victory.', 'North American debut of Madden on DS.', 'Madden NFL 06 (USA) brings the gridiron to your pocket. Master the touch-screen passing mechanics and lead your favorite franchise through a full season mode, complete with detailed stats and authentic NFL playbooks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-07-europe', 'NDS', 'Madden NFL 07 (Europe)', '2006', 'Sports', 'Electronic Arts', '4', 'American Football', 'Sports simulation with updated rosters and improved graphics.', 'Win the championship in Season or Franchise mode.', 'The second Madden entry with refined controls.', 'Madden NFL 07 (Europe) improves on the foundation with smoother animations and better AI. Utilize the touch screen for pre-play adjustments and experience the intensity of professional football in this European sports release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-07-usa', 'NDS', 'Madden NFL 07 (USA)', '2006', 'Sports', 'Electronic Arts', '4', 'American Football', 'Sports simulation with updated rosters and improved graphics.', 'Win the championship in Season or Franchise mode.', 'North American release of Madden 07.', 'Madden NFL 07 (USA) features all the updated rosters and schedules for the season. With the return of Franchise mode and improved wireless multiplayer support, it''s a must-have for football fans looking for a portable fix.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-08-europe', 'NDS', 'Madden NFL 08 (Europe)', '2007', 'Sports', 'Electronic Arts', '4', 'American Football', 'Sports simulation with "Film Room" and mini-games.', 'Build a football dynasty and win the Super Bowl.', 'Feature-rich Madden entry with extra training modes.', 'Madden NFL 08 (Europe) adds depth with the Film Room and new skill-building mini-games. Manage your team’s depth chart and execute precise plays using the DS stylus in this comprehensive football simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-08-usa', 'NDS', 'Madden NFL 08 (USA)', '2007', 'Sports', 'Electronic Arts', '4', 'American Football', 'Sports simulation with "Film Room" and mini-games.', 'Build a football dynasty and win the Super Bowl.', 'North American release of Madden 08.', 'Take control of the field in Madden NFL 08 (USA). This version highlights a more intuitive kicking system and updated player stats, offering the most realistic football gameplay available on the Nintendo DS to date.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-09-europe', 'NDS', 'Madden NFL 09 (Europe)', '2008', 'Sports', 'Electronic Arts', '4', 'American Football', 'Sports simulation with "Madden IQ" and seasonal updates.', 'Prove your football knowledge and win the championship.', 'The 20th anniversary edition of the Madden series.', 'Madden NFL 09 (Europe) features the Madden IQ system to track your skill level. With updated 2009 rosters and refined passing controls, it provides a high-quality sports experience for NFL fans across the continent.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-09-usa', 'NDS', 'Madden NFL 09 (USA)', '2008', 'Sports', 'Electronic Arts', '4', 'American Football', 'Sports simulation with "Madden IQ" and seasonal updates.', 'Prove your football knowledge and win the championship.', 'North American release of the 2009 season.', 'Madden NFL 09 (USA) celebrates two decades of football excellence. Enjoy faster gameplay, updated team playbooks, and a variety of modes including 2-minute drills and a full season pursuit for the Lombardi Trophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-2005-usa', 'NDS', 'Madden NFL 2005 (USA)', '2004', 'Sports', 'Electronic Arts', '4', 'American Football', 'Sports simulation with classic playbooks and rosters.', 'Compete in NFL matches and win the 2005 season.', 'The foundational Madden experience for DS.', 'Madden NFL 2005 (USA) delivers the core football experience. Featuring the rosters of the 2004-2005 season, it uses the NDS hardware to offer a two-screen view of the field, providing a unique perspective for strategic play-calling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('made-in-ore-japan', 'NDS', 'Made in Ore (Japan)', '2007', 'Action', 'Nintendo', '1', 'Arcade', 'Creative game-design sandbox and mini-game creation.', 'Create your own "WarioWare" style micro-games and share them.', 'The "DIY" game creation tool from the WarioWare team.', 'Made in Ore (WarioWare D.I.Y.) is a powerful creative tool. Use the stylus to draw graphics, compose music, and program logic for your own 5-second micro-games, fostering a massive community of creators in this unique Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maeh-jongg-ds-germany', 'NDS', 'Maeh Jongg DS (Germany)', '2007', 'Board Game', 'Daedalic Entertainment', '4', 'Mahjong', 'Traditional tile-matching puzzle game.', 'Clear the board by matching identical Mahjong tiles.', 'Classic Mahjong experience for German players.', 'Maeh Jongg DS (Germany) offers a relaxing and traditional take on the ancient Chinese puzzle game. With various tile sets, backgrounds, and difficulty levels, it provides a portable way to sharpen your pattern recognition and strategy skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maeilmaeil---ds-dunoe-training-korea', 'NDS', 'Maeilmaeil - DS Dunoe Training (Korea)', '2007', 'Educational', 'Daesung C&C', '1', 'Brain Training', 'Brain training exercises and logic puzzles.', 'Improve your "Brain Age" through daily mental workouts.', 'Korean version of the hit Brain Age training game.', 'Maeilmaeil - DS Dunoe Training is the localized Korean edition of the famous Brain Age. It features a variety of quick-fire math, reading, and memory tests designed to stimulate the brain and calculate your mental age using the DS stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maeilmaeil-deoukdeo!---ds-dunoe-training-korea', 'NDS', 'Maeilmaeil Deoukdeo! - DS Dunoe Training (Korea)', '2008', 'Educational', 'Daesung C&C', '1', 'Brain Training', 'Advanced brain training exercises and logic puzzles.', 'Push your mental limits with more difficult brain tests.', 'Korean version of More Brain Training / Brain Age 2.', 'Maeilmaeil Deoukdeo! - DS Dunoe Training provides a fresh set of challenges for the Korean audience. This sequel includes new mini-games and mental exercises aimed at keeping the mind sharp and improving focus through consistent daily play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maer-heaven---boukyaku-no-klavier-japan', 'NDS', 'MAER Heaven - Boukyaku no Klavier (Japan)', '2006', 'RPG', 'SynergySP', '1', 'Action RPG', 'Turn-based tactical RPG based on the MÄR anime.', 'Lead Ginta and his team to victory in the War Games.', 'Tactical RPG featuring characters from MÄR Heaven.', 'MAER Heaven - Boukyaku no Klavier is a grid-based strategy game for fans of the series. Use specialized ÄRMs to cast spells and summon creatures, following an original story path within the MÄR universe on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maer-heaven---kaldea-no-akuma-japan', 'NDS', 'MAER Heaven - Kaldea no Akuma (Japan)', '2006', 'RPG', 'SynergySP', '1', 'Action RPG', 'Card-based battle RPG with adventure elements.', 'Collect powerful ÄRMs and defeat the Chess Pieces.', 'Strategic card-battling RPG based on MÄR Heaven.', 'MAER Heaven - Kaldea no Akuma features a deep battle system where players collect and trade ÄRM cards. Explore the world of MÄR, engage in tactical combat, and customize your deck to become the strongest magic user in the realm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maestro!---jump-in-music-europe-enfrdeesitnlptsvnoda', 'NDS', 'Maestro! - Jump in Music (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da)', '2008', 'Music', 'Kuju Entertainment', '1', 'Rhythm', 'Rhythm-platformer hybrid using touch-screen music notes.', 'Guide Presto through levels by "playing" the music.', 'Unique and colorful music-based platforming.', 'Maestro! - Jump in Music is a creative rhythm game where the environment is the instrument. Pluck strings, tap drums, and follow the melody on the touch screen to help a bird named Presto navigate vibrant worlds in this European multi-language hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mage-knight---destinys-soldier-usa', 'NDS', 'Mage Knight - Destiny''s Soldier (USA)', '2007', 'Strategy', 'Konami', '2', 'Strategy RPG', 'Turn-based strategy RPG based on the miniatures game.', 'Lead your army to victory in a high-fantasy war.', 'Tactical strategy RPG set in the Mage Knight universe.', 'Mage Knight: Destiny''s Soldier brings the tabletop miniatures experience to the DS. Build a custom army from various fantasy races and engage in deep, turn-based tactical combat across a long and challenging narrative campaign.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-encyclopedia-ii---moonlight-europe-enfrdenl', 'NDS', 'Magic Encyclopedia II - Moonlight (Europe) (En,Fr,De,Nl)', '2009', 'Puzzle', 'Big Fish Games', '1', 'Hidden Object', 'Hidden object adventure with puzzle-solving elements.', 'Find magical items to stop a lunar eclipse curse.', 'Enchanting hidden object game and puzzle quest.', 'Magic Encyclopedia II: Moonlight takes you on a mystical journey. Search for hidden fragments of magical artifacts, solve clever logic puzzles, and explore hand-painted European landscapes in this relaxing and atmospheric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-made-fun---perform-tricks-that-will-amaze-your-friends!-europe-enfrdeesit', 'NDS', 'Magic Made Fun - Perform Tricks That Will Amaze Your Friends! (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Icon Games', '1', 'Magic Tricks', 'Interactive tutorial and performance-based magic tricks.', 'Learn and perform magic tricks using the DS hardware.', 'Digital magic kit that teaches you real-world tricks.', 'Magic Made Fun turns your DS into a magician''s assistant. Learn the secrets behind dozens of illusions and use the DS microphone and touch screen to perform "magic" that will baffle your real-life friends and family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-roundabout-the-europe-enfrdeesitnl', 'NDS', 'Magic Roundabout, The (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Adventure', 'Blue Tongue Entertainment', '1', 'Adventure', 'Adventure and mini-game collection based on the animated film.', 'Help Dougal and his friends save the Enchanted Village.', 'Whimsical adventure based on the cult-classic show.', 'The Magic Roundabout brings the colorful world of the film to life. Participate in a variety of fun, character-driven mini-games and puzzles designed for younger players, all wrapped in a charming story about friendship and magic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-taizen-japan', 'NDS', 'Magic Taizen (Japan)', '2006', 'Fitness', 'Nintendo', '1', 'Training', 'Digital magic kit and card trick simulation.', 'Master complex card tricks to impress your audience.', 'Japanese "Master of Illusion" magic training tool.', 'Magic Taizen is a unique utility that teaches players how to perform professional-grade magic tricks. It includes a special deck of cards and uses the DS as a prop for digital illusions, making it a favorite for aspiring magicians in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-michael-pang-europe-enfrdeesit', 'NDS', 'Magical Michael Pang (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Kalisto Entertainment', '2', 'Arcade', 'Bubble-popping action with a fantasy magician theme.', 'Clear all bubbles on the screen to progress through stages.', 'Magical "Pang" style arcade action.', 'Magical Michael Pang is a modern take on the classic arcade hit. As a young wizard, you must pop bubbles of varying sizes across several international locations, using power-ups and quick reflexes in this addictive European puzzle-action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-starsign-europe-enfrdeesit', 'NDS', 'Magical Starsign (Europe) (En,Fr,De,Es,It)', '2007', 'RPG', 'Brownie Brown', '1', 'JRPG', 'Turn-based RPG with planetary exploration and magic.', 'Save your fellow students and stop an interstellar threat.', 'Stylized sci-fi RPG from the creators of Magical Vacation.', 'Magical Starsign (Europe) is a colorful and deep RPG where your magic''s power changes based on the alignment of the planets. Explore multiple worlds, master elemental combat, and enjoy a quirky, beautifully animated story with multi-language support.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-starsign-usa', 'NDS', 'Magical Starsign (USA)', '2007', 'RPG', 'Brownie Brown', '1', 'JRPG', 'Turn-based RPG with planetary exploration and magic.', 'Save your fellow students and stop an interstellar threat.', 'The North American release of the planetary RPG.', 'Journey through outer space in Magical Starsign (USA). Use the touch screen for strategic combat and spell casting, manage a team of diverse mages, and experience one of the most visually unique RPGs on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-unicorn-the-europe-frdenl', 'NDS', 'Magical Unicorn, The (Europe) (Fr,De,Nl)', '2008', 'Simulation', 'Rondomedia', '1', 'Life Simulation', 'Fantasy adventure with creature care and puzzles.', 'Help the unicorn regain its magic and save the forest.', 'Mythical creature simulation and adventure.', 'The Magical Unicorn is a gentle game for younger audiences. Care for your unicorn, solve simple puzzles, and explore a magical forest to restore peace to the kingdom in this localized European release for French, German, and Dutch speakers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-vacation---itsutsu-no-hoshi-ga-narabu-toki-japan', 'NDS', 'Magical Vacation - Itsutsu no Hoshi ga Narabu Toki (Japan)', '2001', 'RPG', 'Brownie Brown', '1', 'JRPG', 'Turn-based RPG with elemental magic and socializing.', 'Travel across five stars to save your magic academy.', 'The Japanese prequel to Magical Starsign.', 'Magical Vacation: Itsutsu no Hoshi ga Narabu Toki is a classic Brownie Brown RPG. With its signature hand-drawn art style and deep elemental magic system, it offers a grand adventure where your bonds with other students dictate your success in battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-zunou-power!!-ds-japan', 'NDS', 'Magical Zunou Power!! DS (Japan)', '2006', 'Educational', 'Bandai Namco', '1', 'Brain Training', 'Quiz and brain game based on the Japanese TV show.', 'Win high-stakes quizzes using logic and quick thinking.', 'Popular Japanese game show adaptation for NDS.', 'Magical Zunou Power!! DS challenges your intellect with a variety of brain teasers and lateral thinking puzzles. Compete against the show''s virtual contestants and prove you have the most powerful brain in this entertaining Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magicians-quest---mysterious-times-usa-enfres', 'NDS', 'Magician''s Quest - Mysterious Times (USA) (En,Fr,Es)', '2008', 'Simulation', 'Koei', '1', 'Life Simulation', 'Life simulation and RPG with magic and school life.', 'Become a master wizard while managing a magical town.', 'Magical school life sim (Animal Crossing with magic).', 'Magician''s Quest: Mysterious Times is a deep simulation where you attend classes, catch bugs, fish, and build relationships. Every week brings a "Mystery Time" event where you must use your spells to solve supernatural occurrences in this US release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magicq-ds-korea', 'NDS', 'MagicQ DS (Korea)', '2008', 'Puzzle', 'Sonata', '1', 'Logic Puzzle', 'Puzzle and logic challenge with a colorful aesthetic.', 'Solve a series of "MagicQ" themed puzzles to win.', 'Korean logic puzzle and trivia collection.', 'MagicQ DS is an engaging collection of brain games aimed at Korean players. It features a mix of memory tests, math puzzles, and logic challenges designed to be played in short bursts, making it a perfect "brain snack" for the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magische-labyrinth-das-germany', 'NDS', 'Magische Labyrinth, Das (Germany)', '2009', 'Puzzle', 'Ravensburger', '4', 'Board Game', 'Digital board game based on the award-winning toy.', 'Find the hidden symbols in the labyrinth using magnets.', 'German digital adaptation of "The Magic Labyrinth."', 'Magische Labyrinth, Das brings the innovative board game to the DS. Use your memory to navigate invisible walls and collect magical tokens, offering a unique strategic experience for families and fans of the physical board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magnetica-usa', 'NDS', 'Magnetica (USA)', '2007', 'Puzzle', 'MumboJumbo', '1', 'Action Puzzle', 'Action-puzzle game involving magnets and marble chains.', 'Prevent the marble chain from reaching the center hole.', 'Fast-paced magnetic puzzle action (Puzz Loop).', 'Magnetica is a high-energy puzzle game that uses the DS stylus to "flick" marbles. Use magnetic attraction and repulsion to create matches and clear the board in this addictive and stylish title, also known as Actionloop in other regions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mah-jong-quest---expeditions-europe-enesit', 'NDS', 'Mah Jong Quest - Expeditions (Europe) (En,Es,It)', '2007', 'Puzzle', 'MumboJumbo', '1', 'Mahjong', 'Mahjong solitaire with an adventure storyline.', 'Travel the world and restore the stolen treasures.', 'Adventure-themed Mahjong solitaire puzzle.', 'Mah Jong Quest: Expeditions (Europe) blends the classic tile-matching game with an epic quest. Solve hundreds of layouts across different continents, each with unique power-ups and challenges, to save the world of Mahjong from eternal darkness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mah-jong-quest---expeditions-europe-enfrnl', 'NDS', 'Mah Jong Quest - Expeditions (Europe) (En,Fr,Nl)', '2007', 'Puzzle', 'MumboJumbo', '1', 'Mahjong', 'Mahjong solitaire with an adventure storyline.', 'Travel the world and restore the stolen treasures.', 'Multi-language European version of Mah Jong Quest.', 'This version of Mah Jong Quest offers the same addictive tile-matching gameplay with support for English, French, and Dutch. Master the "Quests" mode or relax with "Free Play" in this comprehensive digital Mahjong experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mah-jong-quest---expeditions-usa', 'NDS', 'Mah Jong Quest - Expeditions (USA)', '2007', 'Puzzle', 'MumboJumbo', '1', 'Mahjong', 'Mahjong solitaire with an adventure storyline.', 'Travel the world and restore the stolen treasures.', 'US release of the Mahjong puzzle adventure.', 'Embark on a journey of logic and wisdom in Mah Jong Quest: Expeditions (USA). This title features cinematic storytelling, over 90 layouts, and three different ways to play, making it the definitive Mahjong experience for North American puzzle fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong---eine-reise-um-die-welt-europe-enfrdeesit', 'NDS', 'Mahjong - Eine Reise um die Welt (Europe) (En,Fr,De,Es,It)', '2008', 'Board Game', 'DTP Entertainment', '4', 'Mahjong', 'Mahjong tile-matching with a global travel theme.', 'Match tiles to "travel" through famous world cities.', 'Educational Mahjong puzzle game for Europe.', 'Mahjong: Eine Reise um die Welt (A Trip Around the World) combines traditional puzzle gameplay with interesting facts about global landmarks. Clear boards to unlock new destinations in this relaxing and culturally enriched European title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-europe-enfrdeesit', 'NDS', 'Mahjong (Europe) (En,Fr,De,Es,It)', '2007', 'Board Game', 'DTP Entertainment', '4', 'Mahjong', 'Classic Mahjong tile-matching puzzle collection.', 'Clear all tiles from the board within the time limit.', 'Standard Mahjong solitaire for the European market.', 'Mahjong (Europe) provides a clean and accessible digital version of the classic game. With multiple tile sets and dozens of layouts, it offers endless hours of relaxing gameplay for players looking for a portable mental challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-germany-ende', 'NDS', 'Mahjong (Germany) (En,De)', '2007', 'Board Game', 'DTP Entertainment', '4', 'Mahjong', 'Classic Mahjong tile-matching with German localization.', 'Solve complex tile layouts and beat high scores.', 'German-exclusive edition of the Mahjong classic.', 'This localized German version of Mahjong features refined controls and a variety of difficulty settings. It focuses on the core Mahjong experience, providing a high-quality puzzle game for German-speaking fans of the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-fight-club-ds---wi-fi-taiou-japan', 'NDS', 'Mahjong Fight Club DS - Wi-Fi Taiou (Japan)', '2009', 'Board Game', 'Konami', '4', 'Mahjong', 'Competitive online Mahjong with official pro rules.', 'Climb the ranks and become a Mahjong Master.', 'Konami''s professional Mahjong battle game.', 'Mahjong Fight Club DS is the definitive competitive Mahjong experience. Featuring Wi-Fi support, you can play against real opponents across Japan, following the official rules of the Japan Professional Mahjong Federation in this high-stakes title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-fight-club-ds---wi-fi-taiou-japan-rev-1', 'NDS', 'Mahjong Fight Club DS - Wi-Fi Taiou (Japan) (Rev 1)', '2009', 'Board Game', 'Konami', '4', 'Mahjong', 'Competitive online Mahjong with official pro rules.', 'Climb the ranks and become a Mahjong Master.', 'Revised version of the professional Mahjong sim.', 'This Revision 1 of Mahjong Fight Club DS features improved Wi-Fi stability and minor bug fixes. It continues to offer the same deep, professional-grade Mahjong gameplay that has made the franchise a staple in Japanese arcades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-haou-ds---dan-kyuu-battle-japan', 'NDS', 'Mahjong Haou DS - Dan-Kyuu Battle (Japan)', '2007', 'Board Game', 'Komodo', '4', 'Mahjong', 'Strategy Mahjong with a competitive "ranking" system.', 'Win matches to earn "Dan" and "Kyuu" ranks.', 'High-quality Mahjong simulation and ranking battle.', 'Mahjong Haou DS: Dan-Kyuu Battle focuses on the competitive ladder of Mahjong. Play against challenging AI opponents to prove your skill and climb the professional ranking system in this feature-rich Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-haou-ds-special-japan', 'NDS', 'Mahjong Haou DS Special (Japan)', '2008', 'Board Game', 'Komodo', '4', 'Mahjong', 'Enhanced Mahjong simulation with extra modes.', 'Master the game of Mahjong and win tournaments.', 'Special edition of the Mahjong Haou series.', 'Mahjong Haou DS Special includes additional features and refined AI compared to previous entries. It offers a comprehensive tutorial for beginners and a grueling "Tournament Mode" for veterans, making it one of the most complete Mahjong titles in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-journey---quest-for-tikal-usa-enfrdeesit', 'NDS', 'Mahjong Journey - Quest for Tikal (USA) (En,Fr,De,Es,It)', '2005', 'Puzzle', 'Success', '2', 'Traditional Board Game', 'Tile-matching puzzle with an archaeological theme.', 'Solve Mahjong puzzles to uncover the secrets of the Mayan city of Tikal.', 'Archaeological Mahjong adventure in ancient ruins.', 'Mahjong Journey: Quest for Tikal takes the classic solitaire gameplay to the heart of the jungle. Explore the mysteries of the Mayan civilization across five game modes and dozens of levels, featuring power-ups and stunning visual themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-navi-ds-japan', 'NDS', 'Mahjong Navi DS (Japan)', '2008', 'Educational', 'Digital Works', '1', 'Brain Training', 'Educational Mahjong guide and rulebook simulation.', 'Learn the complex rules of Japanese Riichi Mahjong.', 'Comprehensive tutorial and guide for Mahjong.', 'Mahjong Navi DS is the ultimate assistant for Mahjong players. Whether you are a beginner or looking to refine your scoring (Fu and Han), this Japanese tool provides real-time calculations, rule explanations, and practice scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-taikai-japan', 'NDS', 'Mahjong Taikai (Japan)', '2009', 'Educational', 'Digital Works', '1', 'Brain Training', 'Traditional table-top simulation with historic themes.', 'Compete against historical Japanese figures in Mahjong.', 'Koei''s classic Mahjong simulation series.', 'Mahjong Taikai brings the strategic board game to life with a unique historical twist. Face off against famous personalities from Japanese history in a realistic AI environment, featuring various tournament modes and detailed rule customization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjongg---ancient-egypt-europe-enfrdeesit', 'NDS', 'Mahjongg - Ancient Egypt (Europe) (En,Fr,De,Es,It)', '2006', 'Role-Playing Game', 'Konami', '1', 'Japanese RPG', 'Themed tile-matching solitaire puzzles.', 'Clear the board while exploring the myths of ancient Egypt.', 'Egyptian-themed Mahjong puzzle collection.', 'Mahjongg: Ancient Egypt blends classic logic gameplay with atmospheric desert visuals. Match hieroglyphic-themed tiles through challenging layouts while learning about the pharaohs and the gods of the Nile in this relaxing puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjongg---ancient-mayas-europe-enfrdeesitnl', 'NDS', 'Mahjongg - Ancient Mayas (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Role-Playing Game', 'Konami', '1', 'Japanese RPG', 'Themed tile-matching solitaire puzzles.', 'Match tiles to unlock the treasures of the Maya civilization.', 'Central American themed Mahjong solitaire.', 'Mahjongg: Ancient Mayas offers an exotic take on the tile-matching genre. Navigate through lush jungle backgrounds and stone-carved tile sets, featuring multiple game modes and an expansive campaign across the ancient Mayan empire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjongg---ancient-mayas-europe-enfrdeesit', 'NDS', 'Mahjongg - Ancient Mayas (Europe) (En,Fr,De,Es,It)', '2008', 'Music', 'Game Life', '1', 'Rhythm', 'Themed tile-matching solitaire puzzles.', 'Match tiles to unlock the treasures of the Maya civilization.', 'Multi-language European edition of Ancient Mayas.', 'This version of Mahjongg: Ancient Mayas provides localized text for French, German, Spanish, and Italian players. It features the same addictive logic gameplay with high-quality visual assets and a focus on Mayan mythology and architecture.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjongg-ds-europe-enfrdeesitnl', 'NDS', 'Mahjongg DS (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Strategy', 'Climax Studios', '1', 'Turn-Based Strategy', 'Classic tile-matching puzzle collection.', 'Solve hundreds of tile layouts in various difficulty levels.', 'Essential Mahjong solitaire for the Nintendo DS.', 'Mahjongg DS provides a sleek and straightforward puzzle experience. With a wide variety of tile sets, customizable backgrounds, and an intuitive touch-screen interface, it''s the perfect companion for fans of traditional logic games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahou-ni-kakerarete-japan', 'NDS', 'Mahou ni Kakerarete (Japan)', '2009', 'Hidden Object', 'Alawar', '1', 'Casual Puzzle', '3D adventure based on Disney''s "Enchanted."', 'Help Giselle navigate New York City and return home.', 'Magical Disney adventure based on the hit movie.', 'Mahou ni Kakerarete (Enchanted) brings the whimsical world of Disney to the DS. Switch between the 2D animated realm and 3D New York, playing through mini-games and platforming levels that follow the story of the film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mainichi-ga-tanoshii!---ayanokouji-kimimaro-no-happy-techou-japan', 'NDS', 'Mainichi ga Tanoshii! - Ayanokouji Kimimaro no Happy Techou (Japan)', '2009', 'Party', 'Hydravision', '1', 'Magic Simulation', 'Lifestyle organizer and entertainment hub.', 'Manage your daily schedule with a famous comedian''s wit.', 'Hello Kitty-style lifestyle kit featuring Ayanokouji Kimimaro.', 'Mainichi ga Tanoshii! features the humor of famous comedian Ayanokouji Kimimaro. This digital organizer includes a diary, calendar, and health tracking tools, all peppered with audio clips and jokes to brighten your daily routine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mainichi-kokorobics---kaiun-kenkyuuka-utsukita-mahiro-kanshuu---ds-uranai-happiness-2008-japan', 'NDS', 'Mainichi Kokorobics - Kaiun Kenkyuuka Utsukita Mahiro Kanshuu - DS Uranai Happiness 2008 (Japan)', '2009', 'Adventure', 'The Bitmap Brothers', '1', 'Action Adventure', 'Daily fortune-telling and luck-enhancing activities.', 'Check your daily luck and follow advice for a better 2008.', 'Personal zodiac and fortune-telling simulation.', 'Mainichi Kokorobics is a lifestyle tool focused on luck and wellness for 2008. Supervised by Mahiro Utsukita, it offers daily horoscopes, feng shui tips, and personality tests to help Japanese players improve their spiritual happiness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mainichi-shinbun-soukan-135-shuunen-project---mainichi-shinbun-1000-dai-news-japan', 'NDS', 'Mainichi Shinbun Soukan 135 Shuunen Project - Mainichi Shinbun 1000 Dai News (Japan)', '2005', 'Educational', 'Nintendo', '1', 'Brain Training', 'News archive and history trivia collection.', 'Study 135 years of global news events from the Mainichi Shimbun.', 'Digital newspaper archive and news trivia.', 'This project celebrates the 135th anniversary of the Mainichi Shimbun. It serves as a digital encyclopedia of over 1,000 major news stories, complete with quizzes and historical photos to educate players on Japanese and world history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mainichi-shinbunsha-kyouryoku---saikyou-no-kanji-drill-5-man-mon-japan', 'NDS', 'Mainichi Shinbunsha Kyouryoku - Saikyou no Kanji Drill 5-man Mon (Japan)', '2006', 'Puzzle', 'Subzero Games', '2', 'Arcade Puzzle', 'Educational Kanji practice and drill software.', 'Master over 50,000 Kanji problems through repetitive practice.', 'High-intensity Kanji training for Japanese speakers.', 'This collaboration with Mainichi Shinbunsha provides a massive database for Kanji learning. From school-level basics to advanced calligraphy, use the stylus to write and recognize characters across thousands of interactive drills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mainichi-suteki!---hello-kitty-no-life-kit-japan', 'NDS', 'Mainichi Suteki! - Hello Kitty no Life Kit (Japan)', '2007', 'Role-Playing Game', 'Brownie Brown', '1', 'Japanese RPG', 'Lifestyle utility and digital organizer with Hello Kitty.', 'Organize your life using Sanrio''s most famous character.', 'Hello Kitty themed lifestyle and productivity tool.', 'Mainichi Suteki! Hello Kitty no Life Kit turns your DS into a multifunctional organizer. It features a digital planner, calorie counter, and period tracker, all decorated with adorable Hello Kitty motifs and customizable themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mais-ou-se-cache-carmen-sandiego---mystere-au-bout-du-monde-europe-enfr', 'NDS', 'Mais Ou Se Cache Carmen Sandiego - Mystere au Bout du Monde (Europe) (En,Fr)', '2007', 'Role-Playing Game', 'Brownie Brown', '1', 'Japanese RPG', 'Mystery adventure and puzzle-solving.', 'Track down the elusive thief Carmen Sandiego across the globe.', 'Geography-based detective mystery for NDS.', 'Mais Ou Se Cache Carmen Sandiego (Where in the World is Carmen Sandiego?) tasks you with solving international crimes. Use your knowledge of geography and history to follow clues and catch the world''s most famous thief.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maji-de-manabu---lec-de-ukaru---ds-hisho-kentei-2-kyuu---3-kyuu-japan', 'NDS', 'Maji de Manabu - LEC de Ukaru - DS Hisho Kentei 2-kyuu - 3-kyuu (Japan)', '2009', 'Adventure', 'Big Blue Bubble', '1', 'Casual Adventure', 'Educational study aid for secretarial certification.', 'Pass the Level 2 and 3 Secretarial Exams through mock tests.', 'Official LEC study guide for secretarial skills.', 'Maji de Manabu: DS Hisho Kentei is a comprehensive training tool for the Japanese Secretarial Proficiency Test. It includes thousands of practice questions and interactive lessons on business etiquette and administrative tasks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maji-de-manabu---lec-de-ukaru---ds-kikenbutsu-toriatsukaisha-otsushu-4-rui-japan', 'NDS', 'Maji de Manabu - LEC de Ukaru - DS Kikenbutsu Toriatsukaisha Otsushu 4 Rui (Japan)', '2005', 'Role-Playing Game', 'Brownie Brown', '1', 'Japanese RPG', 'Educational study aid for hazardous materials handling.', 'Prepare for the Category 4 Hazardous Materials Operator exam.', 'Specialized vocational training for industrial safety.', 'This LEC training tool focuses on the Otsushu 4 Rui certification. It provides structured study plans and simulated exams to help Japanese users master the safety protocols required for handling flammable liquids and chemicals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maji-de-manabu---lec-de-ukaru---ds-koumuin-shiken---suuteki-shori-japan', 'NDS', 'Maji de Manabu - LEC de Ukaru - DS Koumuin Shiken - Suuteki Shori (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Brain Training', 'Educational study aid for the Civil Service exam.', 'Master "Numerical Processing" logic for government entrance.', 'Advanced logic and math trainer for civil servants.', 'Maji de Manabu: DS Koumuin Shiken targets the difficult numerical reasoning section of the Japanese civil service exam. It offers step-by-step logic solutions and timed tests to build speed and accuracy for job seekers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maji-de-manabu---lec-de-ukaru---ds-nisshou-boki-3-kyuu-japan', 'NDS', 'Maji de Manabu - LEC de Ukaru - DS Nisshou Boki 3-kyuu (Japan)', '2008', 'Life Simulation', 'Konami', '1', 'Social Simulation', 'Educational study aid for bookkeeping certification.', 'Learn Level 3 Nisshou Boki accounting and bookkeeping.', 'Financial accounting and bookkeeping study tool.', 'This title provides a structured curriculum for the Nisshou Boki Level 3 exam. Use the stylus to solve balance sheets and ledger entries, featuring audio explanations and progress tracking for aspiring Japanese accountants.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maji-de-manabu---lec-de-ukaru---ds-takuchi-tatemono-torihiki-shuninsha---2011-nen-&-2012-nendo-ban-japan', 'NDS', 'Maji de Manabu - LEC de Ukaru - DS Takuchi Tatemono Torihiki Shuninsha - 2011 Nen & 2012 Nendo Ban (Japan)', '2007', 'Puzzle', 'ThinkArts', '1', 'Logic Puzzle', 'Educational study aid for real estate certification.', 'Study for the 2011/2012 Real Estate Broker exams.', 'Specialized legal training for Japanese real estate.', 'Maji de Manabu: DS Takuchi Tatemono focuses on the "Takken" exam. It features updated laws and practice questions for the 2011/2012 period, helping users navigate complex property laws and transaction regulations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maji-de-manabu---lec-de-ukaru---ds-takuchi-tatemono-torihiki-shuninsha-japan', 'NDS', 'Maji de Manabu - LEC de Ukaru - DS Takuchi Tatemono Torihiki Shuninsha (Japan)', '2009', 'Puzzle', 'Tivola', '1', 'Labyrinth Puzzle', 'Educational study aid for real estate certification.', 'Learn the fundamentals of real estate brokerage and laws.', 'Professional certification trainer for real estate brokers.', 'This LEC series entry helps students prepare for the Real Estate Transaction Specialist exam. It features a massive database of past exam questions and interactive flashcards to ensure a deep understanding of Japanese housing laws.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majime-ni-fumajime---kaiketsu-zorori---kyoufu-no-takarabako-japan', 'NDS', 'Majime ni Fumajime - Kaiketsu Zorori - Kyoufu no Takarabako (Japan)', '2009', 'Puzzle', 'Melesta Games', '2', 'Arcade Puzzle', 'Side-scrolling action-adventure based on the anime.', 'Help Zorori find the legendary treasure and evade traps.', 'Humorous action-adventure based on the popular manga.', 'Majime ni Fumajime follows the mischievous fox Zorori in a quest for a mysterious treasure box. Solve environmental puzzles and engage in platforming action across levels that capture the humor and art style of the beloved series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majin-tantei-nougami-neuro---neuro-to-yako-no-bishoku-zanmai---suiri-tsuki---gourmet-&-mystery-japan', 'NDS', 'Majin Tantei Nougami Neuro - Neuro to Yako no Bishoku Zanmai - Suiri Tsuki - Gourmet & Mystery (Japan)', '2008', 'Puzzle', 'iWin', '1', 'Mahjong Puzzle', 'Investigative mystery with culinary mini-games.', 'Solve supernatural crimes while satisfying Neuro''s hunger.', 'Mystery-adventure based on the hit manga.', 'Majin Tantei Nougami Neuro blends detective work with high-stakes interrogation. Use Yako''s gourmet knowledge and Neuro''s demonic powers to solve murders through interactive "Gourmet & Mystery" gameplay and deduction puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majo-ni-naru-japan', 'NDS', 'Majo ni Naru. (Japan)', '2008', 'Puzzle', 'iWin', '1', 'Mahjong Puzzle', 'Magical life simulation and RPG.', 'Train to become a full-fledged witch through various trials.', 'Witchcraft-themed RPG with social elements.', 'Majo ni Naru (Becoming a Witch) is a charming adventure where you learn spells and interact with townspeople. Balance your magical studies with daily tasks and explore a hand-drawn world as you grow from a novice into a powerful witch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('major-ds---dream-baseball-japan', 'NDS', 'Major DS - Dream Baseball (Japan)', '2009', 'Puzzle', 'iWin', '1', 'Mahjong Puzzle', 'Sports simulation based on the "Major" anime.', 'Lead Goro Honda and his team to the high school championship.', 'High-stakes baseball drama based on the hit manga.', 'Major DS: Dream Baseball brings the intense baseball action of the series to the DS. Use the touch screen to pitch and hit, relive iconic moments from the story, and manage your team’s roster to win the dream title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('major-league-baseball-2k10-usa', 'NDS', 'Major League Baseball 2K10 (USA)', '2008', 'Puzzle', 'DTP Entertainment', '1', 'Traditional Board Game', 'Realistic baseball simulation with updated rosters.', 'Win the World Series through strategic management and play.', 'The 2010 edition of 2K Sports'' baseball franchise.', 'Major League Baseball 2K10 features a refined "Total Control" pitching and hitting system. With the most accurate rosters of the season and a deep Franchise mode, it''s the definitive portable baseball experience for MLB fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('major-league-baseball-2k7-usa', 'NDS', 'Major League Baseball 2K7 (USA)', '2005', 'Puzzle', 'Destination Software', '1', 'Traditional Board Game', 'Realistic baseball simulation with official licenses.', 'Take your favorite team to the top of the standings.', 'The first 2K baseball title for the Nintendo DS.', 'Major League Baseball 2K7 provides an authentic MLB experience. Use the dual screens to manage your fielding and batting, featuring real players, stadiums, and an intuitive control scheme that brings the big leagues to your pocket.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('major-league-baseball-2k8---fantasy-all-stars-usa-enfres', 'NDS', 'Major League Baseball 2K8 - Fantasy All-Stars (USA) (En,Fr,Es)', '2005', 'Puzzle', 'Destination Software', '1', 'Traditional Board Game', 'Stylized arcade baseball with power-ups and fantasy elements.', 'Win the championship with super-powered versions of MLB stars.', 'Over-the-top arcade baseball with stylized graphics.', 'MLB 2K8: Fantasy All-Stars trades realism for fun. Execute "power swings" and "fire balls" in stylized stadiums, featuring caricatured versions of real MLB pros and accessible, fast-paced gameplay for casual sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('major-league-baseball-2k9---fantasy-all-stars-usa-enfres', 'NDS', 'Major League Baseball 2K9 - Fantasy All-Stars (USA) (En,Fr,Es)', '2009', 'Board Game', 'Koei', '4', 'Japanese Mahjong', 'Stylized arcade baseball with power-ups and fantasy elements.', 'Outplay your rivals using special abilities and power-ups.', 'The fantasy-focused sequel to MLB 2K8.', 'Major League Baseball 2K9: Fantasy All-Stars returns with even more power-ups and bizarre stadiums. Choose your All-Star team and use the touch screen to activate game-changing abilities in this high-energy, non-traditional baseball sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('makai-senki-disgaea---makai-no-ouji-to-akai-tsuki-japan', 'NDS', 'Makai Senki Disgaea - Makai no Ouji to Akai Tsuki (Japan)', '2009', 'Board Game', 'Koei', '4', 'Japanese Mahjong', 'Tactical RPG with grid-based combat and monster recruitment.', 'Help Prince Laharl reclaim his throne in the Netherworld.', 'Port of the legendary strategy RPG Disgaea.', 'Makai Senki Disgaea (Disgaea DS) brings the "million points of damage" series to the handheld. Featuring a dual-screen layout for better battlefield overview, recruit monsters, use the Geo Effect system, and grind to level 9999 in this epic RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('make-10---a-journey-of-numbers-europe-enfrdeesit', 'NDS', 'Make 10 - A Journey of Numbers (Europe) (En,Fr,De,Es,It)', '2007', 'Board Game', 'Compile Heart', '1', 'Japanese Mahjong', 'Mathematical puzzle game based on the number 10.', 'Solve various arithmetic puzzles where the goal is always 10.', 'Innovative and fun math-based puzzle quest.', 'Make 10: A Journey of Numbers is a whimsical puzzle game from Nintendo. Explore a strange world and talk to "Number Pixies" while solving touch-screen math drills that require you to add numbers up to 10 in clever ways.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('make-up-paradise-korea', 'NDS', 'Make-up Paradise (Korea)', '2009', 'Simulation', 'Tivola', '1', 'Fashion Simulation', 'Fashion and beauty simulation.', 'Master the art of makeup and styling to win competitions.', 'Korean localized version of the makeup sim.', 'Make-up Paradise allows players to experiment with countless beauty products. Use the stylus to apply eyeshadow, lipstick, and blush, managing a salon and helping clients find their perfect look for various social events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('makeup-princess-korea', 'NDS', 'Makeup Princess (Korea)', '2009', 'Simulation', 'Tivola', '1', 'Fashion Simulation', 'Princess-themed fashion and makeup simulation.', 'Help the princess look her best for the royal ball.', 'Korean beauty and fashion simulation for young girls.', 'Makeup Princess focuses on the royal aesthetic. Choose from elegant gowns, sparkling jewelry, and a wide array of cosmetics to transform your character into a stunning princess, featuring creative touch-screen gameplay and vibrant art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('malediction-de-toutankhamon-la---enigmes-&-objets-caches-france', 'NDS', 'Malediction de Toutankhamon, La - Enigmes & Objets Caches (France)', '2010', 'Hidden Object', 'Mac Games', '1', 'Hidden Object Adventure', 'Hidden object adventure with puzzle-solving.', 'Break the curse of King Tutankhamun by finding hidden relics.', 'Egyptian-themed hidden object mystery in French.', 'La Malédiction de Toutankhamon (France) sumerge a los jugadores en una investigación arqueológica. Encuentra objetos ocultos en escenarios detallados del antiguo Egipto, resuelve acertijos de lógica y desvela los secretos del faraón en este título de misterio para NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mallangmallang-dunoegyosil-korea', 'NDS', 'Mallangmallang Dunoegyosil (Korea)', '2008', 'Educational', 'Digital Works', '1', 'Brain Training', 'Brain training exercises and logic puzzles.', 'Improve cognitive speed and memory with colorful mini-games.', 'Korean version of Big Brain Academy.', 'Mallangmallang Dunoegyosil es la versión coreana del popular Big Brain Academy. Desafía tu mente en cinco categorías diferentes: lógica, memoria, análisis, cálculo y formas, ideal para jugadores de todas las edades que buscan agilidad mental rápida.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mamegoma---honobono-nikki-japan', 'NDS', 'Mamegoma - Honobono Nikki (Japan)', '2009', 'Simulation', 'Namco Bandai', '1', 'Casual Life Simulation', 'Virtual pet simulation with a baby seal.', 'Care for a cute Mamegoma seal and keep a daily diary.', 'Adorable baby seal raising simulation.', 'Mamegoma: Honobono Nikki te permite adoptar a una de las famosas focas bebé de San-X. Aliméntala, báñala y juega con ella mientras registras su crecimiento en un diario virtual lleno de ternura y estética kawaii japonesa.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mamegoma-2---uchi-no-ko-ga-ichiban!-japan', 'NDS', 'Mamegoma 2 - Uchi no Ko ga Ichiban! (Japan)', '2010', 'Simulation', 'Namco Bandai', '1', 'Casual Life Simulation', 'Virtual pet simulation with breeding and contests.', 'Raise the best Mamegoma seal and win local competitions.', 'The second installment of the cute seal series.', 'Mamegoma 2: Uchi no Ko ga Ichiban! mejora la experiencia de crianza con más tipos de focas y accesorios. Participa en concursos de belleza y talento, y utiliza la pantalla táctil para acariciar y entrenar a tu mascota favorita en este éxito japonés.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mamegoma-3---kawaii-ga-ippai!-japan', 'NDS', 'Mamegoma 3 - Kawaii ga Ippai! (Japan)', '2011', 'Simulation', 'Namco Bandai', '1', 'Casual Life Simulation', 'Virtual pet simulation with expanded customization.', 'Collect all varieties of Mamegoma and decorate their habitat.', 'The third and most complete Mamegoma pet sim.', 'Mamegoma 3: Kawaii ga Ippai! ofrece una cantidad masiva de objetos de personalización. Disfruta de nuevos mini-juegos y una interacción más profunda con las focas en un entorno relajante, perfecto para los fans del coleccionismo y lo adorable.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('manepa-1000-mannin-no-fx-training-japan', 'NDS', 'Manepa 1000 Mannin no FX Training (Japan)', '2008', 'Educational', 'Capcom', '1', 'Financial Training', 'Educational financial simulation and FX trading.', 'Learn the basics of Forex trading and manage virtual capital.', 'Forex trading trainer for Japanese users.', 'Manepa 1000 Mannin no FX Training es una herramienta educativa sobre el mercado de divisas. Practica estrategias de inversión en tiempo real con datos simulados, aprende terminología financiera y mejora tus habilidades de trading sin riesgo de perder dinero real.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('manga-ka-debut-monogatari-ds---akogare!-manga-ka-ikusei-game-japan', 'NDS', 'Manga-ka Debut Monogatari DS - Akogare! Manga-ka Ikusei Game (Japan)', '2008', 'Simulation', 'Konami', '1', 'Career Simulation', 'Life simulation and career management.', 'Rise from a novice artist to a professional Manga-ka.', 'Manga creator career simulation and training.', 'Manga-ka Debut Monogatari DS te pone en la piel de un dibujante de cómics. Gestiona tu tiempo entre dibujar páginas, reunirte con editores y mejorar tus habilidades artísticas usando el lápiz táctil como si fuera una pluma profesional.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('manga-ka-debut-monogatari-ds---akogare!-manga-ka-ikusei-game-japan-rev-1', 'NDS', 'Manga-ka Debut Monogatari DS - Akogare! Manga-ka Ikusei Game (Japan) (Rev 1)', '2008', 'Simulation', 'Konami', '1', 'Career Simulation', 'Life simulation and career management.', 'Rise from a novice artist to a professional Manga-ka.', 'Revised version of the manga creator simulation.', 'Esta Rev 1 de Manga-ka Debut Monogatari DS incluye ajustes de jugabilidad y correcciones menores. Sigue el camino del éxito en la industria del manga japonés, equilibrando tu vida social con el duro trabajo de entregar capítulos a tiempo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('manjyeora---made-in-wario-korea', 'NDS', 'Manjyeora - Made in Wario (Korea)', '2007', 'Action', 'Nintendo', '4', 'Microgame Collection', 'High-speed micro-games using touch and mic controls.', 'Complete hundreds of 5-second tasks to defeat the boss.', 'Korean version of WarioWare Touched!', 'Manjyeora: Made in Wario es la divertidísima versión coreana de WarioWare. Usa el stylus para picar, frotar y arrastrar en una serie frenética de micro-juegos absurdos que aprovechan al máximo todas las funciones de la Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maplestory-ds-korea', 'NDS', 'MapleStory DS (Korea)', '2010', 'Role-Playing Game', 'Nexon', '1', 'Action RPG', 'Side-scrolling action RPG with character classes.', 'Explore the Maple World and defeat the Dark Mage.', 'Portable adaptation of the popular Korean MMORPG.', 'MapleStory DS traslada la magia del RPG online a una aventura de un solo jugador. Elige entre cuatro clases únicas, sube de nivel, recolecta equipo y vive una historia épica con el estilo artístico vibrante que caracteriza a esta franquicia coreana.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('march-of-the-penguins-europe-enfrdeesit', 'NDS', 'March of the Penguins (Europe) (En,Fr,De,Es,It)', '2007', 'Adventure', 'DTI Games', '1', 'Narrative Adventure', 'Lemmings-style puzzle game with penguins.', 'Lead a group of penguins safely through icy obstacles.', 'Puzzle adventure based on the award-winning documentary.', 'March of the Penguins (Europe) te reta a guiar a las colonias de pingüinos emperador. Usa el entorno para protegerlos de depredadores y el clima extremo en una serie de niveles de lógica que requieren planificación y reflejos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('march-of-the-penguins-usa', 'NDS', 'March of the Penguins (USA)', '2007', 'Adventure', 'DTI Games', '1', 'Narrative Adventure', 'Lemmings-style puzzle game with penguins.', 'Lead a group of penguins safely through icy obstacles.', 'US release of the penguin-themed puzzle game.', 'Follow the epic journey of the Emperor penguins in March of the Penguins (USA). Navigate through 12 levels based on the film, using the DS stylus to build bridges or clear paths to ensure the survival of the flock.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('margots-bepuzzled!-europe-enfrdeesit', 'NDS', 'Margot''s Bepuzzled! (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Compile Heart', '1', 'Logic Puzzle', 'Puzzle collection featuring multiple logic games.', 'Solve diverse puzzles to unlock high scores and achievements.', 'Compilation of brain teasers and logic puzzles.', 'Margot''s Bepuzzled! ofrece una variedad de juegos clásicos como Sudoku, crucigramas y rompecabezas de palabras. Ideal para sesiones de juego cortas, este título europeo pone a prueba tu agilidad mental con una interfaz limpia y accesible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('margots-word-brain-europe-enfrdeesit', 'NDS', 'Margot''s Word Brain (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Compile Heart', '1', 'Word Puzzle', 'Word-based puzzle game with multiple modes.', 'Solve word searches and anagrams to boost your vocabulary.', 'Challenging word game collection for Europe.', 'Margot''s Word Brain es el desafío definitivo para los amantes de las letras. Incluye seis modos de juego diferentes que pondrán a prueba tu capacidad de deletreo y asociación de palabras bajo presión de tiempo en varios idiomas europeos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('margots-word-brain-usa-enfres', 'NDS', 'Margot''s Word Brain (USA) (En,Fr,Es)', '2009', 'Educational', 'Compile Heart', '1', 'Word Puzzle', 'Word-based puzzle game with multiple modes.', 'Solve word searches and anagrams to boost your vocabulary.', 'North American release of the word puzzle trainer.', 'Test your vocabulary with Margot''s Word Brain (USA). Use the touch screen to find hidden words and solve complex linguistic puzzles. Es una herramienta excelente tanto para entretenerse como para mejorar el vocabulario y la velocidad mental.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marie-&-gali-no-lets-science-japan', 'NDS', 'Marie & Gali no Let''s Science (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Science Education', 'Educational mini-games with a science theme.', 'Learn scientific principles through experiments and quizzes.', 'Science-learning adventure based on the anime characters.', 'Marie & Gali no Let''s Science hace que aprender física y química sea divertido. Acompaña a Marie y al científico Gali en una serie de retos educativos basados en la serie de TV, diseñados para despertar la curiosidad científica en los niños.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marie-antoinette-and-the-american-war-of-independence---episode-1---the-brotherhood-of-the-wolf-europe-enfrdeesit', 'NDS', 'Marie-Antoinette and the American War of Independence - Episode 1 - The Brotherhood of the Wolf (Europe) (En,Fr,De,Es,It)', '2011', 'Adventure', 'Funbox Media', '1', 'Historical Adventure', 'Hidden object mystery with historical fiction elements.', 'Investigate a conspiracy during the American Revolution.', 'Historical mystery adventure set in the 18th century.', 'Marie-Antoinette and the American War of Independence es una aventura de búsqueda de objetos únicos. Explora la corte francesa y los campos de batalla coloniales mientras resuelves intrigas políticas en este primer episodio de la saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-&-luigi---partners-in-time-hard-mode-10', 'NDS', 'Mario & Luigi - Partners in Time Hard Mode 1.0', '2005', 'Role-Playing Game', 'AlphaDream', '1', 'Japanese RPG', 'Puzzle-platformer RPG with turn-based combat.', 'Travel back in time to rescue Princess Peach from the Shroobs.', 'Fan-made hard mode of the classic Mario & Luigi RPG.', 'Mario & Luigi: Partners in Time Hard Mode 1.0 es una modificación que eleva drásticamente la dificultad del juego original. Enfrenta enemigos más fuertes y jefes con nuevas estrategias en este desafío diseñado para expertos de la saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-&-luigi-rpg---siganui-partner-korea', 'NDS', 'Mario & Luigi RPG - Siganui Partner (Korea)', '2005', 'Role-Playing Game', 'AlphaDream', '1', 'Japanese RPG', 'Puzzle-platformer RPG with turn-based combat.', 'Travel back in time to rescue Princess Peach from the Shroobs.', 'Korean version of Partners in Time.', 'Mario & Luigi RPG: Siganui Partner es la localización coreana oficial de esta aventura temporal. Controla a Mario, Luigi y sus versiones bebés simultáneamente para resolver puzzles cooperativos y ejecutar ataques tándem espectaculares.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-kart-0', 'NDS', 'Mario Kart 0', '2005', 'Racing', 'Nintendo', '4', 'Arcade Racing', 'Kart racing with power-ups and drifting.', 'Win races and battle in high-speed go-kart matches.', 'Rare/Beta version or homebrew mod of Mario Kart DS.', 'Mario Kart 0 representa una curiosidad para coleccionistas y fans de la escena homebrew. Ofrece una experiencia de carreras arcade clásica con los personajes de Nintendo, centrada en la velocidad pura y la competición en circuitos icónicos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-kart-ds---ctgp-nitro-100', 'NDS', 'Mario Kart DS - CTGP Nitro 1.0.0', '2008', 'Racing', 'Custom Team', '4', 'Arcade Racing', 'Kart racing with massive custom track support.', 'Compete in races featuring tracks from across the Mario series.', 'Comprehensive custom track mod for Mario Kart DS.', 'Mario Kart DS: CTGP Nitro 1.0.0 es una de las modificaciones más ambiciosas de la comunidad. Añade decenas de pistas nuevas, música personalizada y mejoras visuales, expandiendo el contenido del juego original de forma masiva.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-kart-ds-europe-demo-kiosk', 'NDS', 'Mario Kart DS (Europe) (Demo) (Kiosk)', '2005', 'Racing', 'Nintendo', '4', 'Arcade Racing', 'Kart racing demo version for retail kiosks.', 'Experience a limited selection of tracks and characters.', 'Rare retail kiosk demo for Nintendo DS.', 'Esta versión Demo de Mario Kart DS se utilizaba en tiendas para promocionar la consola. Incluye una selección limitada de copas y corredores, permitiendo probar las mecánicas de derrape y el multijugador inalámbrico antes del lanzamiento oficial.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-kart-ds-n64-circuit', 'NDS', 'Mario Kart DS N64 Circuit', '2005', 'Racing', 'Nintendo', '4', 'Arcade Racing', 'Kart racing focusing on retro N64 tracks.', 'Race through faithfully recreated tracks from the N64 era.', 'Homebrew track pack featuring classic N64 circuits.', 'Mario Kart DS N64 Circuit es una modificación que se centra en la nostalgia. Reconstruye pistas legendarias de Mario Kart 64 con el motor de DS, permitiendo revivir circuitos como Yoshi Valley o Royal Raceway en formato portátil.');